window.POEM_DB=window.POEM_DB||{};POEM_DB["yuan_003"]={"n":"张翥","dyn":"元","poems":[{"t":"冯秀才伯学以丹青小景山水求题","f":"五言律诗","c":["沙禽毛羽新，来往采桑津。","野水碧于草，桃花红照人。","徘徊远山暮，窈窕江南春。","芳思不可极，悠然怀钓纶。"]},{"t":"七忆 其六 忆吴兴","f":"七言律诗","c":["忆汎苕华溪上船，故人为我重留连。","半山塔寺藏云树，绕郭楼台住水天。","白榜载歌明月里，青帘沽酒画桥边。","计筹山下先茔在，欲往浇松定几年。"]},{"t":"七忆 其四 忆维扬","f":"七言律诗","c":["蜀冈东畔竹西楼，十五年前烂漫游。","岂意繁华今劫火，空怀歌吹古扬州。","亲朋未报何人在，战伐宁知几日休。","惟有满襟狼藉泪，何时归洒大江流。"]},{"t":"听松轩为丹丘杜高士作","f":"七言律诗","c":["长松千树拥前荣，虚籁还从树底鸣。","一片海涛云杪堕，几番山雨月中生。","茶香夜煮苓泉活，琴思秋翻鹤帐清。","安得南华老仙伯，相随轩上说风声。"]},{"t":"郡楼晚望览临武堂故基","f":"七言律诗","c":["全晋山川气象开，满城烟树拥层台。","土风旧有尧时俗，人物今无楚国材。","千嶂晚云原上合，两河秋色雁边来。","昔贤胜赏今陈迹，落日登临画角哀。"]},{"t":"闻归集贤远引奉简一章","f":"七言律诗","c":["故旧相看逐逝波，思归无路欲如何。","将军每叹檀公策，朝士徒悲穆氏歌。","南海明珠来贡少，中原健马出征多。","先生自说将高举，不遣冥鸿到罻罗。"]},{"t":"秦淮晚眺","f":"七言律诗","c":["赤栏桥下暮潮空，远火疏舂晻霭中。","新月半天分落照，断云千里附归鸿。","严城鼓角秋声早，故国山川王气终。","莫讶时来一长望，越吟荆赋思无穷。"]},{"t":"人雁吟（悯饥也）二章 其一","f":"七言古诗","c":["雁飞渡江谋稻粱，江人趁熟亦渡江。","雁下江中唼蘋藻，人饥尽属江中央。","天长水阔罗网多，无衣无食可奈何？","人声未断雁声起，弃儿呱呱道傍死。","不见雁春还北飞，人今去此将何之？","叹息人穷不如鸟，何日相随如雁归。"]},{"t":"范宽山水","f":"曲","c":["忆昔往寻剡中山，南明天姥相萦盘。","客路上头穿鸟道，行人脚底踏风湍。","旦寒露重多成雨，泄雾濛云互吞吐。","仆夫相呼岩谷间，空响应人作人语。","溪穷岸断地忽平，石门壁立如削成。","隔水无数山花明，中有人家鸡犬声。","向来老眼曾到处，此境俱作桃源行。","百年留在范宽笔，水墨精神且萧瑟。","上有翰林学士之院章，恐是宣和旧时物。","林?野鹤应自在，令我相见犹前日。","时平会乞閒身归，一壑得专吾事毕。"]},{"t":"一枝春 闹蛾","f":"曲","c":["雾翅烟须，向云窗斗巧，宫罗轻剪。","翩翩鬓影，侧映宝钗双燕。","银丝蜡蒂，弄春色、一枝娇颤。","谁网得、金玉飞钱，结成翠羞红怨。","灯街上元又见。","闹春风簇定，冠儿争转。","偷香傅粉，尚忆去年人面。","妆楼误约，定何处、为花留恋。","应化作、晓梦寻郎，采芳径远。"]},{"t":"八声甘州","f":"曲","c":["向芙蓉湖上驻兰舟，凄凉胜游稀。","但西泠桥外，北山堤畔，残柳依依。","追忆莺花旧梦，回首冷烟霏。","惟有盟鸥好，时傍人飞。","听取红筵象板，尽歌回彩扇，舞换仙衣。","正白萍风急，吹雨暗斜晖。","空惆怅、离怀未展，更酒边、忍又送将归。","江南客、此生心事，只在渔矶。"]},{"t":"丹凤吟 幺凤","f":"曲","c":["蓬莱花鸟。","记并宿苔枝，双双娇小。","海上仙姝，唤起绿衣歌笑。","芳丛有时遣探听，东风数声啼晓。","月下人归，凄凉梦醒，怅愁多欢少。","念故巢犹在瘴云杪。","甚闭入雕笼，庭院深悄。","信断羁雌远镇怨索绕。","翠襟近来渐短，看梅花又还开了。","纵解收香寄与，柰罗浮春杳。"]},{"t":"六州歌头 孤山寻梅","f":"曲","c":["孤山岁晚，石老树查牙。","逋仙去。","谁为主。","自疏花。","破冰芽。","乌帽骑驴处。","近修竹，侵荒藓，知几度。","踏残雪，趁晴霞。","空谷佳人，独耐朝寒峭，翠袖笼纱。","甚江南江北，相忆梦魂赊。","水绕云遮。","思无涯。","又苔枝上，香痕沁，幺凤语。","冻蜂衙。","瀛屿月，偏来照，影横斜。","瘦争些。","好约寻芳客，问前度，那人家。","重呼酒。","摘琼朵。","插鬓鸦。","唤起春娇扶醉，休孤负锦瑟年华。","怕流芳不待，回首易风沙。","吹断城笳。"]},{"t":"凤凰台上忆吹箫 听沈野云吹箫醉后有赋","f":"曲","c":["琪树锵鸣，春冰碎落，玉盘珠泻还停。","渐一丝风袅，悠扬青冥。","疑把红牙趁节，想有人、记豆银屏。","何须数，琵琶汉女，锦瑟湘灵。","追思旧时胜赏，醉几度西湖，山馆池亭。","惯依歌花月，按舞娉婷。","岁晚相逢客里，且一尊、同慰漂零。","君休惜，吴音朔调，尽与吹听。"]},{"t":"太常引","f":"曲","c":["素娥风韵自天真。","似回首、趁行云。","眉黛任长颦。","正宜看、啼妆未匀。","扇犀轻按，袖罗低掩，一曲广陵春。","飞尽画梁尘。","曾数到、梨园几人。"]},{"t":"忆旧游 重到金陵","f":"曲","c":["怅麟残废井，凤去荒台。","烟树敧斜。","再到登临处，渺秦淮自碧，目断云沙。","后庭谩有遗曲，玉树已无花。","向宛寺裁诗，江亭把酒，暗换年华。","双双旧时燕，问巷陌归来，王谢谁家。","自昔西州泪，等生存零落，何事兴嗟。","庾郎似我憔悴，回首又天涯。","但满耳西风，关河冷落凝暮笳。"]},{"t":"忆秦娥","f":"曲","c":["金杯侧。","东风易醉多情客。","多情客。","送君南浦，送春南陌。","落花巧妒罗裙色。","舞红变尽休轻拆。","休轻拆。","待他归看，旧时宽窄。"]},{"t":"忆秦娥","f":"曲","c":["江南北。","金鞍一去空消息。","空消息。","鸡声月店，雁声霜驿。","春醪谁道浓无滴。","十分满引浑无力。","浑无力。","离愁如海，怎生乾得。"]},{"t":"木兰花慢 次韵陈见心文学孤山问梅","f":"曲","c":["压西湖千树，曾几度，为携尊。","向柳外停桡，苔边待鹤，酒熟诗温。","瀛洲旧时月色，怅荒凉、惟有数枝存。","天上梨花成梦，江南桃叶移根。","如今憔悴客愁村。","难返暗香魂。","甚岁晚春迟，角寒笛晓，雪暗云昏。","登临不甚寄目，但青山、隐隐月纷纷。","再约与君同醉，从他啄木敲门。"]},{"t":"木兰花慢 题红犀扇面","f":"曲","c":["记西湖送别，曾共绾，绿杨丝。","怅水去云回，佳期杳渺，远梦参差。","重来访邻寻里，爱卿卿、不减旧风姿。","不着银筝清怨，难题纨扇相思。","暗香销尽合欢枝。","留在锦囊诗。","又越北闽南，秋随雁影，花老莺儿。","应缘采春情重，便鉴湖、春色恋微之。","扶起晓窗残醉，潮平月落多时。"]},{"t":"水龙吟 郑兰玉赋蜡梅，工甚，予拾其遗意补之","f":"曲","c":["玉人栀貌堪怜，晓妆一洗铅华尽。","此花应是，菊分颜色，梅分风韵。","萼点驼酥，口攒金磬，心凝檀粉。","甚女贞染就，仙女绝胜，蜂儿童，鹅儿嫩。","说与玉龙莫品，怕宫波、一般流浪。","故人堪寄，折枝代取，江南春信。","沉水全熏，檗丝密缀，额黄深晕。","乍燕姬未识，是花是蜡，笑偎人问。"]},{"t":"水龙吟 听房氏自然歌，求词为赋","f":"曲","c":["春风琼树香中，数声恰似流莺啭。","歌尘飞下，落花起舞，骊珠脱串。","豆蔻珠帘，牡丹雪岭，小桃人面。","是自然绝艺，天然书谱，霓裳序，六幺遍。","独占二分月色，向尊前、几番曾见。","赏音如此，不辞醉墨，为题纨扇。","浪雨闲云，剩香残黛，莫论恩怨。","看秾华又老，情缘未断，寄楼中燕。"]},{"t":"水龙吟 广陵送客，次郑兰玉赋蓼花韵","f":"曲","c":["芙蓉老去妆残，露华滴尽珠盘泪。","水天潇洒，秋容冷淡，凭谁点缀。","瘦苇黄边，疏萍白外，满汀烟穟。","把余妍分与，西风染就，犹堪爱，红芳媚。","几度临流送远，向花前、偏惊客意。","船窗雨后，数枝低人，香零粉碎。","不见当年，秦淮花月，竹西歌吹。","但此时此处，丛丛满眼，伴离人醉。"]},{"t":"水龙吟 次韵王本中赋楼子芍药","f":"曲","c":["宝楼十二玲珑，仙家只在云间住。","金盘舞罢，罗裙襞皱，乘风欲去。","画槛移春，彩鸾衔信，几番延伫。","看钗莛叠萼，天然富贵，妆台近，有人妒。","句引广陵遗恨，倩流莺、为花低诉。","年年长是，芳菲时候，满城烟絮。","春色三分，落红千片，总成尘土。","向月明空羡，双双睡蝶，宿花房露。"]},{"t":"水龙吟 西池败荷","f":"曲","c":["水宫仙子归来，为谁独立西风背。","凌波梦断，可怜零落，一奁环佩。","雨叶敲寒，露房倒影，秋声惊碎。","问西亭翠被，将愁何处，空留得，余香在。","最爱双飞白鹭，镇相依、蓼边萍外。","舞衫歌扇，有人绣出，水情云态。","西子湖边，越娘舟上，忆曾同采。","甚人今未老，花应依旧，约明年再。"]},{"t":"水龙吟 傅渊道宅上赏紫牡丹","f":"曲","c":["紫云何处飞来，仙家别有藏春洞。","刻缯纹皱，镂檀色腻，薰脐香重。","谷雨初晴，榆烟新换，楝风微动。","是花姑养就，韩仙染出，还分与，人间种。","好与密笼绣幄，护玉环、三生妖梦。","只愁今夜，绿丛月老，珠房露冻。","便唤秋娘，重浇卯酒，缓歌低送。","倩红鸾与约，韵华且住，作尊前供。"]},{"t":"水龙吟 赋情云","f":"曲","c":["无心却恁多情，闲愁长向眉尖聚。","牢龙不定，为谁留恋，为谁归去。","半饷花阴，霎儿月暝，几番日暮。","被东风搅散，离愁惹断，又还趁，歌声驻。","只恐佩环卧冷，好重将、绣帷调护。","何人得似，晓妆鬟髻，春娇态度。","缥缈尊前，朦胧眼底，非烟非雾。","把柔情一缕，都随好梦，作阳台雨。"]},{"t":"水调歌头","f":"曲","c":["三十九年我，老色上吟髭。","生辰月宿南斗，正合退之诗。","今岁两逢正月，准算恰成四十，岁暮日斜时。","腊彘剐红玉，汤饼煮银丝。","炷炉香，饮杯酒，赋篇词。","萧然世味，前身恐是出家儿。","天下谁非健者，我辈终为奇士，一醉不须辞。","莫问黄杨厄，春在老梅枝。"]},{"t":"水调歌头 御河舟中","f":"曲","c":["中夜正无寐，何处橹声来。","河声不堪强聒，更听雁声哀。","月色依依偏照，霜气萧萧渐紧，何似解离怀。","明发吾无策，惟有快衔杯。","过重阳，都未见，菊花开。","遥知数丛篱下，破蕊映书斋。","三十六陂烟水，二十四桥风月，天遣几时回。","传语闲鸥鹭，相望莫惊猜。"]},{"t":"风入松","f":"曲","c":["东风巷陌暮寒骄。","灯火闹河桥。","胜游忆遍钱塘夜，青鸾远、信断难招。","蕙草情随雪尽，梨花梦与云销。","客怀先自病无聊。","绿酒负金蕉。","下帷独拥香篝睡，春城外、玉漏声遥。","可惜满阶明月，更无人为吹箫。"]},{"t":"风入松 清明日湖上即事","f":"曲","c":["寻春春在凤城东。","罗帕玉花骢。","美人半亸垂鞭袖，游尘远、目断云空。","浅碧湖波雪涨，淡黄官柳烟蒙。","相如多病赋难工。","宿酒更频中。","归来自按新声谱，凭谁解、唱与东风。","一夜小窗疏雨，杏花明日应红。"]},{"t":"风流子","f":"曲","c":["荷雨送凉飙，炎尘净、三市影灯宵。","看珠珞翠绳，焰摇冰碗，彩棚花架，光射星桥。","洞天好、笑声遮画扇，歌韵合鸾箫。","琼树影中，月窥端正，雪罗香里，人斗娇娆。","依稀元夜影，铜壶短，还又露洒烟飘。","空遣酒怀摇荡，羁思无聊。","想骢马钿车，俊游何在，雪梅蛾柳，旧梦难招。","醉掩重门，半釭兰烬红销。"]},{"t":"风流子 赏筝妓崔爱","f":"曲","c":["梨园供奉曲，卿卿解、写入十三弦。","听促弹宝柱，暮催行雨，放娇银甲，春绕飞烟。","可人处、凤声啼玉碎，燕尾点波圆。","宜与画看，徽容妍丽，欲裁诗寄，莺思缠绵。","多情曾相遇，归舟字、梦里尚记游仙。","好倩钿床纤手，移近尊前。","尽何处教吹，玉箫明月，此情追忆，锦瑟华年。","多少旧愁新恨，知为谁传。"]},{"t":"东风第一枝 忆梅","f":"曲","c":["老树浑苔，横枝未叶，青春肯误芳约。","背阴未返冰魂，阳梢已含红萼。","佳人寒怯，谁惊起、晓来梳掠。","是月斜、花外幺禽，霜冷竹间幽鹤。","云淡淡，粉痕渐薄。","风细细，冻香又落。","叩门喜伴金尊，倚阑怕听画角。","依稀梦里，记半面、浅窥朱箔。","甚时得、重写鸾笺，去访旧游东阁。"]},{"t":"兰陵王 临川寓舍闻筝","f":"曲","c":["晚风恶。","墙外杨花正落。","秋千罢、人在琐窗，犹怯春寒下帘幕。","多情倦绣作。","恰了棠梨半萼。","移金雁、应是自调，尽寄深情与弦索。","数声白瓴雀。","又歇拍多时，娇甚弹错。","新声旧谱多忘却。","想红香憔悴，锦书缭邈，匆匆前度见略略。","甚如在天角。","雾阁。","闭银钥。","柰梦断行云，青鸟难托。","三生书记情缘薄。","记旧家歌舞，那时行乐。","桃枝人面，问酒家，负旧约。"]},{"t":"玉漏迟 春日有怀","f":"曲","c":["病怀因酒恼。","依稀梦里，吴娃娇小。","金缕歌残，人去月斜云杳。","怕见栖香燕晚，又怕听、啼花莺晓。","庭院悄。","生衣欲试，风寒犹峭。","窈窕青粉墙低，送影遇秋千，蓦然间笑。","半朵棠梨，微露凤钗红袅。","近日琴心倦写，更远信、西沉青鸟。","虚负了。","花月一春多少。"]},{"t":"玉蝴蝶 春梦","f":"曲","c":["屏里昊山深窃，宿酲未解，午枕初甜。","胆怯窗虚，惊起误使人嫌。","是乳鸦、声声绿树，是语燕、两两朱帘。","转愁添。","斜翘不正，堕珥慵拈。","厌厌。","行云飞去，潇湘江上，巫峡峰尖。","不尽销凝，海棠月上已窥檐。","蝶粉寒、羞薰翠被，灯花瘦、懒叠香奁，倚春纤。","暗啼妆泪，半袖红淹。"]},{"t":"石州慢 春日雨中","f":"曲","c":["烟雨轻阴，庭院悄寒，晴意难准。","社前燕子归来，恰换一番花信。","春光全在，杏花红闹枝头，双鸾衔上金钗鬓。","待到尽开时，又胭脂成粉。","堪恨。","西园扑蝶人间，芳径踏青鞋润。","帘影愔愔、竟日瞢胜如困。","惜花中酒，寻常过了年年，情多那得离愁尽。","翠被不成温，满薰篝兰烬。"]},{"t":"石州慢 题玉笙手卷","f":"曲","c":["仙去缑山，宴罢武夷，琼响吹彻。","丛霄旧样亲传，琢就玉烟凝白。","悠扬彩凤，恰从云杪飞来，数声又趁鸳鸯歇。","零落碧桃花，点春风如雪。","清绝。","更宜秦女，银筝唤取，楚娥瑶瑟。","旋炙娇簧，只愁夜深寒咽。","相看老矣，剩须陶写留连，尊前递把红牙节。","归去画船时，满西湖明月。"]},{"t":"多丽","f":"曲","c":["凤凰箫。","新声远度兰桡。","漾东风、湖光十里，参差绿港红桥。","暖云蘸、郁金衫色，晴烟抹、翡翠裙腰。","罨画名园，闹红芳榭，蒲葵亭畔彩绳摇。","满鸳甃、落英堪藉，犹作殢人娇。","渍罗袂、莫揉痕退，生怕香销。","忆当年、尊前扇底，多情冶叶倡条。","浴兰女、隔花偷盼，修禊客、临水相招。","旧约寻欢，新声换谱，三生梦里可怜宵。","从留得、楝花寒在，啼鴂已无聊。","江南恨、越王台下，几度回潮。"]},{"t":"多丽","f":"曲","c":["晚山青。","一川云树冥冥。","正参差、烟凝紫翠，斜阳画出南屏。","馆娃归、吴台游鹿，铜仙去、汉苑飞萤。","怀古情多，凭高望极，且将尊酒慰飘零。","自湖上、爱梅仙远，鹤梦几时醒。","空留在、六桥疏柳，孤屿危亭。","待苏堤、歌声散尽，更须携妓西泠。","藕花深、雨凉翡翠，菰蒲软、风弄蜻蜓。","澄碧生秋，闹红驻景，采菱新唱最堪听。","□一片、水天无际，渔火两三星。","多情月、为人留照，未过前汀。"]},{"t":"多丽 为友生书所见","f":"曲","c":["小庭阶。","帘栊婀娜蓬莱。","恨匆匆、归鸿度影，东风摇荡情怀。","不多时、见他行过，霎儿后、依旧回来。","银铤双鬟，玉丝头导，一尖生色合欢鞋。","麝香粉、绣茸衫子，窄窄可身裁。","偶回头、笑涡透脸，蝉影笼钗。","忆疏狂、随车信马，那知沦落天涯。","豆蔻初、可怜春早，菖蒲晚、难见花开。","红叶波深，彩楼天远，浪凭青鸟信音乖。","等闲是、这番迷眼，无处可安排。","行云断、梦魂不到，空赋阳台。"]},{"t":"好事近 寒夜","f":"曲","c":["门外晚风生，鼓角城头欲动。","霜月满天如水，渐夜深寒重。","幽人拥被醉模糊，无愁也无梦。","只有些儿心上，怕梅花清冻。"]},{"t":"如梦令","f":"曲","c":["月似二年前好。","人比二年前老。","今夕又鲸川，但欠酒杯倾倒。","闻道。","闻道。","三径渐荒秋草。"]},{"t":"扫花游 落红","f":"曲","c":["洗春雨急，碎万点胭脂，荡空无影。","馆娃骨冷。","怅香销麝土，泪殷玉井。","莫怨东风，自古佳人薄命。","掩鸾镜。","纵补得茜瘢，妆坏难整。","芳事谁管领。","但蜜腻蜂房，藓斑鸳径。","一帘昼永。","绿阴阴尚有，绛趺痕凝。","彩笔招魂，已是繁华梦醒。","伫芳景。","换西湖、锦云千顷。"]},{"t":"江城子","f":"曲","c":["阖闾城外绿杨枝。","一丝丝。","比吟髭。","比似吟髭，不似少年时。","积欲同携尊酒去，青翰舫，缕金卮。","故人相见减风姿。","淡胭脂。","比红儿。","比似红儿，扶醉索新诗。","明日片帆江水远，人去也，又相思。"]},{"t":"江城子 枕顶","f":"曲","c":["合欢花样满池娇。","用心描。","数针挑。","面面芙蕖，闲叶映兰苕。","刺到鸳鸯双比翼，应想像，为魂销。","巧盘金缕缀倡条。","隐红绡。","翠妖饶。","白玉函边，几度坠鸾翘。","汗粉啼红容易涴，须爱惜，可怜宵。"]},{"t":"江城子 惜花","f":"曲","c":["牡丹芍药冠池台。","缕金杯。","锦云堆。","最恨颠风，横雨故相催。","国色天香虚过了，红片片，卧苍苔。","绿阴篱落暗香来。","野酴醾，刺玫瑰。","照眼遗芳，烂漫趁晴开。","纵使专春春有几，花到此，已堪哀。"]},{"t":"江城梅花引","f":"曲","c":["玉儿睡起帕蒙头。","更娇柔。","见郎羞。","缟袂仙人，一笑艳明眸。","粉瘦红憨春梦断，画阑畔，对西风，忆旧游。","忆君恨君思悠悠。","怕凄凉，不耐秋。","艳绝韵绝香更绝，特地风流。","宜与云鬟双插倚妆楼。","月又渐低霜渐冷，花似雪，满苍苔，总是愁。"]},{"t":"百字令 眉间雁","f":"曲","c":["晓妆乍了，又翩翩何许、飞来临镜。","欲寄相思无一字，拈起芳心重省。","鬓亸云低，眉颦山远，去翼宜相映。","娇波频送，恍如秋水涵影。","几度揉损啼红，恨卿卿不到，吴江枫冷。","一点风流应解妒，翡翠双钿相并。","忘入香奁，时偎绣枕，看足宫花暝。","多情剪就，忍教分做孤另。"]},{"t":"百字令 燕城晚望","f":"曲","c":["碧天向晚，远云开疑是、江南山色。","渺渺孤鸿残照外，独上高城望极。","鸡散台空，萤沉苑废，龙去沟无迹。","英雄安在，千秋恨血凝碧。","我欲携酒重来，佛狸祠下，字暗苍苔石。","社鼓神鸦浑不见，一片青青荠麦。","夜月琼枝，春风水调，肯慰淹留客。","翩然归去，天风扶下双舄。"]},{"t":"行香子","f":"曲","c":["谢董糟丘。","罢醉乡侯。","更开除、从事青州。","长瓶尽卧，大白休浮。","本欲成欢，翻引病，不销愁。","今日空喉。","明日扶头。","甚窦中、瓮下堪羞。","客应嗔断，妇不须谋。","指水为言，山作誓，有盟鸥。"]},{"t":"行香子","f":"曲","c":["扰扰阎浮。","清浊同流。","费精神、补喜填忧。","岁云暮矣，卿可归休。","有板支颐，书遮眼，被蒙头。","蝼蚁王侯。","华屋山丘。","待他时、老去优游。","筑间茅屋，买个黄牛。","种芋成区，瓜作圃，稻盈畴。"]},{"t":"行香子","f":"曲","c":["水远天低。","雪意垂垂。","火炉头、煨芋燃萁。","蒲团稳坐，纸帐低围。","且放些慵，补些拙，学些痴。","休惹群儿。","唱起铜鞮。","笑山翁、醉倒如泥。","谁分蜾嬴，莫近鸱夷。","把独醒人，沉醉者，两忘机。"]},{"t":"行香子","f":"曲","c":["传癖诗逋。","野逸山臞。","是幽人、平日称呼。","过如饭袋，胜似钱愚。","尽我为牛，人如虎，子非鱼。","石铫风炉。","雪碗冰壶。","有清茶、可润肠枯。","生涯何许，机事全疏。","但伴牢愁，盘礴赢，鼓咙胡。"]},{"t":"行香子 山水便面","f":"曲","c":["佛寺云边。","茅舍山前。","树阴中、酒旆低悬。","峰峦空翠，溪水清涟。","只欠梅花，欠沙鸟，欠渔船。","无限风烟。","景趣天然。","最宜他、隐者盘旋。","何人村墅。","若个林泉。","恰似敧湖，似枋口，似斜川。"]},{"t":"行香子 止酒五首","f":"曲","c":["酒量无多。","不饮从他。","看黄垆、似隔山河。","渊明自止，醉尉谁呵。","也莫豪吟，莫狂舞，莫高歌。","鸥外风波。","蜗角干戈。","算百年、一梦南柯。","阅人传舍，随处行窝。","便富熏天，气盖世，待如何。"]},{"t":"齐天乐","f":"曲","c":["阑干十二东风外，春藏画楼鸳琐。","蜡炬光浓，氍毹坐软，宝鼎旋培沉火。","玻璃盏大。","但有酒须倾，有歌须和。","剧饮淋浪，万金良夜虚过。","中年情绪易恶，风流青镜里，销减些个。","闽雨程赊，吴云驿远，别恨料应如我。","先拚醉卧。","任杨柳烟销，海棠月堕。","明日江头，倩谁留画舸。"]},{"t":"齐天乐 临川夜饮滏阳李辅之寓所","f":"曲","c":["江霜一树凄凉叶，惊鸟夜深啼落。","客里相逢，尊前细数，几度雨漂风泊。","微吟缓酌。","渐月影斜欹，画阑东角。","只怕梅花，无人看管瘦如削。","江湖容易岁晚，想多情念我，归信曾约。","尘土狂踪，山林旧隐，梦寄草堂猿鹤。","离怀最恶。","是酒醒香残，烛寒花薄。","一段销凝，觉来无处着。"]},{"t":"声声慢","f":"曲","c":["金銮学士，天上归来、兰舟小驻芜城。","供奉新词，几度惯赋鸣筝。","相逢沉郎绝艺，为尊前、细写余情。","问何似，似秦关雁度，楚树蝉鸣。","我亦从来多感，但登山临水，慷慨愁生。","一曲哀弹，只遣髯变魂惊。","行期买花载酒，趁秋高、月明风清。","须尽醉，听江头、肠断数声。"]},{"t":"声声慢","f":"曲","c":["西风坠绿。","唤起春娇，嫣然困倚修竹。","落帽人来，花艳乍惊郎目。","相思尚带旧恨，甚凄凉、未忺妆束。","吟鬓底，伴寒香一朵，并簪黄菊。","却待金盘华屋。","园林静、多情怎禁幽独。","蛱蝶应愁，明日落红难触。","那堪雁霜渐重，怕黄昏、欲睡未足。","翠袖冷，且莫辞、花下秉烛。"]},{"t":"沁园春","f":"曲","c":["客汝知乎，载酒轻舟，看花小车。","胜炎州出使，瘴浮征旆，禁门待漏，霜满朝靴。","岁去堂堂，老来冉冉，瓶雀飞时手怎遮。","平生事，叹山林迹远，霄汉程赊。","从渠梦蝶疑蛇。","得放懒、还须自在些。","甚天荒地老，铜台歌舞，水流云在，金谷豪奢。","客问先生，归宜早计，醉后之言可信耶。","鸥盟在，任渔蓑江上，雨细风斜。"]},{"t":"沁园春","f":"曲","c":["天上玉堂，海外瀛洲，山中蜕岩。","甚六十四岁，出持使节，八千余里，来驻征骖。","香火缘深，功名意薄，梦觉仙家雪满簪。","桐花社，喜酒边莺燕，诗外云岚。","锦堂容我清酣。","拥画烛、金钩手屡探。","怪朗吟御史，笑回红粉，送归司马，泪湿青衫。","蜀魄春多，塞鸿秋远，无限离情老不堪。","空留意，在水光山色，江北江南。"]},{"t":"沁园春","f":"曲","c":["何许登临，路绕芜城，冈连楚皋。","爱流云低响，歌催琼树，微波照影，人艳仙桃。","松院移尊，柳桥携袖，随处兰舟且暂捎。","秋无际，望空江雁远，落木天高。","不妨左手持螯。","更右把、金尊送浊醪。","叹鸡台草暗，凄然兴废，龙山烟冷，老矣英豪。","白发宁饶，黄花任插，要里西风破帽牢。","刘郎醉，把吴笺笑擘，试与题糕。"]},{"t":"沁园春 次韵李元之听董氏双弦","f":"曲","c":["谁唤娇娆，斜插双弦，华筵乍开。","爱玉纤轻轧，半笼翠袖，歌喉缓引，暗点鸳鞋。","胡部新声，乐工巧制，写出龙沙马上哀。","哀何似，似离鸾惊起，白雀飞来。","丁宁击节金钗。","要细听、春风且慢催。","正宫商分犯，拽归双调，伊州入破，攧遍三台。","画扇香收，罗巾汗湿，愁是云兜醉后回。","花闲客，任鸾绡缠髻，更尽余杯。"]},{"t":"花心动 剑浦有感","f":"曲","c":["花信风寒，绮窗深、匆匆禁烟时节。","燕子乍来，宿雨才晴，满树海棠如雪。","黛眉准拟明朝画，灯花剪、妆奁双叠。","负佳约、鹊还误报，燕应羞说。","宝镜将圆又缺。","从涩尽银簧，怕吹呜咽。","一霎梦魂，也唤相逢，依黯断云残月。","古来多少春闺怨，看薄命、无人如妾。","软绡帕、凭谁寄将泪血。"]},{"t":"苏武慢","f":"曲","c":["岁晚江空，雪飞风起，老境若为聊赖。","家人解事，准备深尊，旋遣夜窗寒解。","萍梗孤踪，幻影浮生，万里喜还闽海。","但囊中留得，诗篇烂写，水情山态。","真比似、一个冥鸿，南来北去，阅尽几重关塞。","名缰利锁，绊杀英雄，都付醉乡之外。","惟不能忘，一舸吴淞，鲈脍豉羹莼菜。","且今宵还我，冰壶天地，眼空尘界。"]},{"t":"苏武慢 对雪","f":"曲","c":["冻雨跳空，朔云屯地，陡觉夜寒无赖。","谁从蕊阙，宴罢群仙，一样佩零珠解。","应唤冯夷，起舞回风，搅碎渺茫银海。","倚南窗清思，盈襟看尽，整容斜态。","君试问、白羽鸣弦，青貂束锦，千骑猎归烟塞。","何如倦客，蜡屐枝筇，乘兴竹边梅外。","随处堪寻，卖酒人家，春渚水乡挑菜。","趁湖山晴晓，吟魂飞上，玉峰瑶界。"]},{"t":"孤鸾 题钱舜举仙女梅下吹笛图","f":"曲","c":["江皋空阔。","更半霎轻风，些儿微雪。","倚树仙姬，翠袖暮寒应怯。","闲拈玉龙自品，爱冰姿、与花争洁。","一阕霓裳乍了，又落梅初叠。","怕曲终人去彩云绝。","便梦断瑶台春思愁结。","□□□□、□□□□□□。","那堪绿毛幺凤，向苔枝、数声啼咽。","留得余香满袂，已西山斜月。"]},{"t":"定风波 商角调西江客舍酒后闻梅花吹香满窗醒而赋此","f":"曲","c":["恨行云、特地高寒，牢笼好梦不定。","婉娩年华，凄凉客况，泥酒浑成病。","画阑深，碧窗静。","一树瑶花可怜影。","低映。","怕月明照见，青禽相并。","素衾正冷。","又寒香、枕上薰愁醒。","甚银床霜冻，山童未起，谁汲墙阴井。","玉笙残，锦书迥。","应是多情道薄幸。","争肯。","便等闲孤负，西湖春兴。"]},{"t":"定风波 昆山路漕席上","f":"曲","c":["舞袖歌鬟簇画堂。","就中偏是展家娘。","待道无情还有思。","恰似。","昆山日暖凤求凰。","海上潮生人尽醉。","催起。","兰舟分散不成双。","回首玄都春梦里。","从此。","桃花应自怨刘郎。"]},{"t":"金缕词 送上官子东之昆山州幕官","f":"曲","c":["烟草长洲苑。","渺姑苏、旧游麋鹿，岁华云晚。","多少吴宫花月恨，春去春来不管。","只付与、行人凄断。","君去风流宾幕里，把今情、古意供裁剪。","珠唾湿，玉烟暖。","相逢尽看金杯满。","信人生、好怀有几，梦长缘短。","白发峥嵘三千丈，底用云揉雨染。","且斗取、尊前强健。","为问浮槎还到否，便乘之、直上三山远。","看瀛岛，水清浅。"]},{"t":"金缕词 送王季境还广陵","f":"曲","c":["西子湖边路。","看依然、水光山色，自宜晴雨。","天上归来重载酒，惟有旧盟鸥鹭。","笑鬓影、星星如许。","公子华筵凉似水，更绿鬟、窈窕歌金缕。","留晚醉，看眉妩。","三生书记真豪举。","把平生、香奁软语，锦囊佳句。","君到淮南明月夜，为问崔娘安否。","□翻作、锦筝新谱。","只恐惊鸿花外起，趁行云、直过沧江去。","飞不到，断肠处。"]},{"t":"陌上花","f":"曲","c":["关山梦里，归来还又、岁华催晚。","马影鸡声，谙尽倦邮荒馆。","绿笺密记多情事，一看一回肠断。","待殷勤寄与，旧游莺燕，水流云散。","满罗衫是酒，香痕凝处，唾碧啼红相半。","只恐梅花，瘦倚夜寒谁暖。","不成便没相逢日，重整钗鸾筝雁。","但何郎，纵有春风词笔，病怀浑懒。"]},{"t":"临江仙","f":"曲","c":["羡杀渔村无畔岸，茫茫杨柳蒹葭。","雨余秋涨没汀沙。","惊鸿投别渚，浴鸟坐沉槎。","残日篱头闲晒网，垂髫来卖鱼虾。","得钱沽酒径归家。","一声横笛外，烟火隔芦花。"]},{"t":"临江仙 次韵山村先生赋柳","f":"曲","c":["摇荡春光湖上路，多情偏识倡条。","画船系在赤阑桥。","花飞人别处，绿暗雨休朝。","恼乱东风扶不起，空怜燕姹莺娇。","舞衣香冷董娇娆。","相思无限恨，犹似旧宫腰。"]},{"t":"临江仙 梁山舟中二首 其二","f":"曲","c":["羡杀渔家生处乐，隔湾数点青灯。","蓑衣忘在石矶层。","蓼花秋酿酒，枫树晚垂罾。","时向瓦鸥篷底醉，往来鹭侣鸥朋。","老翁倚棹坐瞢腾。","有鱼吾欲买，摇手不能膺。"]},{"t":"南乡子","f":"曲","c":["野唱自凄凉。","一曲孤鸿欲断肠。","恰似竹枝哀怨处，潇湘。","月冷云昏觅断行。","离思楚天长。","风闪青灯雨打窗。","惊起小红楼上梦，悠扬。","只在佳人锦瑟傍。"]},{"t":"南乡子","f":"曲","c":["秋色照波明。","夹岸芙蓉似锦城。","罨画楼台红粉面，轻盈。","未许黄徐写得成。","一舸载杨琼。","共醉花前玉笛声。","犹记青鸾和月跨，三生。","我是仙家石曼卿。"]},{"t":"南浦","f":"曲","c":["花落楚江流，过西山、雨涨渔村无路。","双浆载愁来，苹沙外、惟有盟鸥相觑。","春波碧草，送君曾是伤情处。","依旧朝云飞画栋，秋满鹤汀凫渚。","斜阳三两人家，□青旗影里，炊烟一缕。","弦索夜深船，凄凉听、还似西风湓浦。","征鸿去尽，梦回明月生烟树。","如此山川无限恨，都付一尊怀古。"]},{"t":"春从天上来","f":"曲","c":["袅袅秋风。","听响彻云间，彩凤啼雄。","嬴女飞下，玉佩玲珑。","肠断十二台空。","渺霜天如海，写不尽、楚客情浓。","烛销红。","更锵金振羽，变徵移宫。","扬州旧时月色，叹水调如今，离唱谁工。","露叶残蛾，蟾花遗粉，寂寞琼树香中。","问坡仙何处，沧江上、鹤梦无踪。","思难穷。","把一襟幽怨，吹与鱼龙。"]},{"t":"春从天上来 同王继学宪使赋","f":"曲","c":["十里红楼。","问声价如今，谁满扬州。","白发书记，此日重游。","听取席上名讴。","拥冰弦斜伫，更为我、敛笑凝眸。","觅黄骝。","看端端怎比，楚楚风流。","殷勤砑绫小草，写不尽宫妆，一段春柔。","淡水疏花，知谁消受，几度帘卷香收。","怕巫娥归去，空惆怅、梦断情留。","把离愁。","付行云行雨，楚尾吴头。"]},{"t":"昭君怨","f":"曲","c":["队队毡车细马。","簇拥阏氏如画。","却胜汉宫人。","闭长门。","看取蛾眉妒宠。","身后谁如遗冢。","千载草青青。","有芳名。"]},{"t":"洞仙歌 辛巳岁燕城初度","f":"曲","c":["功名利达，任纷纷奔竞。","纵使得来也侥幸。","老眼看多时，钟鼎山林，须信道、造物安排有命。","人生行乐耳，对月临风，一咏一觞且乘兴。","五十五年春，南北东西，自笑萍踪久无定。","好学取、渊明赋归来，但种柳栽花，便成三径。"]},{"t":"点绛唇 舟行书见","f":"曲","c":["风起云飞，兰舟竞入横塘住。","恼人何处。","隔岸花篱雾。","一水盈盈，难送凌波步。","空相觑。","正如牛女。","隔断银河路。"]},{"t":"眉妩 七夕感事","f":"曲","c":["又蛛分天巧，鹊误秋期，银汉会牛女。","薄命犹如此，悲欢事，人间何限夫妇。","此情更苦。","怎似他、今夜相遇。","素娥妒、不肯偏留照，渐凉影催曙。","私语钗盟何处。","但翠屏天远，清梦云去。","纵有闲针缕，相怜爱、丝丝空缀愁绪。","窃春伴侣。","问甚时、重画眉妩。","谩铅泪弹风，都付与洗车雨。"]},{"t":"唐多令 寄意箜篌曲","f":"曲","c":["花下钿箜篌。","尊前白雪讴。","记怀中、朱李曾投。","镜约钗盟心已许，诗写在，小红楼。","忍泪上云兜。","断魂随彩舟。","等闲闲、惹得离愁。","欲寄长河鱼信去，流不到，白鹭洲。"]},{"t":"恋绣衾 春晴中酒","f":"曲","c":["醉乡残梦莺唤醒。","见柳梢、日影弄明。","又误了、寻芳伴，减东风、庭院笑声。","玉儿扶起仍娇困，索樱桃、芳露解酲。","纵病也、心情好，比别离、滋味较轻。"]},{"t":"桂枝香","f":"曲","c":["天香万斛。","尽贮入魏台，辟寒金粟。","谁唤仙娥睡起，露妆烟沐。","翠云裙袖黄云袜，倚秋风、乍惊郎目。","恨无明月，高烧蜡炬，分阴丛绿。","深照见、凉禽并宿。","爱摇滟琼杯，花影堪掬。","寸梦丝缘旧约，尚堪重续。","何时卜隐西湖上，葺缃荷、芳杜为屋。","小山人远，魂招不来，谩歌遗曲。"]},{"t":"浣溪沙","f":"七言古诗","c":["一点芳心两翠蛾。","恼人离绪不胜多。","尊前忍听渭城歌。","花落鸟啼春去也，水长天远客愁何。","此情何处托微波。"]},{"t":"浣溪沙","f":"七言古诗","c":["偶约尊前已目成。","琵琶私语更分明。","如今翻作断肠声。","彩扇旧歌怜楚楚，青楼薄幸怨卿卿。","海枯石烂古今情。"]},{"t":"浣溪沙","f":"七言古诗","c":["数载相看欲话难。","酒边失口却成欢。","空添别恨与眉端。","流水有声传锦瑟，行云无梦赴青鸾。","关河秋雨客窗寒。"]},{"t":"浣溪沙","f":"七言古诗","c":["珍重千金一诺同。","小红楼上舞筵中。","谁知别路太匆匆。","愁杀二分无赖月，凭将万里有情风。","为传消息宋家东。"]},{"t":"浣溪沙 临川别席","f":"七言古诗","c":["昨夜花前送玉钟。","绿鬟歌罢落梅风。","不知离思为谁浓。","醉语低回银烛背，梦云重叠绣帏中。","只愁归路见芙蓉。"]},{"t":"浪淘沙令","f":"曲","c":["醉胆望秋寒。","星斗阑干。","小窗人影月明间。","客里不知归是梦，只在吴山。","行路自来难。","长铗休弹。","黄尘到底涴儒冠。","一片白鸥湖上水，闲了渔竿。"]},{"t":"真珠帘","f":"曲","c":["银蟾半露婵娟影，西风早、次第中秋天气。","凉透小帘栊，乍夜长迟睡。","见说灵岩山色好，甚也不浓如归意。","归未。","趁西泠载酒，南园寻桂。","还又客里生朝，把金尊绿酒，与谁同醉。","烟雨隔垂虹，望美人秋水。","桃叶妆楼团扇曲，但小草、鸾笺相寄。","传示。","送白萍一剪，碧云千里。"]},{"t":"破阵子 七夕戏咏","f":"曲","c":["此夕天孙河鼓，多情呆女痴儿。","鹊驾年年仍远渡，蛛合家家长巧丝。","星期莫怨咨。","迢递金钗私语，凄凉纨扇宫词。","奔月姮娥催去路，行雨巫山空梦思。","都无重会时。"]},{"t":"高阳台 题赵仲穆作陈野云居士山水便面","f":"曲","c":["染黛浮空，凝妆伫远，数峰底事含颦。","十样新眉，从他雨抹烟匀。","龙绡便面宜歌舞，看亭亭、玉骨冰神。","几销魂，翠被余香，锦瑟清尘。","如今归去湖山畔，对一川平野，一片闲云。","两两渔舟，相过桂渚兰津。","谁将玉斧修明月，柰琼楼、高处无人。","忆王孙。","芳草江南，暗鴂残春。"]},{"t":"婆罗门引","f":"曲","c":["暮天映碧，玻璃十顷蕊珠宫。","金波涌出芙蓉。","谁唤川妃微步，一色夜妆红。","看光摇星汉，起舞鱼龙。","月华正中。","画船漾，藕花风。","声度鸾箫缥缈，雁柱玲珑。","酒阑兴极，更移上、琼楼十二重。","残醉醒、烟水连空。"]},{"t":"惜分飞 写梦","f":"曲","c":["相见依然人似旧。","比似年时较瘦。","笑问平安否。","不言低掩罗衫袖。","便欲窗前推枕就。","无柰红僝绿僽。","惊起空回首。","半床斜月疏钟后。"]},{"t":"望海潮","f":"曲","c":["扶桑何许，蓬莱何处，沧海一望漫漫。","精卫解填，鼋鼍可驾，凌波直度三韩。","云气有无间。","只是天是水，无地无山。","赑屃鳌掀，飓风俄起书生寒。","从今不数鲵桓。","羡秦人采药，龙伯垂竿。","槎信未来，珠光暗徙，群仙约我骖鸾。","长啸壮怀宽。","且振衣绝顶，酾酒长澜。","挥手相招，片帆飞趁暮潮还。"]},{"t":"清平乐","f":"曲","c":["先生醉也。","甚矣吾衰也。","万物不如归去也。","陶令真吾师也。","篱边菊蕊初黄。","为花准备携觞。","只恐不如人意，风风雨雨重阳。"]},{"t":"清平乐 酒后二首","f":"曲","c":["先生醉矣。","是事忘之矣。","欲友古贤谁可矣。","严子真其人矣。","问渠辛苦征鞍。","何如自在渔竿。","终办一丘隐计、西湖鸥鹭平安。"]},{"t":"清平乐 寄山居道人约看杏花","f":"曲","c":["东风阵阵。","第几番春信。","呆李痴桃消息近。","写取鸾笺试问。","君家杨柳墙东。","杏花初吐生红。","好唤一床金雁，明朝来醉春风。"]},{"t":"清平乐 盛子昭花下欠伸美人图","f":"曲","c":["阶前昼永。","绕石芭蕉影。","半亸云鬟慵不整。","寂寞朝酲乍醒。","湘裙翠被风流。","背人无限娇羞。","玉腕一双跳脱，欠伸浑是春愁。"]},{"t":"渔家傲","f":"曲","c":["红白芙渠千万朵。","水仙恰试新梳裹。","缟袂霞衣争婀娜。","香霞堕。","凌波忽载行云过。","正好玩芳停画舸。","尊前自唱无人和。","惟有沙鸥三两个。","飞近我。","夜凉同向花间卧。"]},{"t":"绮罗香 雨中舟次洹上","f":"曲","c":["燕子梁深，秋千院冷，半湿垂杨烟缕。","怯试春衫，长恨踏青期阻。","梅子后、余润留寒，藕花外、嫩凉消暑。","渐惊他、秋老梧桐，萧萧金井断蛩暮。","薰篝须待被暖，催雪新词未稳，重寻笙谱。","水阁云窗，总是惯曾听处。","曾信有、客里关河，又怎禁、夜深风雨。","一声声、滴在疏篷，做成情味苦。"]},{"t":"菩萨蛮","f":"曲","c":["郎情秋后萧疏叶。","妾心陌上悠扬蝶。","何处望归鞍。","春云山外山。","梨花新月下。","独自烧香罢。","惟有梦相寻。","惊鸟啼夜深。"]},{"t":"菩萨蛮 赠雁","f":"曲","c":["人随雁雁俱南去。","雁应先到凭传语。","若问锦书无。","人归不得书。","归期还信否。","准在梅花后。","烟树短长亭。","只争三四程。"]},{"t":"谒金门 效前人首句用山人字醉中答友","f":"曲","c":["山人坐。","把酒歌呼相和。","起舞尽教乌帽堕。","归来头不裹。","浮世人情历过。","身外虚名参破。","除却醉乡无别个。","神仙天地我。"]},{"t":"谒金门 酒后偶忆","f":"曲","c":["春几许。","红透数枝花雨。","管领风光谁是主。","酒边人楚楚。","好与写将乐府。","剩与画教眉妩。","醉后不知庭院午。","隔帘双燕语。"]},{"t":"谒金门 寒食临川平塘道中","f":"曲","c":["溪水漫。","岸口小桥冲断。","沽酒人家门巷短。","柳阴旗一半。","细雨鸣鸠相唤。","曲港落花流满。","两两睡红鸂鶒暖。","恼人春不管。"]},{"t":"喜迁莺 琼花","f":"曲","c":["东风吹尽。","但一片绿阴，空留春恨。","后土祠荒，飞琼谪久，还喜玉容堪认。","二十四桥夜月，二十四番花信。","便载酒，怕芳菲易老，阴晴难稳。","娇困。","羞起晚，伫立画阑，净洗闲脂粉。","沉水浓熏，蜂黄淡染，自有绝尘香韵。","也知世间无对，肯许浮花相近。","凤箫远，待数枝折与，玉峰人问。"]},{"t":"最高楼 为山村仇先生寿","f":"曲","c":["方寸地，七十四年春。","世事几浮云。","躬行斋内蒲团稳，耆英社里酒杯频。","日追游，时啸咏，任天真。","喜女嫁男婚今已毕。","便束帛安车那肯出。","无一事，挂闲身。","西湖鸥鹭长为侣，北山猿鹤莫移文。","愿年年，汤饼会，乐情亲。"]},{"t":"朝中措","f":"曲","c":["梅花处处满枝开。","酒力荡吟怀。","烟染藏鸦万缕，东风扶起春来。","幽禽啼树，戏鱼跳日，水碧如苔。","若个仙翁画得，翠微倒影楼台。"]},{"t":"疏影 王元章墨梅图","f":"曲","c":["山阴赋客。","怪几番睡起，窗影生白。","缥缈仙姝，飞下瑶台，淡伫东风颜色。","微霜恰护朦胧月，更漠漠、暝烟低隔。","恨翠禽、啼处惊残，一夜梦云无迹。","惟有龙煤解染，数枝入画里，如印溪碧。","老树枯苔，玉晕冰圈，满幅寒香狼藉。","墨池雪岭春长好，悄不管、小楼横笛。","怕有人、误认真花，欲点晓来妆额。"]},{"t":"意难忘 妓杨韵卿以善歌求赋","f":"曲","c":["高韵天成。","问当时爱爱，得似卿卿。","江梅风致别，楚蕙雪香清。","花旎旎，月盈盈。","写不尽才情。","把旧游，名讴试数，谁解新声。","诗家只有杨琼。","向吴姬丛里，转更分明。","金闺春思怯，翠被暮寒生。","人欲去，酒还醒。","黯此际销凝。","待剪将，江云数尺，与染丹青。"]},{"t":"感皇恩 题赵仲穆画凌波水仙图","f":"曲","c":["湘水冷涵秋，行云平贴。","时见惊鸿度萍末。","雾鬟烟佩，微步一川凉月。","软波擎不定，龙绡袜。","楚楚绀莲，愔愔瑶瑟。","照影明珰两清绝。","汜人何处，起舞为谁轻别。","数峰江上晚，和愁叠。"]},{"t":"摸鱼儿","f":"曲","c":["过花朝、淡烟轻雨，东风还又春社。","客怀不断还家梦，只泥酒杯陶写。","孤馆夜。","甚浓醉、无人知道归来也。","兰灯半灺。","任赋就鱼笺，弦抛玉轸，谁念倦司马。","长安市，几度携尊命驾。","空惊游兴衰谢。","醉乡天地无今古，争得一襟萧洒。","春纵冶。","便不饮、从教团雪揉花打。","觥筹已罢。","笑蜾嬴螟蛉，吾今真止，为报独醒者。"]},{"t":"摸鱼儿","f":"曲","c":["正匆匆、楚乡秋晚，孤鸿飞过南浦。","同来桃叶堪惆怅，一舸载春先去。","愁绝处。","问那曲阑干，曾听人低语。","今宵最苦。","向枫树溪桥，芦花野馆，剪烛卧听雨。","吴霜鬓，破帽西风怎护。","丝丝都是离绪。","旧情顿冷新愁重，总付坠鞭词谱。","君记取。","待雪夜、相思乘兴柴冈路。","唱予和汝。","要款段随车，轻盈唤酒，重为国香赋。"]},{"t":"摸鱼儿","f":"曲","c":["问西湖、旧家儿女，香魂还又连理。","多情欲赋双蕖怨，闲却满奁秋意。","娇旖旎。","爱照影、红妆一样新梳洗。","王孙正拟。","唤翠袖轻歌，玉筝低按，凉夜为花醉。","鸳鸯浦，凄断凌波梦里。","空怜心苦丝脆。","吴娃小艇应偷采，一道绿萍犹碎。","君试记。","还怕是、西风吹作行云起。","阑干谩倚。","便载酒重来，寻芳已晚，余恨渺烟水。"]},{"t":"摸鱼儿","f":"曲","c":["记苏台、旧时风景，西楼灯火如画。","严城月色依然好，无复绮罗游冶。","欢意谢。","向客里相逢，还又思陶写。","金尊翠斝。","把锦字新声，红牙小拍，分付倦司马。","繁华梦，唤起燕娇莺奼。","肯教孤负元夜。","楚芳玉润吴兰媚，一曲夕阳西下。","沉醉罢。","君试问、人生谁是无情者。","先生归也。","但留意江南，杏花春雨，和泪在罗帕。"]},{"t":"摸鱼儿 春日西湖泛舟","f":"曲","c":["涨西湖、半篙新雨，曲尘波外风软。","兰舟同上鸳鸯浦，天气嫩寒轻暖。","帘半卷。","度一缕、歌云不碍桃花扇。","莺娇燕婉。","任狂客无肠，王孙有恨，莫放酒杯浅。","垂杨岸，何处红亭翠馆。","如今游兴全懒。","山容水态依然好，惟有绮罗云散。","君不见。","歌舞地、青芜满目成秋苑。","斜阳又晚。","正落絮飞花，将春欲去，目送水天远。"]},{"t":"摸鱼儿 钱万户宜之邀予赋瑶台景","f":"曲","c":["甚瑶台、翠鸾雏小。","风流占断妍景。","数声何处啼春胜，帘卷晓窗人静。","天气困。","梳未稳、绿鬟倭堕临妆镜。","懒羞倦整。","待铰个金花，眉夫双雁，还怯剪刀冷。","仙家好，十二行云路迥。","牢笼芳梦不定。","多情正要人拘管，无柰绿昏红暝。","乘酒兴。","携两袖、天风飞上蓬莱顶。","阑干独凭。","为唤玉笙来，霓裳按舞，和月醉花影。"]},{"t":"摸鱼儿 赋湘云","f":"曲","c":["问湘南、有云多少，不应长是为雨。","平生宋玉缘情老，赢得鬓丝如许。","歌又舞。","更一曲琵琶，昵昵如私语。","闲悲浪苦。","怪旧日青衫，空流泪满，不解画眉妩。","空凝伫。","十二峰前路阻。","相逢知在何处。","今朝重见春风手，仍听旧弹金缕。","君且住。","怕望断、蘅皋日暮伤离绪。","新声自谱。","把江北江南，今愁往恨，尽入断肠句。"]},{"t":"摸鱼儿 题熊伯宜藏梅花卷子","f":"曲","c":["记西湖、水边曾见，查牙老树如此。","冰痕冷沁苔枝雪，的皪数花才试。","天也似。","爱玉质、清高不久闲红紫。","孤山处士。","总赋得招魂，烟荒雨暗，寂寞抱香死。","春风笔，休忆深宫旧事。","添人多恨多思。","墨池雪岭三生梦，唤起缟衣仙子。","仍独自。","伴瘦影、黄昏和月窥窗纸。","声声字字。","写不尽江南，闲愁万斛，诉与绿衣使。"]},{"t":"满江红 次韵耶律舜中樟亭观潮","f":"曲","c":["望入西泠，乍一线、涛头涌白。","疑海上、鳌翻山动，鹏抟风积。","银汉迢遥槎有信，秋光浩荡云无迹。","快醉挥、吟笔倒琼瑰，冯夷宅。","沙草远，迷烟碛。","云树老，敧宫壁。","叹潮生潮落，几时休息。","事往空遗亡国恨，鸟飞不尽吴天碧。","正销凝、何处夕阳楼，人横笛。"]},{"t":"满江红 钱舜举桃花折枝","f":"曲","c":["前度刘郎，重来访、玄都燕麦。","回首地、暗香销尽，暮云低碧。","啼鸟犹知人怅望，东风不管花狼籍。","又凄凄、红雨夕阳中，空相忆。","繁华梦，浑无迹。","丹青笔，还留得。","恍一枝常见，故园春色。","尘世事多吾欲避，武陵路远谁能觅。","但有山、可隐便须归，栽桃客。"]},{"t":"瑞龙吟","f":"曲","c":["鳌溪路。","潇洒翠壁丹崖，古藤高树。","林间猿鸟欣然，故人隐在，溪山胜处。","久延伫。","浑似种桃源里，白云窗户。","灯前素瑟清尊，开怀正好，连床夜语。","应是山灵留客，雪飞风起，长松掀舞。","谁道倦途相逢，倾盖如故。","阳春一曲，总是关心句。","何妨共、矶头把钓，梅边徐步。","只恐匆匆去。","故园梦里，长牵别绪。","寂寞闲针缕。","还念我、飘零江湖烟雨。","断肠岁晚，客衣谁絮。"]},{"t":"虞美人","f":"曲","c":["千林白雪花间谱。","价重黄金缕。","尊前自听断肠词。","正是江南风景落花时。","红楼翠舫西湖路。","好写新声去。","为凭宫羽教歌儿。","不道峰居才子鬓如丝。"]},{"t":"解连环 留别临川诸友","f":"曲","c":["夜来风色。","叹青灯素被，早寒欺客。","想寂寞、人在帘栊，望鸿雁欲来，又催刀尺。","秋满关河，更谁倚、夕阳横笛。","记题花赋月，此地与君，几度游历。","江头楚枫渐赤。","对离尊饮泪，难问消息。","趁一舸、千里东归，眇天末乱山，水边孤驿。","晼晚年华，怅回首、雨南云北。","算今古、此情此恨，甚时尽得。"]},{"t":"鹊桥仙","f":"曲","c":["功名一饷。","风波千丈。","已与闲居认状。","平生一步一崎岖，也趱到、盘山顶上。","梅花解笑，青禽能唱。","容我尊前疏放。","从今甘老醉乡侯，算不是、麒麟画像。"]},{"t":"鹊桥仙","f":"曲","c":["生朝戊子。","今朝戊子。","五十八年还是。","头童齿豁可怜人，也召入、词林修史。","前生偶尔。","后生偶尔。","但喜心头无事。","从来不解学神仙，怎会得、长生不死。"]},{"t":"摘红英 春雨惜花","f":"曲","c":["莺声寂。","鸠声急。","柳烟一片梨云湿。","惊人困。","教人恨。","待到平明，海棠应尽。","青无力。","红无迹。","残香剩粉那禁得。","天难准。","晴难稳。","晚风又起，倚阑争忍。"]},{"t":"蝶恋花 柳絮","f":"曲","c":["陌上垂杨吹絮罢。","愁杀行人，又是春归也。","点点飞来和泪洒。","多情解逐章台马。","瘦尽柔丝无一把。","细叶青颦，闲却当时画。","惆怅此情何处写。","黄昏淡月疏帘下。"]},{"t":"踏莎行","f":"曲","c":["雨涧天寒，孤山雪后。","美人空谷谁为友。","香林有路玉烟深，瀛洲无梦朝云瘦。","照影冰壶，含情翠袖。","写生合在徐黄手。","仙家花月镇长春，与君岁晚同三寿。"]},{"t":"踏莎行 江上送客","f":"曲","c":["芳草平沙，斜阳远树。","无情桃叶江头渡。","醉来扶上木兰舟，将愁不去将人去。","薄劣东风，夭邪落絮。","明朝重觅吹笙路。","碧云红雨小楼空，春光已到销魂处。"]},{"t":"鹧鸪天","f":"曲","c":["乍学琵琶已断肠。","锦绦银甲玉悬珰。","春风琼树声逾稳，秋水芙蓉字亦香。","微敛笑，浅句妆。","何须重觅杜韦娘。","休教月底清歌去，怕趁行云上凤凰。"]},{"t":"鹧鸪天","f":"曲","c":["一曲吴歌酒半酣。","声声字字是江南。","书凭仙苑青鸾递，花助妆楼粉蝶衔。","飞燕瘦，宝儿憨。","已妍还慧更岩岩。","无因剪得湘江水，与蘸春云作舞衫。"]},{"t":"鹧鸪天 为朱氏小妓绣莲赋三首","f":"曲","c":["半臂京绡稳称身。","玉为颜面水为神。","一痕头导分云绾，两点眉山入翠颦。","丹杏小，碧桃新。","雏莺恰啭上林春。","平生惯是听歌耳，除却莲儿只一人。"]},{"t":"鹧鸪天 赠泉南琵琶妓","f":"曲","c":["玉手琵琶半醉中。","从容慢拈复轻拢。","青衫司马情偏感，翠袖红莲艺更工。","花淡泞，月朦朦，归来无语立东风。","汗巾红渍槟榔液，错认窗前唾绣绒。"]},{"t":"露华 玉簪","f":"曲","c":["瀛洲种玉。","总付与花神，月底深斸。","琢就瑶笄，光映鬓云斜矗。","几度借取搔头，别试汉宫妆束。","风露冷，幽香半襟，淡伫阑曲。","亭亭雪艳愁独。","爱粉沁冰筒，须拈金粟。","石上那回磨断，争忍轻触。","一自楚客归来，珠履旧游谁续。","秋梦起，残妆半簪坠绿。"]},{"t":"寄题顾仲瑛玉山诗一百韵","f":"五言古诗","c":["治理逢熙运，钦明仰圣皇。","至仁侔覆载，上德配轩唐。","大业勤宏济，元臣协赞襄。","贤科收俊造，庭实璨圭璋。","入贡徕符拔，仪韶下凤凰。","普天均雨露，绝域总梯航。","每念京师食，遥需漕府粮。","神妃所庇护，飓母敢飞扬。","前队貔貅发，先驱罔象藏。","冷飙鼓万舵，朱火耀连樯。","帝策申嘉惠，祠官按典常。","赏劳兼湛濊，旌烈特巍煌。","仆本中林士，久陪东观郎。","遂叨乘驿传，遍与礼灵场。","簜节雕龙饰，华旗画隼翔。","冲流度鄞越，陟险过泉漳。","缅彼湄洲屿，崭然钜海洋。","蛟穿崖破碎，鲸蹴浪撞搪。","震鼓轰空阔，奔帆截渺茫。","岛夷迎使舸，瘴雾避天香。","嘉荐歆芬苾，阴功助翕张。","精诚致工祝，景贶答祯祥。","贾舶倾诸国，舆图奄八荒。","身虽距闽峤，志已略扶桑。","裴洞三生梦，温陵十月凉。","兹游平昔冠，夙愿一朝偿。","女髻皆殊制，蛮音各异乡。","地偏宜荔子，人最贵槟榔。","酿鹿肥漂酒，浇蚝液满房。","招贤簇车骑，挥扫积缣缃。","穷腊才竣事，暄春始趣装。","剑津传警急，汀贼起狓猖。","獠砦旋戡定，藩垣慎捍防。","思亲弥切切，行役更遑遑。","狐死嗟奚首，龟占喜允臧。","封崇晏坞内，木拱计峰旁。","薄宦祇牵率，孤踪易感伤。","暂为江左客，谁洒墓头浆。","逝矣川涂阻，凄其涕泪滂。","南园恰啼鴂，北路复鸣螀。","粤若娄东邑，由来汉太仓。","机云存故宅，吴会画雄疆。","遁迹晞高士，遗风挹让王。","厥田尤沃衍，比岁适丰穰。","老我张承吉，新知顾辟疆。","闻君占形胜，筑室恣徜徉。","铁笛留严客，青钱乞泰娘。","杏鞯红叱拨，兰柱绣鸳鸯。","辟径通佳处，栽桃带柳塘。","脩梧羽葆盖，美竹碧琳琅。","列岫浓螺色，澄湖净镜光。","鸟边岚漠漠，鱼外水泱泱。","鹤驻游仙馆，鸾鸣种玉冈。","投竿钓月槛，隐几读书床。","云结芝英秀，花团桂树苍。","舫斋青筱箔，渔舍绿苔墙。","栋宇环相属，园池郁在望。","直疑金谷墅，还似辋川庄。","未获窥诗境，相邀到草堂。","开樽罗绮馔，侑席出红妆。","婉态随歌板，齐容缀舞行。","新声《绿水》曲，秾艳《大堤》倡。","宛转缠头锦，淋漓蘸甲觞。","弦松调宝柱，笙咽炙银簧。","倚策骖联辔，钩帘烛绕廊。","僰僮供紫蟹，庖吏进黄獐。","卜昼宁辞醉，留欢正未央。","分司莫惊坐，刺史欲无肠。","是集俱才彦，虚怀共颉颃。","珠玑散咳唾，律吕应宫商。","郑老经术富，于仙词翰长。","琦初灯并照，郯华骥同骧。","璧色笺毫健，吟篇綵绘彰。","拈题争点笔，得句倏盈箱。","劲敌千钧彀，精逾百鍊钢。","语奇凌鲍谢，体变失卢杨。","瑛甫早有誉，亨衢那可量。","抟扶看怒翼，腾达待蜚黄。","既笃朋情重，仍持雅道昌。","披襟视肝胆，刻琰播文章。","永契欣依托，衰踪顿激昂。","盍簪承伟饯，授简藉馀芳。","自鄙冥搜拙，徒令属对忙。","端如享敝帚，何异贮奚囊。","谈笑聊堪接，赓酬曷足当。","吾犹郐以下，公等楚之良。","瓠落浑无用，艰难寔备尝。","拟为覂驾马，竟作触藩羊。","箸力频驰骛，功名几慨慷。","不嫌成晚合，深幸际时康。","邂逅因斯会，暌违又一方。","匆匆把别袂，眷眷赋河梁。","鸿雁清秋日，蒹葭昨夜霜。","关山凝朔气，星斗丽寒芒。","疾病家多难，归休岁亦阳。","苦心甘寂寞，短发任苍浪。","漏屋愁荷盖，尘衣惜蕙纕。","杜陵非固懒，贺监岂真狂。","回首长追忆，缄诗远寄将。","乾坤浩今古，此意讵能忘。"]},{"t":"堂堂","f":"五言古诗","c":["朝为堂堂吟，暮为堂堂讴。","堂堂徒尔奇，堂堂徒尔忧。","不见膏与兰，煎燔祗自休。","勿以不遇故，弃捐经与史。","勿以势利故，弃捐廉与耻。","勿以行役故，弃捐山与水。","谓夜未遽央，已复明星明。","仰视何煌煌，白露忽沾裳。","怀人搅余心，何以勿永伤。","江北亦为客，江南亦为客。","为客多偪兀，何以安所适。","上有君与亲，下有妻与息。","在山则种榆，在隰则种蒲。","马牛必维娄，舟航必繻袽。","富贵富贵友，贫贱贫贱徒。","岁月来者多，江湖逝者远。","所得不可逝，所期不可返。","幸此世累轻，归去衡门偃。"]},{"t":"杂诗七首 其一","f":"五言古诗","c":["先人有夙训，闻在幼壮时。","岂意衰暮日，乃复新验之。","茫茫上天理，讵可私臆知。","百年大化中，流浪从推移。","信彼杞忧者，徒为众所嗤。"]},{"t":"杂诗七首 其二","f":"五言古诗","c":["叔子邻家儿，探环记前身。","次律求师后，一悟了宿因。","我亦清源洞，蜕骨岩下人。","误堕声利区，驱驰丧其真。","所以付樽酒，都忘贱与贫。","惜无还丹术，高举遗世尘。","悠悠笙鹤期，旷望三山津。"]},{"t":"杂诗七首 其三","f":"五言古诗","c":["寒日迫县车，寸阴老愈惜。","晨趋理公务，暮返亲坟籍。","究往发孤愤，思来抱深惕。","理惬复相忘，神劬聊一息。","湛然拥襟坐，栩栩鼻端白。","千龄与化终，不朽在方策。","圣哲有明训，学道庶自益。"]},{"t":"杂诗七首 其四","f":"五言古诗","c":["寒夜何皛皛，中庭积繁霜。","天风下河汉，万里流玉光。","羽衣四三人，各乘白凤凰。","笙响发空际，游云高驰翔。","无缘执霞佩，揽结双明珰。","愿托月中桂，终古有馀芳。"]},{"t":"杂诗七首 其五","f":"五言古诗","c":["陇坂何崎岖，行人且复止。","直上望晴川，遥遥忆乡里。","流离肝肠断，悲歌不能已。","一身已遐征，永念同室子。","何殊转蓬科，随风四散起。","虽得同根生，不得同根死。","吾洒古今泪，多于陇头水。"]},{"t":"杂诗七首 其六","f":"五言古诗","c":["春江采瑶草，将以伸缱绻。","初期拾翠洲，复道滋兰畹。","美人隔花深，歌竟瑶瑟偃。","临流不可见，恍忽心未稳。","佳时难骤得，鶗鴂鸣已晚。","祇有千古思，绵绵楚波远。","黎丘之丈人，归路逢奇鬼。","既为鬼所惑，又复鬼其子。","夏南滑蜀梁，俯影明月里。","背走谓伏鬼，而又鬼诸已。","此皆非鬼者，特以疑故死。","憧憧奸佞徒，情状实鬼尔。","匿迹不自惭，胡为满朝市。"]},{"t":"杂诗七首 其七","f":"五言古诗","c":["河淮厌兵祸，城邑多荒榛。","百里无几家，但见风起尘。","燕雀归果树，豺虎饥食人。","乡来脂膏地，死骨今如银。","流亡使复业，牛种当及春。","安得百龚召，错落为拊循。","征讨尚未息，奈何尔遗民。"]},{"t":"前出军五首 其一","f":"五言古诗","c":["前军红衲袍，朱丝系彭排。","后军细铠甲，白羽攒鞲靫。","辎车左右驰，万马拥长街。","送行动城郭，斗酒饮同侪。","壮士当报国，毋为故乡怀。"]},{"t":"前出军五首 其二","f":"五言古诗","c":["锻铁作佩刀，磨石为箭镞。","中军把辕门，前竖十丈纛。","朝上芦沟桥，夕次泃河曲。","超乘既誇勇，骋马复齐足。","男儿不封侯，百年同视肉。"]},{"t":"前出军五首 其三","f":"五言古诗","c":["昨日发万军，今日发万军。","明日发万军，枭骑来群群。","马蹄所经过，黄埃荡成云。","堆粮与作饭，倒树与作薪。","道途行者绝，那得有居人。"]},{"t":"前出军五首 其四","f":"五言古诗","c":["大军北庭来，部伍各有屯。","放马原隰枯，磨刀河水浑。","行行且射猎，雉兔不复存。","野次群驼卧，弓箭挂车辕。","幽幽笛声起，日暮伤人魂。"]},{"t":"前出军五首 其五","f":"五言古诗","c":["京师少年子，胆气乃粗豪。","倾金售宝剑，厚价买名刀。","白毡作行帐，红绫制战袍。","结束往从军，谈笑取功劳。","当时霍嫖姚，岂在学戎韬。"]},{"t":"后出军五首 其一","f":"五言古诗","c":["步卒伧楚健，长刀短甲衣。","大叫前搏敌，跳荡如鸟飞。","左提血髑髅，右夺贼马归。","黄金得重赏，顾盼生光辉。","尔辈疾归命，将军足天威。"]},{"t":"后出军五首 其二","f":"五言古诗","c":["我军城东门，呼声震屋瓦。","百万山压来，此贼何足打。","狂锋尚力拒，转斗血喷洒。","城中有暗沟，多陷人与马。","将令毋轻入，明当一鼓下。"]},{"t":"后出军五首 其三","f":"五言古诗","c":["先锋才攻门，后军已登陴。","拔都不怕死，直上搴贼旗。","马前献逆首，脚下踏死尸。","长河走败船，疾遣飞将追。","幕中作露板，应有傅脩期。"]},{"t":"后出军五首 其四","f":"五言古诗","c":["行行铁兜鍪，队队金骆驼。","呜呜吹铜角，来来齐唱歌。","总戎面如虎，指顾挥雕戈。","马踶无贼垒，手箠可填河。","王师本无敌，安用战图多。"]},{"t":"后出军五首 其五","f":"五言古诗","c":["魔贼生汝亳，獠贼起于海。","婴锋天狗触，堕网奔鲸骇。","徐方一战收，振旅已奏凯。","江浙尘既清，豫章围亦解。","诸将如竭力，削平行可待。"]},{"t":"独酌谣","f":"五言古诗","c":["有酒且一醉，有歌且一谣。","杯尽当再酌，歌阕须重调。","生足意自适，身荣心苦焦。","所以黎首人，放浪乐渔樵。","一谣仍一酌，且复永今朝。","明朝未可料，况乃百岁遥。","但愿花长开，美酒长满瓢。","静疑太古调，散觉神理超。","近识南郭叟，得酒时见招。","尽醉即高卧，谁能慕松乔。"]},{"t":"古镜","f":"五言律诗","c":["古镜色如墨，照人不见形。","我照乃见心，洞彻天地明。","此明非外来，此明非内有。","自是世上人，惟将照妍丑。"]},{"t":"题林大用隐居饭牛山","f":"五言古诗","c":["山田多白石，阳陂足丰草。","瘦地费牛力，饭之当宿饱。","近午牛背热，出耕须及早。","解纼休树阴，念此觳觫老。","隐居抱正学，逍遥事幽讨。","商歌干齐侯，戚也岂知道。"]},{"t":"中秋望月","f":"五言古诗","c":["当年见明月，不饮亦清欢。","讵意有今夕，照此长恨端。","近闻钱塘破，流血城市丹。","官军虽杀贼，斯民已多残。","不知亲与故，零落几家完。","徘徊庭中影，对酒起长叹。","死生两莫测，欲往书问难。","仰视云中雁，安得托羽翰。","凄其衰谢踪，有泪徒汍澜。","山中松筠地，弃置谁与看。","河汉变夜色，西风生早寒。","累觞不能醉，百念摧肺肝。"]},{"t":"送客齐化门东马上口号","f":"五言古诗","c":["白杨多悲风，黄叶满行路。","荒沟寒水碧，乱石且无数。","我兴远送别，驻望生百虑。","欲往岂不怀，畏此简书故。","遥遥墟烟上，历历鸣雁度。","秋景倏己短，归人驱车去。","劳歌一凄然，回首重愁暮。"]},{"t":"阳曲义士薛氏旌表诗卷","f":"五言古诗","c":["上天久无雨，南风日吹沙。","旱气弥虫虫，六月稻不花。","晋土素硗瘠，如此岁食赊。","上官方劝分，义士起叹嗟。","发帑捐积镪，籴粟来连车。","吾乡忍沟壑，哺尔万口呀。","厚泽田里被，颂声父老誇。","预备世勿务，征敛惟纷拿。","遂令活人功，乃出一士家。","不知时有司，视此无愧耶。","我作义薛诗，好德良可嘉。","愿言讲荒政，生意当无涯。"]},{"t":"安童都事字鼎新号太虚徵余赋之集贤院","f":"五言古诗","c":["太虚本无象，何有倪与端。","至理妙自然，万化孰控抟。","天地亦一物，而在虚空间。","所以豪杰士，不受世网干。","脱迹形气表，出入凌汗漫。","鸾鹄为我导，云飙作之翰。","仰扳霄衢辔，俯濯龙池澜。","绿文粲瑶轨，高咏瀛洲山。","冥心合玄想，坐以空洞观。","琳腴荐朝食，紫金咀神丹。","无待无穷外，浩然与之还。"]},{"t":"漷农叹","f":"五言古诗","c":["漷南有农者，家仅一两车。","王师征淮蔡，官遣给军储。","翁无应门儿，一身老当夫。","劳劳千里役，泥雨半道途。","到军遭焚烹，翁脱走故闾。","车牛力既尽，户籍名不除。","府帖星火下，尔乘仍往输。","破产不重置，笞箠无完肤。","翁复徒手归，涕洟满敝襦。","问家墙屋在，榆柳馀残株。","野雉雊梁间，狐狸穴阶隅。","老妻出佣食，四顾筐箧无。","有司更著役，我实骨髓枯。","仰天哭欲死，醉吏方歌呼。"]},{"t":"题述律万户澹乐轩","f":"五言古诗","c":["惟澹有至乐，此乐世罕知。","谁能味无味，舍彼甘与肥。","君侯文武才，面有虎豹姿。","被甲起上马，出入百万师。","西来树功勋，献颂白玉墀。","方将大将权，绕帐罗旌麾。","纷华艳人目，孰不为朵颐。","顾于方寸间，物累乃若遗。","斋居寄遐赏，而无山林期。","处乐宁易言，岂独静者宜。","始知豪杰士，自有绝世资。","悠哉澹中趣，吾道同所归。"]},{"t":"送黄中玉之庆元市舶","f":"五言古诗","c":["昔我游四明，壮观溟海波。","褰裳宝山顶，曙色寒嵯峨。","日轮镕生金，涌出万丈涡。","云气忽破碎，朱光相荡摩。","决眦蓬莱宫，携手扶桑柯。","群仙迎我笑，佩羽纷傞傞。","飓风歘惊潮，腾掷鳄与鼍。","浮槎径可揽，从此超天河。","精神动百灵，上下烦撝诃。","归来已十载，远梦时一过。","君家贤父兄，儒术传世科。","薄言捧省檄，舶署聊婆娑。","是邦控岛夷，走集聚商舸。","珠香杂犀象，税入何其多。","权衡较低昂，心计宁有讹。","资阅须历试，壮图讵蹉跎。","惟君官事隙，为访岩之阿。","悬想仙者徒，往往笑且歌。","遐征渺不见，空响遥相和。","因声两黄鹄，持我紫玉珂。","岂无沧洲兴，奈此尘劫何。"]},{"t":"门有车马客行 其一","f":"曲","c":["坐秋雨思秋风，仰视白日云中。","彼美一人谁容，秉心郁其忡忡。"]},{"t":"门有车马客行 其二","f":"曲","c":["为客一鼓云何，慷慨起舞悲歌。","巨鱼出听凉波，鸣鸟徘徊庭柯。"]},{"t":"有客有客在门崔嵬高盖华轩起欲与之语言已叱仆夫回辕 其一","f":"曲","c":["宁不少忍须臾，谓我巷不容车。","北望豪家是趋，堂上有筝有竽。"]},{"t":"有客有客在门崔嵬高盖华轩起欲与之语言已叱仆夫回辕 其二","f":"曲","c":["盛衰相寻无端，媒劳恩绝则然。","还坐自乐我閒，勿谓无知绝弦。"]},{"t":"古促促辞","f":"曲","c":["促促何促促，丈夫生儿美如玉。","长城游荡不思归，令我只身守空屋。","不愿汝学班定远，不愿汝学马相如。","定远生不入玉关，相如死不还成都。","但如塞翁父子长相保，得马失马何足道。","又如庞公携家隐鹿门，遗安遗危俱不论。","贵而衣貂不如贫而缊枲，离而食肉不如聚而饮水。","身虽促促心得宽，为汝白头屋中死。"]},{"t":"北风行","f":"曲","c":["长河风急波浪恶，青天昼黄尘漠漠，瓠?渡中舟尽泊。","官船扯帆与水争，牵马毛寒挝不行，秃树挂戛枯蓬惊。","夜深风定浪声死，窗光倒摇天在水，前伴相呼随雁起。","帽絮不暖衣生棱，老贸不语愁河冰，上闸下闸应蹙凌。","篙师指直失增减，明星欲明霜似糁，馆陶城南鼓紞紞。"]},{"t":"萤苑曲","f":"七言古诗","c":["杨花吹春一千里，兽舰如云锦帆起。","咸洛山河真帝都，君王自爱扬州死。","军装小队皆美人，画龙鞯汗金麒麟。","香风摇荡夜游处，二十四桥珠翠尘。","骑行不用烧红烛，万点飞萤炫川谷。","金钗歌度苑中来，宝帐香迷楼上宿。","醉魂贪作花月荒，肯信剑戟生宫墙。","斓斑六合洗秋露，尚疑怨血凝晶光。","至今落日行人路，鬼火狐鸣隔烟树。","腐草无情亦有情，年年为照雷塘墓。"]},{"t":"城西路","f":"曲","c":["城西路，多少人从此中去。","昨日红颜美少年，今朝白骨委黄泉。","纵令藏金比山积，鬼伯不受人间钱。","少年何用誇豪富，来看城西送人处。"]},{"t":"发古城铺","f":"七言古诗","c":["黄蒿古城风捲沙，涧头衰树啼寒鸦。","岁云暮矣霜露积，夜如何其星汉斜。","满衣落月行人起，马上梦魂犹在家。"]},{"t":"王贞妇","f":"曲","c":["青枫岭头石色赤，岭下?江千丈黑。","数行血字尚斓斑，雨荡霜磨消不得。","当时一死真勇烈，身入波涛魂入石。","至今苔藓不敢生，上与日月争光晶。","千秋万古化为碧，海风吹断山云腥。","可怜薄命良家女，千金之躯弃如土。","奸臣误国合万死，天独何为妾遭虏。","古来丧乱何代无，谁肯将身事他主。","兵尘澒洞迷天台，骨肉散尽随飞埃。","枫林景黑寒燐堕，精灵日暮空归来。","堂堂大节有如此，正当庙食依崔嵬。","君看?江之畔石上血，当与湘江之竹泪痕俱不灭。"]},{"t":"题昌化陈孝子传","f":"七言古诗","c":["百丈山前妾逢主，礼贤镇中子逢母。","三十馀年昨日同，白发相看泪如雨。","阿㜷去时未断乳，儿壮得知心独苦。","清湖老妪天所留，逆旅主人神使语。","归来桑竹溪之浒，妇前持觞儿起舞。","双瓜生祥表秋圃，岂用旌书动官府。","吴人买妾纷莫数，岁满母归遗子女。","巷南巷北不相觅，况复山川两脩阻。","呜呼千秋复万古，孝子之名在寰宇。","世上滔滔忘母人，不愧唐昌一抔土。"]},{"t":"题铁石骢马图","f":"七言古诗","c":["神厓黑龙时出水，游牝何年得其子。","是何毛骨如积铁，迥立长风独奇伟。","霜蹄白鼻散五花，倏见马中真騄駬。","美髯奚官能剪拂，不遣云鬟涴泥滓。","少施鞚勒即飞腾，唾尚不敢况敢捶。","马生岂在粟一石，不饱宁能见才美。","朝燕晡越信汝良，安得壮士同生死。","阿师一室巾锡外，时展此图临燕几。","三生似是支道林，爱马苦心同若此。","平原丰草秋漠漠，恍惚寒沙飒然起。","英雄有志在青云，老眼因之空万里。"]},{"t":"题赵文敏公画马","f":"曲","c":["君不见汉家将军求善马，战骨纵横血流野。","归来作歌荐宗庙，宁悲鬼哭宛城下。","何如圣代德所怀，入献磊落皆龙媒。","右牵者谁鬈者偲，万里知自宛沙来。","眼光镜悬蹄腕促，老奚识性仍善牧。","时巡之外游幸稀，饱秣原头春苜蓿。","吴兴学士艺绝伦，妙处直似曹将军。","只今有马无此笔，谁与写之传世人。","为君甘老驽骀群。"]},{"t":"题牧牛图","f":"七言古诗","c":["去年苦旱蹄敲块，今年水多深没鼻。","尔牛觳觫耕得田，水旱无情力皆废。","画中见此东皋春，牧儿超摇犊子驯。","手持鸲鹆坐牛背，风柳烟芜愁杀人。","儿长犊壮须尽力，岂惜辛勤供稼穑。","纵然喘死死即休，不愿徵求到筋骨。"]},{"t":"题李白观泉图","f":"七言古诗","c":["玻瓈杯中春酒绿，醉墨淋漓牡丹曲。","平生合置七宝床，白纻乌纱美如玉。","阿瞒荒宴百不理，宁记宫花衔野鹿。","何物老妪生此儿，偷向金鸡帐中宿。","高将军才奴隶耳，误使脱靴吾所辱。","要留污袜踏鲸鱼，鼠子何堪烦一蹴。","寻常沟渎不可濯，何处容伸遭污足。","翩然却下匡庐云，五老峰前看飞瀑。"]},{"t":"题郝内翰书所作梦观琼花赋后","f":"七言古诗","c":["钓鱼山前龙上天，武昌城外走蜀船。","老奸欺国驰露布，使者坐囚吞雪毡。","溃兵一夜甲填水，血污木棉花下鬼。","岂知老仙方卧游，鹤背天风扶梦起。","颓云抉月光西流，玉箫声断江声愁。","露华泣尽琼树死，广陵春色寒于秋。","百年遗赋人争重，劲墨遒毫精爽动。","节旄零落喜生还，回首江南已如梦。","花神换根春更芳，想像月色扃馀香。","楚招无人青鸟去，公不少留涕泗滂。"]},{"t":"题赵仲穆怪石奇木","f":"曲","c":["君不见岳阳城南老树能化人，又不见草中巨石如卧虎。","树逢仙客授还丹，石误将军箭飞雨。","海宁太守提健笔，与丹通灵箭角力。","山精木魅寒睒䁑，千年丑怪匿不得。","衔瘤半裂雷大出，隐入云绡露奇迹。","猝然一见心胆惊，气尽画工俱辟易。","挂之高堂风动摇，古色一片秋萧萧。","待候砚池卷东海，归写扶桑与沃焦。"]},{"t":"题长孙皇后谏猎图","f":"七言古诗","c":["黄门晓出西清仗，秋色满天鹰犬王。","虎落遥连渭水南，鸾旗直度河桥上。","日边云气五色文，虬须天子真天人。","羽林猛士森成列，六气不惊清路尘。","太平无征帝神武，岂为禽荒将按部。","已知哲后佐兴王，不数樊姬能霸楚。","从容数语即罢田，六宫迎笑花如烟。","跸回那待外庭疏，听谏由来同转圜。","天宝神孙隳大业，锦绣五家争蹀躞。","可怜风雪骊山宫，正与真妃同射猎。"]},{"t":"题华山图","f":"七言古诗","c":["华岳连天向西起，澒洞秦川三百里。","巨灵高掌削芙蓉，影落黄河一线水。","云台雾谷巢神仙，羽衣金节时周旋。","大笑失脚白骡背，归来石上长鼾眠。","千载悠悠寄玄赏，耳孙风骨犹萧爽。","远从丹丘渡沧海，追挹神踪欲长往。","何人想像图真形，叠崖阴洞高林青。","上摩金天之帝京，下揽玉女之明星。","峰耶麓耶两莫极，虎豹叫绝烟霏冥。","仙家楼观超然住，遥认微茫是征路。","丹梯铁锁不可攀，直唤茅龙上天去。"]},{"t":"懒拙道人苕溪晓望图","f":"七言古诗","c":["忆昔薄游苕之城，溪光近秋山晚晴。","连峰接嶂望不极，惟有白云纵复横。","渔村无林树墨色，微风忽起菰蒲声。","月从太湖东畔出，直射西塞山前明。","人家碧玉壶中住，野舫银河天上行。","酒酣时起发长啸，水底直遣鱼龙惊。","老晖乡亦此盘礴，安知今我非三生。","尽搜万象入奇笔，画与诗境俱峥嵘。","吾家苕中有茅屋，京尘满鬓难为情。","顿令扁舟夜入梦，万顷鸥波归濯缨。"]},{"t":"金宣孝太子墨竹","f":"曲","c":["沙海神光射天起，中有蟠龙龙有子。","混同江声何处来，卷作淋浪墨池水。","蜿蜒欻起鳞鬣张，蜕骨立化千筼筜。","一朝侍臣抱髯泣，鹤驾不归云路长。","百年梁苑陵谷变，流落人间能几见。","明昌内府应秘藏，小字亲题保成殿。","吁嗟帝子真天人，此君亦作天人真。","君不见洋州老太守，挥洒虽工无此神。"]},{"t":"绿玉连环歌为邢从周典簿作","f":"七言古诗","c":["于阗河头夜光发，赤髯贾胡采明月。","中有美璞凝寒晶，唯许鬼工能琢成。","伊谁得此邢公子，示我绿玉双连理。","恍如空碧虹气垂，半隐青瑶蟾一规。","展之两环不逾尺，叠作团团小苍璧。","縠文错落映雷文，宛是昆吾宝刀刻。","庐陵学士癖好奇，辨古重似琼琚词。","珊瑚佩钩讵可数，我疑制自金源时。","集贤仙公丈人行，凤阁舍人文有样。","请君留束宫锦袍，待看挥毫玉堂上。"]},{"t":"并州歌送张彦洪使毕还河东","f":"曲","c":["吾乡故人零落尽，见子老成殊慰心。","祥金百鍊乃利器，桐尾方焦逢赏音。","河东臬府幕下士，飞传来作朝正使。","太和岭上盗已空，旌旗尽是官军红。","杀人如麻道路绝，朝狐暮枭竞巢穴。","严风歘起霜倒飞，塞日黯淡寒无辉。","子来未几遽言归，使我东望泪沾衣。","岂不闻并州少年游侠子，手携玉龙最轻死。","并州将军刘越石，夜半登临长啸起。","汾河直来绕郡城，雁门离石寒峥嵘。","老旻四叶弹丸地，大梁全师劳再征。","一朝征贼辄破碎，大将不诛天失刑。","为子作歌歌愤激，眼中太行如动色。","安得壮士射乌弓，为落搀抢连太白。"]},{"t":"刘道权为李远子微作青山似洛中图为作歌以系之","f":"曲","c":["石头城中有渺渺之秦淮，秦淮东流入江远，其上叠巘连鲁厓。","牛头双阙云门开，三山北山郁烟霾。","六朝遗迹犹在眼，千古往事徒兴怀。","昔人谓此洛中似，四面青山围二水。","刘侯熟识此景胜，况复爱画入骨髓。","五尺长纸茧不如，乘兴破墨涂成图。","渔梁茅屋昏欲无，坏陵荒陇迷楸梧。","寒潮已落断崖阔，行人不渡扁舟孤。","嵩邪邙邪漫漶那可辨，但见招提林杪直下藏村墟。","忆我羁游石城日，江烟山雨正萧瑟。","横塘酒家好新酒，醉倚船窗看奇崛。","只将健句写归来，却恨此时无此笔。"]},{"t":"吴俊仲杰横河精舍图亦道权作","f":"曲","c":["横河精舍谁所居，丰城隐者吴仲杰。","是中林壑特幽胜，一幅刘权画尤绝。","远山数曲重复重，炊烟一村树丛丛。","岚光云气纷滉瀁，盱水汝水遥相通。","近山什伯青匼匝，峰底斜穿鹧鸪峡。","跳波直下却洄漩，怪石截断双流合。","竹窗桂栋溪之隅，过门好客无时无。","溪鱼长肥酒长熟，拨弃世务谈诗书。","梧州春雨草木长，榉塘耕稼仍膏壤。","锄翁牧子行唯诺，沙鸟风帆自来往。","独不见陶县令松菊园，又不见杜陵老桑麻田。","人生得此不归去，有如头上之青天。","杰乎杰乎吾羡汝，毋负山中故人招隐篇。"]},{"t":"崔旭行之云巢图赠道士俞刚中请余赋长歌","f":"楚辞体","c":["崔郎胸次奇突兀，兴来从人索纸笔。","斯须千峰万峰出，底用一石画五日。","上饶道人列仙癯，示我新作云巢图。","涂岚抹雾思更逸，古色满眼苍寒俱。","重溪叠谷各异状，坏木崩石森相向。","翠微最上云所栖，道人又在云之上。","数椽丹室荫白茅，团团云间如一巢。","拂衣拂著宿鹤背，挂剑挂落长松梢。","空濛杳霭迷处所，岂复漂摇畏风雨。","既非鸟窠老衲子，无乃中林古巢父。","填窗拥户昼不开，神光隐见金银台。","云之君兮凤为马，往往玉箫吹月来。","道人几年游上国，卖药壶中人不识。","洞玄宫观一黍珠，灵秀似与仙都敌。","故巢未破归便得，归到玉山多美石。","我诗毋刻刻此图，留照千秋山水碧。"]},{"t":"送崔让士良都事江淮行省","f":"曲","c":["时平久不脩武备，一旦盗贼起跳踉。","南窥荆邓北徐汝，红巾直来据武昌。","摧城破壁官吏走，九江太守能死守。","赤眉铜马终殄除，此贼游魂?得久。","天兵势若风雨来，直扫四野无氛埃。","庙谟最先择元帅，国计莫重完江淮。","堂堂中书开外省，幕府人材倚公等。","崔侯如刃新发硎，锋锐所当无肯綮。","金汤表里元有捷，正藉前筹资薄伐。","草茅有策可采用，义士多方须教阅。","酒酣客起征马鸣，壮气满髯肝胆倾。","浩歌把剑徒激烈，老矣莫赋从军行。"]},{"t":"为古绍先题刘平妻胡氏杀虎图","f":"七言古诗","c":["沙河岸边秋草白，枣阳城头落日黑。","老兵辛苦践更来，林下税车聊一息。","黄芦飒飒中夜鸣，伥鬼叫啸悲风生。","虎饥得人怒不置，妇急徒手危相争。","直前死力持虎足，呼儿进刀屠虎腹。","但知有夫岂知虎，视之何殊机上肉。","当时一击宁顾躯，惊魂碎骨仍携扶。","九原瞑目已无憾，旧血勿湔身上襦。","千秋节义传乡闾，我犹胆怯见画图。","健妇果胜一丈夫，向来冯妇有不如。"]},{"t":"城南","f":"七言律诗","c":["城南北风朝卷沙，将军开宴树大牙。","黄须健儿饱酒肉，十十五五来将车。","尽驱丁男作生口，鬼妾鬼马充其家。","呜呼上天不可问，道旁观者徒咨嗟。"]},{"t":"张师夔为郭子静作终南山色因题","f":"七言古诗","c":["终南山色秀可食，中有游云动凝碧。","华岳西面仙掌高，仙都下射金精白。","绀宫琳馆凭险阻，渭水晴川来咫尺。","古木深藏魍魉寒，阴厓晓入蜿蜒黑。","幽人旧隐依青壁，萝径紫篱闭寥阒。","野桥插岸何处船，落日无人独归客。","栎翁笔法追郭熙，远意欲寄烟霞微。","半生江海屡惊梦，万里风尘能化衣。","捷径无媒既愁寂，故山好在曷遄归。","尚说于今明月夜，时有箫声台上飞。"]},{"t":"天香室为四明定水复见心禅师赋","f":"曲","c":["定水山中多古桂，老璘结茅来避世。","囊中少试蒸花法，正藉烟霏作舆卫。","谁令作诗传世人，一时搅动声闻尘。","百年公案结未了，复翁拈起还清新。","唱开石壁壁成字，百颗明珠照天地。","不关旃檀林下风，薰破枯禅半边鼻。","吾闻佛家别有众香国，我亦三生学禅客。","若为一洗六根空，从子归来分半席。"]},{"t":"题赵文敏公木石有先师题于上","f":"七言古诗","c":["吴兴笔法妙天下，人藏片楮无遗者。","南阳诗律动江湖，一篇才出人争写。","二老风流倾一时，只今传画仍传诗。","清涵月露秋见影，黑入雷雨寒无姿。","仇山黄鹤去不返，苕溪鸥波岁俱晚。","好呼铁爪夜铮铮，刻向青珉照人眼。"]},{"t":"题武林姚氏颐寿堂","f":"曲","c":["有地须种木兰花，有树好宿双啼鸦。","木兰女儿能代父，慈鸦之雏能哺母。","姚家堂中如画图，鹤发高居彩衣舞。","当年兵尘暗乡关，扶携稿砧烟瘴间。","天留晚福在平世，去家万里仍生还。","有儿有妇供滫瀡，书声歌声动邻里。","板舆不待鱼轩，列鼎不如负米，中有至乐物莫比。","酌彼金罍酒，起为颐颜寿。","堂前日日春风和，棘心之诗岂足多。","我今独无空尔羡，如此堂中萱草何。"]},{"t":"题雪溪待渡图","f":"七言古诗","c":["晋阳山下蒲村渡，断坂连冈叠烟树。","横汾水落流更急，客子西归迫秋暮。","朔风转雨作雪飞，倚盖沙头泥没屦。","后来者谁须我友，望望津船出前溆。","湿云扑地边鸿惊，危桥挂岸征马生。","樵家有径冻叶平，土床火煖无人声。","乱峰倒倚白石烂，空壑半压冰槎横。","归来想像犹眼底，讵拟褐夫能画此。","溪明雪净古色起，一片荒寒在窗几，岁晚远游吾倦矣。"]},{"t":"题李早女真三马扇头","f":"七言古诗","c":["金源六叶全盛年，明昌正似宣和前。","宝书玉轴充内府，时以李早当龙眠。","想当画院供奉日，饱阅天闲万奇骨。","等閒游墨落宫扇，骏气凌风欲超忽。","雾鬣风鬉剪剔新，郎君丰格玉为人。","四带纱巾绣衣领，醉鞭踏尽燕台春。","一声白雁黄河暮，岂料征蹄竟南渡。","回首西风障战尘，女仙空抱琵琶去。"]},{"t":"题陈所翁九龙戏珠图","f":"七言古诗","c":["两龙颉颃出重渊，白日移海空中悬。","一龙回矫一倒起，侧磔胡髯怒喷水。","火珠炎炎如弹丸，爪底云头争控抟。","一龙仰首逆鳞露，两龙旁睨苍崖蟠。","怪风狂电浩呼汹，天吴倅立八山动。","一龙后出尤崛奇，半尾戏绕蜿蜒儿。","儿生未角已神猛，一顾却走千蛟螭。","陈翁砚池藏霹雳，往往醉时翻水滴。","便觉天瓢入手来，雨气模糊浑是墨。","我尝见画多巨幅，簸荡惊涛骇人目。","何如此笔穷变化，三尺微绡形势足。","是翁前身定龙精，故能吸歘奔精灵。","卷图还君慎封鐍，但恐破壁飞空冥。"]},{"t":"题侍郎秋江捕鱼图","f":"七言古诗","c":["秋江水多鱼唯唯，海风驱潮葭菼靡。","轻舠竞载罛网出，欲向中流截鲂鲤。","巨鳞有神不可获，腾踏波涛脱泥滓。","最怜濡沫笭箵间，小白针头尖如指。","钓璜渭叟晚终遇，西塞玄真徵不起。","若人自是隐者徒，岂比沙岛渔蛮子。","高髯能画得玄理，涂抹山川游戏耳。","千岩万壑堆白云，稍看人家乔木底。","眼中之景何所似，富春泽畔鸬鹚里。","两台萧瑟秋风高，脚底滩声荡清泚。","我当扁舟冲雁过，彷佛厓根旧曾舣。","自知世外渔者村，只合投竿老烟水。","巨缁未办五十犗，草屩捞虾从此始。"]},{"t":"画马","f":"七言古诗","c":["睿思殿中万几暇，缥带犀签阅名画。","君王爱此神骏姿，笔势不在韦韩下。","五云御押手自封，玉窠蟠屈宸篆红。","百年重遭赤马劫，散落不逐兵尘空。","谁欤传之能爱惜，尺楮萧萧开古色。","骊骢玉面蹄腕白，青丝络脑黄金勒。","风鬉半散头怒侧，一团渥洼云气黑。","绯衫圉郎紧控持，直恐骄腾收不得。","向来南渡小朝廷，虎视欲与金源争。","蜀襄马场能几匹，尚想按图心胆倾。","只今万里龙沙道，游牝千群饱丰草。","天闲上驷皆乘黄，驽蹇纷纷世空老。"]},{"t":"赠吴士桑饶","f":"曲","c":["吴兴一士气貌醇，儒冠落魄甘长贫。","医家诸书总贯穿，有病有药即与人。","山中僦屋不肯出，苦厌城市多嚣尘。","得钱沽酒饮即醉，指点富贵如浮云。","时来西湖住几日，所宿随夜餐随晨。","过门与我谈抵掌，百无一伪皆天真。","疾恶如雠每愤激，正坐时命遭其屯。","人生除贫贫则已，五鬼到此安能神。","天以清名补寒饿，昔之隐者人皆闻。","圣贤法则吾岂敢，乡里小儿安足云。","况君能医当济世，未叹行路常踆踆。","伸眉一笑索我别，北风吹雪来缤纷。","溪畔无钱附归去，垂橐不管妻子嗔。","青山白石大自在，且复挂子头上巾。","江湖多芦识者少，岁晚远游须待春。","君不见舍中之长眼眦肉，岂解善事长桑君。"]},{"t":"题泰东山藏主十八开士图","f":"曲","c":["环瀛茫茫去不穷，大鲸吹浪鼓飓风。","楼船如山不敢过，况在泛苇浮萑中。","西方十八大尊者，径渡万里犹乘空。","犀行水开蛟蜃露，直下踏入天吴宫。","龟鱼背高盂锡稳，中流正与灵槎同。","怪头达拚四罔象，一单舁出庞眉公。","鼻端嘘气作飞塔，舌上弹咒招降龙。","两僧促膝披贝叶，一衲裹足须山童。","雪毛白鹿岐角健，斑尾黑虎双睛红。","最后坐禅如古佛，从渠抟控何神通。","吾闻浮屠多善幻，作诗自赏画者工。","君不见海波横溃鬼神恶，我无其术安能东。"]},{"t":"重赋明山歌送胥式有仪还武昌","f":"楚辞体","c":["盱母城南隐居者，一生耕凿盱南野。","何年移入明山来，筑楼山颠云在下。","环山小坞三十六，中有清池荫桑竹。","日高坞口烟雾消，稍见行人出深谷。","池头古井穿石空，绝底暗与江流通。","井中鲤鱼长尺半，人不敢取疑蛟龙。","隐居何人曾子白，谁其从者胥生式。","先生喜与山为徒，意不在仙在楼居。","胥也来读山中书。","溪翁野老时时一相过，有筐盛蕨兮有酒盛壶。","兴酣题诗满青壁，墨痕入石青模糊。","华盖浮丘，石门麻姑，邻峰丘壑可游衍，山中之乐足以遄吾躯。","生今掉头不肯住，京尘茫茫岁云暮。","岂知卬亦爱山人，未办山赀得归去。","曾先生，几时把袂明山行，洒扫楼上听松声。","黄精饱啖一千日，飞上丹梯朝玉京。"]},{"t":"息斋竹石古木为会稽韩季博士题","f":"七言古诗","c":["老竹叶稀多秃枝，新竹碧润含幽姿。","箨中龙子振春蛰，突出雷雨头参差。","旁蹲怪石石罅裂，裂处恍惚疑龙穴。","山中有树皆十围，活干撑青死槎折。","霜皮食尽乾藓文，半顶斩立双桠分。","最后一枝身出群，垂枝倒走阴崖云。","李侯标致不可得，小字亲题别涂黑。","纵横不在摩诘下，萧爽直与洋州敌。","玉堂学士欣见之，浓墨大书真崛奇。","森然一片铁石笔，妙甚七字琼瑰词。","此诗此画今两绝，把玩微风动毛发。","只应真宰泣雕镂，一夜山窗冷秋月。"]},{"t":"昆山寺","f":"七言古诗","c":["昆山突兀摩空苍，寺幽更枕山之阳。","松杉高出人境外，楼阁半在天中央。","日照檐楹分杳霭，风回廊庑添清凉。","谷声远合蒲牢韵，林近时闻薝卜香。","红尘咫尺到不得，黄金地面生辉光。","我疑意在融结际，真宰用意非寻常。","云埋烟蔽岁月古，未与时会犹潜藏。","一旦宝像顿发见，果闻玉磬鸣高冈。","二生开示此经始，源流既浚深必长。","乃知景物不自胜，惟人方可存其纲。"]},{"t":"休洗红二首 其一","f":"曲","c":["休洗红，洗红红在水。","新红换作裳，旧红翻作里。","回黄倒绿无定期，世情翻覆君所知。"]},{"t":"休洗红二首 其二","f":"曲","c":["休洗红，洗红红减色。","虽好不如新，著时须爱惜。","阿母嫁女不择人，鸡飞狗走长苦辛。"]},{"t":"悲寒风","f":"曲","c":["夜漫漫，风凛凛，严霜下，寒更甚。","狐鸣鬼啸有今夕，仓卒剑戟生高枕。","神光堕地摧白虹，呜咽英雄泪空饮。"]},{"t":"登歌风台","f":"五言律诗","c":["君王逝已久，遗构在彭城。","空阔青徐坼，苍茫楚汉争。","荒山尚云气，乔木有风声。","无限登临意，长歌慷慨生。"]},{"t":"黄河","f":"五言律诗","c":["橹后风才顺，桅头日未斜。","旧河通瓠子，新浪涨桃花。","得鲙因沽酒，闻鹃更忆家。","迢迢云气外，北望是京华。"]},{"t":"泊淮口","f":"五言律诗","c":["滟滟潮初上，移舟出浦中。","岸分清浊水，帆掉合离风。","伧楚方言杂，徐扬地利通。","何殊入乔口，怀古思无穷。"]},{"t":"蚤发鲁桥","f":"五言律诗","c":["路滑雨初歇，山昏云不开。","看镫野店近，闻铎贾车来。","马饱力方健，蛬寒声易哀。","偶逢南去使，早早附书回。"]},{"t":"泊隆兴章江门","f":"五言律诗","c":["把酒西风里，挂帆南斗傍。","夕阳城角尽，人影水中长。","问俗劳羁旅，干时儗俊良。","平生槎上意，漂转益难忘。"]},{"t":"次曹娥江","f":"五言律诗","c":["庙貌丹青古，碑词风雨讹。","珓投估客拜，神降女巫歌。","沙灶烧盐速，潮船聚堰多。","贞魂招不得，挥泪大江波。"]},{"t":"还自临江省亲鄞之长山元日有作","f":"五言律诗","c":["茅屋鹿皮几，柴扉乌角巾。","杯盘丰海味，礼数略乡人。","树霁石湫晓，山暄槎浦春。","僻居无一事，即是葛天民。"]},{"t":"衡山福严寺二十三题为梓上人赋 其一 般若寺","f":"五言律诗","c":["般若南朝寺，思公第一传。","拓开方丈地，坐断再生禅。","贝叶收经夹，昙花散法筵。","山神应夜夜，来礼佛灯前。"]},{"t":"衡山福严寺二十三题为梓上人赋 其二 一生岩","f":"五言律诗","c":["初地灵峰下，重来为讲经。","神应合掌受，石亦点头听。","云鹤随飞盖，湖龙入净瓶。","至今花雨处，长照一镫青。"]},{"t":"衡山福严寺二十三题为梓上人赋 其三 二生塔","f":"五言律诗","c":["塔寺前朝旧，山林宿业空。","法身无幻坏，藏骨自神通。","宝供珊瑚碧，珠花舍利红。","无缘香一瓣，回首佛堂中。"]},{"t":"衡山福严寺二十三题为梓上人赋 其四 三生藏","f":"五言律诗","c":["神僧涅槃处，那有去来今。","尚记三生石，难磨万古心。","地埋禅刹在，山掩岳祠深。","长日闻钟梵，萧萧枫桂林。"]},{"t":"衡山福严寺二十三题为梓上人赋 其五 天柱峰","f":"五言律诗","c":["一柱标南纪，神功自断鳌。","寒过岣嵝远，势敌祝融高。","异鸟流清响，神镫见白毫。","危颠可观日，夜涌海东涛。"]},{"t":"衡山福严寺二十三题为梓上人赋 其六 掷钵峰","f":"五言律诗","c":["神僧手中钵，掷向最高峰。","径度虚空上，难寻变化踪。","锡飞曾近鹤，剑跃或成龙。","搔首不可见，烟霞千万重。"]},{"t":"衡山福严寺二十三题为梓上人赋 其七 定心石","f":"五言律诗","c":["燕坐百念息，湛然方寸间。","相无分彼我，空已判真顽。","魑魅来相试，刍尼去不还。","众人笑痴衲，长日此看山。"]},{"t":"衡山福严寺二十三题为梓上人赋 其八 砖镜亭","f":"五言律诗","c":["曹溪一祖后，衡岳世多贤。","分得灯相续，提将印密传。","法音风万籁，禅性月中天。","珍重磨砖喻，微机要自诠。"]},{"t":"衡山福严寺二十三题为梓上人赋 其九 隐身嵓","f":"五言律诗","c":["尘世苦热恼，山林长夏幽。","岳神来护法，尊者坐经秋。","呼粥鱼频响，衔花鹿自游。","法云长散满，七十二峰头。"]},{"t":"衡山福严寺二十三题为梓上人赋 其十 三泉","f":"五言律诗","c":["一沼天成后，双泉神应来。","云根锡卓破，地胍虎跑开。","暗溜悬山雨，寒光漾石苔。","诸僧朝盥罢，相次上堂回。"]},{"t":"衡山福严寺二十三题为梓上人赋 其十一 岳心亭","f":"五言律诗","c":["何许新亭好，轩窗窈窕深。","天开云四面，地据岳中心。","雨绿蘼芜道，风香薝卜林。","晓岚收不尽，犹作半山阴。"]},{"t":"衡山福严寺二十三题为梓上人赋 其十二 目云亭","f":"五言律诗","c":["两公俱古佛，遗迹在新亭。","塔寺疑神造，山川本地灵。","峰秋阳雁断，潭暮雨龙腥。","老宿忘言久，閒抛案上经。"]},{"t":"衡山福严寺二十三题为梓上人赋 其十三 迎云亭","f":"五言律诗","c":["细路扪萝上，高亭在翠微。","树阴幪草坐，山气湿田衣。","落日孤钟动，遥天一锡飞。","悠然片云下，知是应真归。"]},{"t":"衡山福严寺二十三题为梓上人赋 其十四 兜率桥","f":"五言律诗","c":["传是竺僧说，幽如兜率宫。","驱龙劈地险，架石补天空。","星土熊湘合，云沙鹫岭通。","阑干倚来久，时度吉祥风。"]},{"t":"衡山福严寺二十三题为梓上人赋 其十五 开虹桥","f":"五言律诗","c":["螮蝀横当道，蜿蜒下汇潭。","幽光飞睒睒，危构郁耽耽。","鸟下窥寒瀑，樵回带夕岚。","遥知说法处，来作老人参。"]},{"t":"衡山福严寺二十三题为梓上人赋 其十六 大慧塔","f":"五言律诗","c":["大慧谈经地，林园即给孤。","凿云藏舍利，鞭石起浮图。","风铎时喧寂，天经忽有无。","沙门每来此，三绕作南谟。"]},{"t":"衡山福严寺二十三题为梓上人赋 其十七 读书堂","f":"五言律诗","c":["上年贤宰相，遁迹白衣时。","试问葫芦卜，何如懒瓒知。","才名留别传，香火寄空祠。","千载衡江水，东流有所思。"]},{"t":"衡山福严寺二十三题为梓上人赋 其十八 煨芋嵓","f":"五言律诗","c":["彼美山中芋，轮囷类饿鸱。","暖生松火夜，香透竹炉时。","虎迹群行满，猿声独啸悲。","邺侯知味否，莫比御烧梨。"]},{"t":"衡山福严寺二十三题为梓上人赋 其十九 御书阁","f":"五言律诗","c":["粲若唐宸翰，森然宋赐书。","宝藏经阁上，光动道场初。","川岳留奇观，风云绕净居。","何时能一到，银钥借开鱼。"]},{"t":"衡山福严寺二十三题为梓上人赋 其二十 退道陂","f":"曲","c":["神凿三百级，盘回上峻陂。","摄衣苍藓滑，倚杖白云多。","野叟耕麋?，山都寄鸟窠。","朱陵是俦侣，飞锡定相过。"]},{"t":"衡山福严寺二十三题为梓上人赋 其二十一 止南寮","f":"五言古诗","c":["昔隐黄龙老，今遗书记寮。","人天所供养，巾盖此逍遥。","仙乐时时下，香云往往飘。","千秋一金塔，□□□□□。"]},{"t":"衡山福严寺二十三题为梓上人赋 其二十二 藏雪寮","f":"五言律诗","c":["雪山一片雪，何日落中华。","皎洁无藏处，虚空自作花。","石厓穿乳窦，海岸叠潮沙。","底用分荆越，诸方总是家。"]},{"t":"衡山福严寺二十三题为梓上人赋 其二十三 冰雪庵","f":"五言律诗","c":["近岭无冰雪，庵居易过寒。","饭炊麻子熟，衣补衲头完。","颢气诗脾里，雷音讲舌端。","知师最清苦，归去北山干。"]},{"t":"题桐庐凤山寺僧道大鹭雪轩","f":"五言律诗","c":["禅客忘机地，舂锄尔亦灵。","飞来万点雪，巢破一林青。","晚濑明拳足，秋萝退阁翎。","山神护说法，吹断草风腥。"]},{"t":"篷轩为吴僧元谊赋","f":"五言律诗","c":["缚竹作禅宇，小于江上舟。","树声疑叠浪，月影似中流。","兴寄江湖远，身同世界浮。","怀师燕坐处，吾道在沧洲。"]},{"t":"静寄轩为吴僧一元赋","f":"五言律诗","c":["群动寂寥外，一轩潇洒中。","山林亦长物，身世本虚空。","清磬花龛日，孤灯竹榻风。","不曾离寓所，惟有主人公。"]},{"t":"抱素子作自适图求题","f":"五言律诗","c":["隐者抱幽素，独行穿杳冥。","有诗吟木客，无驾勒山灵。","寒涧流沙白，秋云入竹青。","携琴向何处，弹与野猿听。"]},{"t":"北山诵藏经三旬毕诗以调之","f":"五言律诗","c":["金布庄严地，花飞梵呗时。","舌端谈孔雀，顶上集刍尼。","国寿祈天永，皇心体物慈。","明当喜圆满，一月废吟诗。"]},{"t":"用北山韵答之","f":"五言律诗","c":["吾衰年冉冉，师乐日閒閒。","师以诗娱意，吾将酒驻颜。","看云知幻灭，见月喜明还。","莫问谁家曲，相酬笑语间。"]},{"t":"送观性空上人归省","f":"五言律诗","c":["白发高堂在，青山旧业贫。","载经随客舫，留偈别禅邻。","行路半春雨，近乡多故人。","一龛还可老，莫污衲衣尘。"]},{"t":"送以中及公自扬天宁寺游匡庐","f":"五言律诗","c":["趺坐对禅镫，江风浪几层。","还从鹤城路，去访虎溪僧。","湖晓星浮石，岩春瀑断冰。","吴中却回日，应老旧池菱。"]},{"t":"清轩","f":"五言律诗","c":["轩居最潇洒，不受一尘侵。","门断怀金者，人知饮水心。","鹤声生晚思，竹色净秋阴。","此意琴尊外，翛然只自深。"]},{"t":"话旧送胡士恭之京师","f":"五言律诗","c":["话旧共蝉联，河桥且系船。","春归花满地，江阔雨连天。","处士题鹦鹉，诗人拜杜鹃。","此生虽老去，未敢愧前贤。"]},{"t":"自顾","f":"五言律诗","c":["自顾摧颓客，仍居寂寞滨。","月佣奴谇少，岁计妇忧贫。","酒后诗成梦，灯前壁写神。","渔樵吾所喜，相见即情亲。"]},{"t":"怀天目山处士张一无二首 其一","f":"五言律诗","c":["一饭了年华，蒲团静结跏。","雪蹊抛即栗，风壁裂袈裟。","寒狖窥烧叶，饥禽听施茶。","清除亿劫想，吾欲问僧伽。"]},{"t":"怀天目山处士张一无二首 其二","f":"五言律诗","c":["僧舍蜂腰缀，君居第几间。","池冰寒挂瀑，云雪白藏山。","未得抛尘网，相从出死关。","东冈幻住塔，礼罢几时还。"]},{"t":"送福上人无际南归","f":"五言律诗","c":["岁闰春来早，师行且过寒。","问程山寺远，乞食野人难。","空性元无际，禅锋岂有端。","遇予方外友，一为问平安。"]},{"t":"清河水涨答复中吉监县水字韵","f":"五言律诗","c":["漭漾清河涨，湍流滋浸淫。","沧溟浑灌注，浊浪浩浮沉。","洲渚津涯阔，泥沙沮洳深。","沿淮泽鸿满，漂荡渡江浔。"]},{"t":"送郑喧宣伯赴赤那思山大斡耳朵儒学教授四首 其一","f":"五言律诗","c":["圣祖兴王地，风云护大营。","天垂紫塞阔，星戴赤山明。","人俗殊淳古，皇文易化成。","君行当劝学，无愧鲁诸生。"]},{"t":"送郑喧宣伯赴赤那思山大斡耳朵儒学教授四首 其二","f":"五言律诗","c":["绝漠同文轨，提封振古稀。","犬牙开武帐，元老秉天威。","白马紫驼酒，青貂银鼠衣。","那思山下水，曾睹六龙飞。"]},{"t":"送郑喧宣伯赴赤那思山大斡耳朵儒学教授四首 其三","f":"五言律诗","c":["野散千军帐，云横万里川。","寒多雨是雪，日近海为天。","黑黍供甘酿，黄羊饱割鲜。","广文但少客，宁虑坐无毡。"]},{"t":"送郑喧宣伯赴赤那思山大斡耳朵儒学教授四首 其四","f":"五言古诗","c":["晨发戒行装，风沙碛路长。","油鞯白鼻马，蓝绶赤铜章。","文学重新命，□□□□□。","□□□□□，□□□□□。"]},{"t":"宫中舞队歌词 其一","f":"五言律诗","c":["十六天魔女，分行锦绣围。","千花织步幛，百宝贴仙衣。","回雪纷难定，行云不肯归。","舞心挑转急，一一欲空飞。"]},{"t":"宫中舞队歌词 其二","f":"五言律诗","c":["凿海行龙舸，凭山起鹄台。","天池神马出，月殿舞鸾来。","六合妖氛静，群生寿域开。","吾皇乐民乐，愿上万年杯。"]},{"t":"宫中舞队歌词 其三","f":"五言律诗","c":["白玉雕钗燕，黄金凿步莲。","箫吹凤台女，花献蕊宫仙。","香雾团银烛，歌云扑锦筵。","请将供奉曲，同贺太平年。"]},{"t":"潞庄","f":"五言律诗","c":["松棚叟卖浆，棚下午风凉。","独涧绕群木，数家成一坊。","蜂行花已密，蚕罢叶仍桑。","此地无千步，真堪作蜕藏。"]},{"t":"闻蝉","f":"五言律诗","c":["中庭白榆树，时有一蝉声。","沸茧方抽绪，鸣弦忽断筝。","苍烟起平楚，落日下高城。","曾是天涯客，因之百感生。"]},{"t":"雁声","f":"五言律诗","c":["嘹嘹数雁度，流响一凄然。","半落淮南雨，遥沉海上天。","疏砧欲断处，哀角未吹前。","我亦离群者，闻之夜不眠。"]},{"t":"马通薪","f":"五言律诗","c":["可代薪如桂，还宜火作煤。","翁摊扶杖立，童拾戴筐回。","野屋寒堆整，山炉夜拨灰。","厩官无好事，不遣换香来。"]},{"t":"陈伯将作北山梓公岳居图余题其上","f":"五言律诗","c":["高僧业何许，云梦泽南洲。","楼阁诸天上，江湖万里流。","禅心无住著，世事若浮休。","寂寞京尘里，披图时卧游。"]},{"t":"乌桕树","f":"五言律诗","c":["巾子峰前树，逋仙句最工。","迥明霜寺外，半落石池中。","郑老惟书柿，崔郎只咏枫。","山林正寂寞，备此作春红。"]},{"t":"书所见 其一","f":"五言律诗","c":["沟中人啖尸，道上母抛儿。","有眼何曾见，无方能疗饥。","干戈未解日，风雪正寒时。","归向妻孥说，毋嫌朝食糜。"]},{"t":"书所见 其二","f":"五言律诗","c":["城南官掘穴，日见委尸盈。","终朝乌鸟下，薄暮狼狐鸣。","冰裂人刳骨，风悲鬼哭声。","茫茫死生理，真宰岂无情。"]},{"t":"偕鄢元止善东门视田","f":"五言律诗","c":["白骨如乱石，荒村殊惨神。","恶风生杀气，斜照逼归人。","应俗悲多故，全生幸此身。","青青原上麦，亦复可怜春。"]},{"t":"题林德清竹雪斋","f":"五言律诗","c":["高斋修竹林，积雪竹间深。","岁暮不改色，幽人同此心。","种梅分地隙，笼鹤就墙阴。","想见椒江上，扁舟许客寻。"]},{"t":"雪后 其一","f":"五言律诗","c":["雪后北风急，起行冰满须。","冻泥忧蹇马，活火爱团蒲。","数口狼依狈，群情虎畏貙。","每逢来使问，亲故有书无。"]},{"t":"雪后 其二","f":"五言律诗","c":["路滑堆残雪，山晴散宿霾。","民生已涂炭，兵气尚江淮。","抚世忧徒切，谋身计自垂。","临觞且复醉，吾命有安排。"]},{"t":"癸巳元日即事","f":"五言律诗","c":["禁苑朝珂集，宫楼昼刻传。","云开黄道日，春丽紫薇天。","进虎蛮如画，仪鸾仗类仙。","晨观净氛气，即是偃兵年。"]},{"t":"大驾时巡千官导送至大口","f":"五言律诗","c":["万乘巡行远，三灵佑护多。","旌旄随大纛，鼓铎杂鸣驼。","丽日浮黄伞，微风送玉珂。","臣心如草色，不断到滦河。"]},{"t":"松巢为潜川谢尧章作","f":"五言律诗","c":["林栖有隐君，结构出尘氛。","就树遮青雨，牵萝补白云。","双鸠从此拙，独鹤与平分。","华屋非无数，山中了不闻。"]},{"t":"蜕庵岁晏百忧薰心排遣以诗乃作五首 其一","f":"五言律诗","c":["开岁七十五，故园犹未归。","看从今以后，知复是邪非。","星斗天垂象，龙蛇地发机。","边声近稍息，一醉典春衣。"]},{"t":"蜕庵岁晏百忧薰心排遣以诗乃作五首 其二","f":"五言律诗","c":["小小新斋阁，温温旧毾㲪。","精神全藉酒，筋力半支藤。","蛰豸深坯户，冥鸿巧避矰。","蒙头衲被底，何异在家僧。"]},{"t":"蜕庵岁晏百忧薰心排遣以诗乃作五首 其三","f":"五言律诗","c":["世路正如棘，吾生犹系匏。","诗人歌蟋蟀，军士叹蟏蛸。","无地营家食，何心解客嘲。","山林徒在眼，难觅一枝巢。"]},{"t":"蜕庵岁晏百忧薰心排遣以诗乃作五首 其四","f":"五言律诗","c":["书舍如僧舍，心閒与静宜。","写多髡兔颖，藏久蛀貂皮。","宦迹年劳见，生涯日历知。","未应同与俊，肯负沃洲期。"]},{"t":"蜕庵岁晏百忧薰心排遣以诗乃作五首 其五","f":"五言律诗","c":["久悟无生法，从容与化迁。","机忘槔俯仰，道悟蜜中边。","宇县犹多垒，干戈已十年。","吾惟待其定，归种故山田。"]},{"t":"十月一日","f":"五言律诗","c":["瓦盎醅纯白，砖炉火乍红。","风生月晕后，霜下角声中。","饥鼠窥灯暗，惊厖吠巷空。","于今玉堂老，讵信暮途穷。"]},{"t":"立冬前二日","f":"五言律诗","c":["高秋日凄冷，且复闭门居。","蟹壮输芒后，醅香出榨初。","霜篱存晚菊，腊瓮作寒菹。","更好山翁唱，阳春恐不如。"]},{"t":"吴下客怀秋荅湛渊白先生廷玉","f":"五言律诗","c":["湖海无穷事，风霜薄暮年。","客程淹白日，吾道信青天。","影自酬形赠，心宁爱目怜。","平生五字律，名在万人前。"]},{"t":"怀先陇","f":"五言律诗","c":["京国留家久，馀生只自怜。","一单如老衲，八十又新年。","义士心犹血，谗夫舌谩涎。","何时抱尊酒，哭向计峰前。"]},{"t":"七月廿九日","f":"五言律诗","c":["此丑今方殛，京城蹀血新。","也知天悔祸，谁谓国无人。","胜气腾龙虎，沈机动鬼神。","大廷亲命诏，终夜在延春。"]},{"t":"自誓","f":"五言律诗","c":["此丑行当殛，吾身敢顾危。","要看夺笏处，正是结缨时。","万古千秋在，皇天后土知。","寸心三尺简，肯愧史臣词。"]},{"t":"乙巳初度","f":"五言律诗","c":["今日吾生日，开尊向竹斋。","家人更上寿，凡事且宽怀。","学道精神淡，匡时志愿垂。","百年原土上，自有一坏埋。"]},{"t":"病起","f":"五言律诗","c":["强起梳头坐，窗明晚景新。","生遭兵是劫，病与鬼为邻。","农事田畴废，边声鼓角频。","故山多药物，徒切未归身。"]},{"t":"岁晚苦寒偶成四章录似北山 其一","f":"五言律诗","c":["风暴寒逾急，星回岁欲周。","缺牙便食粥，瘦骨怯重裘。","节物殊牢落，前图益谬悠。","蜕窝真类蛰，长日火炉头。"]},{"t":"岁晚苦寒偶成四章录似北山 其二","f":"五言律诗","c":["清眠梦屡觉，霜气转凄凄。","春近雁北向，月明乌夜啼。","炉香留墨篆，烛泪聚银泥。","少释幽忧疾，寻君一杖藜。"]},{"t":"岁晚苦寒偶成四章录似北山 其三","f":"五言律诗","c":["鼠劣翻书册，猫驯伴坐毡。","吟怀欣雪夜，疾目畏风天。","惟酒能消日，无方可引年。","我诗犹偈子，一问北山禅。"]},{"t":"岁晚苦寒偶成四章录似北山 其四","f":"五言律诗","c":["短景催残岁，穷阴连大荒。","狙三随所赋，龟六可深藏。","未了惟文债，堪归祗醉乡。","絁衾有馀暖，翻喜夜天长。"]},{"t":"四月十三日","f":"五言律诗","c":["白丁驱上城，徒手不能兵。","斗将无人色，行涂多哭声。","惟将孔达解，竟遣夙沙烹。","满眼黄尘暮，悲风惨淡生。"]},{"t":"城东废寺","f":"五言律诗","c":["一径入荒寂，松风长夏寒。","夜叉栖败屋，魔女去空坛。","古佛金全剥，遗碑字半刓。","时逢好事者，来剔藓文看。"]},{"t":"游刘真君庙","f":"五言律诗","c":["古庙西原上，虚廊半欲摧。","水龙鳞剥雨，画鬼面生苔。","叟乞烧钱火，巫抄构殿材。","英雄有神护，遁迹此中来。"]},{"t":"渐老","f":"五言律诗","c":["渐老惟贪睡，相留大有情。","诗从年长淡，寒入夜深清。","不鼓床琴㾌，慵书帖字生。","灯花独可喜，连夕向人明。"]},{"t":"夜宿青芝坟园","f":"五言律诗","c":["水落宽船步，年丰密酒壶。","土酥分地产，木蜜荐秋腴。","认路尘踪断，拖筇野影孤。","行人不可暮，落日有于菟。"]},{"t":"上都从驾幸东凉亭","f":"五言律诗","c":["鹤禁烟华紫，龙冈草色青。","羽林移晓仗，法驾幸凉亭。","大业开天道，甘泉发地灵。","微臣叨侍从，愿睹万邦宁。"]},{"t":"西内应制即事","f":"五言律诗","c":["烽火连齐鲁，干戈接陇秦。","四郊多壁垒，万里半烟尘。","将帅屯兵久，君王遣使频。","老臣叨视草，进罢益沾巾。"]},{"t":"行次独石驿大雨驲行廿里喜晴","f":"五言律诗","c":["段段青天出，浮云四散归。","燕忙搀马过，蝇乱扑人飞。","远道倦行李，故山思采薇。","北风朝已冷，未敢御絺衣。"]},{"t":"暴疾卧草堂","f":"五言律诗","c":["伏枕朝佣起，惟将药裹亲。","纷纭眼前事，憔悴病中身。","宿露浓于雨，秋花好似春。","最嫌姜桂绝，无处乞诸邻。"]},{"t":"有旨翥领宋史刊于江浙次东阿站","f":"五言律诗","c":["南来十五驿，幽绝独斯亭。","下榻月初上，捲帘山更青。","干时嗟暮齿，从事厌劳形。","寂寞江云外，谁知有使星。"]},{"t":"九日抵武安县徘徊店","f":"五言律诗","c":["水落衡漳急，川回上党高。","流年秋忽忽，行路日滔滔。","山市人多瘿，沙沟地不毛。","村墟欣有菊，小驻为持醪。"]},{"t":"代祀湄洲天妃庙次直沽","f":"五言律诗","c":["晓日三叉口，连樯集万艘。","普天均雨露，大海静波涛。","入庙灵风肃，焚香瑞气高。","使臣三奠毕，喜色满宫袍。"]},{"t":"次石门驿","f":"五言律诗","c":["投老复行役，江湖秋兴悲。","舣舟黄落处，欹枕黑甜时。","燕闰归何晚，鸥晴浴故迟。","不妨无事饮，聊遣有情痴。"]},{"t":"剡中清风岭王节妇沈江处有血书石上","f":"五言律诗","c":["尽日经行远，云山又嵊山。","江光寒照外，雨气乱峰间。","野艇罾鱼卖，村巫诅虎还。","千秋贞妇庙，留在□□□。"]},{"t":"关岭","f":"五言律诗","c":["青林抱涧阿，直上更嵯峨。","田凿云根种，人盘鸟道过。","乱泉鸣暗谷，丰草被阳坡。","彷佛疑山鬼，衣裳隐薜萝。"]},{"t":"雨中次黄岩驿","f":"五言律诗","c":["宿雨晨初歇，高秋日浸微。","水声千涧落，云气万山归。","委羽洞天在，仙人飙驾飞。","丹砂如可问，吾岂恋朝衣。"]},{"t":"夜过石溪驿","f":"五言律诗","c":["篮舆摇醉梦，轧轧过前冈。","木落风声碎，行人月影长。","远村时见火，沾露忽零裳。","一笑方言异，前涂殊未央。"]},{"t":"刘山驿","f":"五言律诗","c":["兹山类台剡，回复度中岑。","传舍白云上，人家乌桕林。","此身嗟老大，行路转岖嵚。","佳处时停策，终焉惬野心。"]},{"t":"濑溪","f":"五言律诗","c":["古渡猴溪外，风烟淡欲无。","岛人形貌怪，闽囝语言殊。","小店鱼虾市，深林猿鸟都。","肩舆看山好，候骑缓前驱。"]},{"t":"发漳州","f":"五言律诗","c":["万里漳南道，遥连岭峤东。","山寒冬息瘴，海近昼多风。","废圃攒筋竹，疏林落刺桐。","槟榔新善啖，一解宿酲空。"]},{"t":"归武林冒雨至练市韩伯清庄","f":"五言律诗","c":["溪雨寒犹重，山云昼不开。","老夫喜閒暇，练水得沿洄。","凫雁冲船过，鱼虾入馔来。","故人居渐近，应待举吾杯。"]},{"t":"泛舟青镇至姚师善庄夕回韩庄","f":"五言律诗","c":["明月半溪水，归人中夜舟。","树阴屯岸合，萤影入烟流。","勋业生无取，田园老可谋。","悠然发清咏，思绕白蘋洲。"]},{"t":"召入国学雨中过高沙湖","f":"五言律诗","c":["细雨洒秋色，平湖生白波。","客心贪路急，帆腹受风多。","落木生诗思，惊禽避棹歌。","舟行不借酒，兀坐奈愁何。"]},{"t":"北归四月一日舟至市泾","f":"五言律诗","c":["绿树村村合，晴川浦浦通。","岸容宽积雨，水色定回风。","戍近时鸣柝，渔归忽舣篷。","船人喜相约，乘早过垂虹。"]},{"t":"留宿洪洞庆云观刘山甫方丈","f":"五言律诗","c":["旅寓丹房夜，高城乍绝钟。","蜡花烧烛短，乳面泼茶浓。","山豁三更月，秋添四壁蛩。","殷勤老贞士，清话得从容。"]},{"t":"舟行即事二首 其一","f":"五言律诗","c":["雾树浑连水，水沟不受潮。","米盐江上舫，鱼菜市中桥。","壮士宁辞辱，仙公会见招。","边淮无酒禁，磊碨剩须浇。"]},{"t":"舟行即事二首 其二","f":"五言律诗","c":["天水浑无际，中流明月轮。","山形立积铁，潮色烂镕银。","沙露冻粘石，海风寒薄人。","舟师传吉语，沽酒祭江神。"]},{"t":"归来二首 其一","f":"五言律诗","c":["扰扰群生里，茫茫大化中。","是非同喻马，得失一亡弓。","买酒从贤浊，论文任鬼穷。","此身河上鸟，只合信天公。"]},{"t":"归来二首 其二","f":"五言律诗","c":["处士声华远，吾生志趣同。","结庐犹洛北，避世即墙东。","几见薰天富，俱成扑地空。","虞罗谩机事，未许篡冥鸿。"]},{"t":"七月一日之集庆望日次锡山宿玄文馆","f":"五言律诗","c":["海月光芒湿，川云意绪閒。","刚风浮地外，元气满人间。","野榜歌相答，渔灯去不还。","电明知有雨，只在九龙山。"]},{"t":"九日谒告归阻风御河","f":"五言律诗","c":["雨后风何暴，藏舟古岸阴。","早霜红树遍，残月白河沈。","鸥泛乘长浪，狐跳没远林。","人生信淹速，那敢易初心。"]},{"t":"至通州","f":"五言律诗","c":["驿卒争鸣鼓，舟人喜下桅。","依然今日到，却似去年回。","岸黑秋涛缩，川红夕照开。","君恩忘险阻，不觉畏途来。"]},{"t":"自悟 其一","f":"五言律诗","c":["古佛风翻盎，诗僧醉可朋。","有生还有劫，无尽本无灯。","蚤自楞伽悟，今非愿力能。","此心宁万虑，于道只三乘。"]},{"t":"自悟 其二","f":"五言律诗","c":["海内虚游子，山中脱骨仙。","一单如老衲，八十又新年。","野马飞窗日，醯鸡舞瓮天。","吾今丈人行，肯与众争怜。"]},{"t":"上除日南山莲社期忏偕伯清昆季还饮南园","f":"五言律诗","c":["禊饮湖亭上，临流自祓衣。","闰留春事晚，风打酒船稀。","蛙子黑初出，桃花红欲飞。","早霞知有雨，沾洒送人归。"]},{"t":"伯青邀予至青芝坞汎湖暮归","f":"五言律诗","c":["落日风花起，寒波倏渺然。","山藏进雪寺，岸护种冰田。","醉眼轻浮世，牢愁入暮年。","若为湖一曲，携钓隐渔船。"]},{"t":"清明游包家山 其一","f":"五言律诗","c":["远近红千树，繁开夺艳霞。","月明寒食雨，春老上阳花。","辇路迷游躅，宫词入梦华。","东风葵麦浪，回首野人家。"]},{"t":"清明游包家山 其二","f":"五言律诗","c":["太液曾来鹄，高台旧影娥。","美人黄土尽，故国白云多。","野草荒神籍，宫莲怨棹歌。","羌儿洗马处，斜日满寒波。"]},{"t":"偕杨瑀元诚王炢自行湖堤閒步","f":"五言律诗","c":["湖上西风急，秋阴止杳冥。","水痕连岸白，山色彻云青。","蛰燕依深谷，还鸥下近汀。","君歌我当和，有酒满长瓶。"]},{"t":"秋试后胡益士恭归番阳与游吴山圣水寺","f":"五言律诗","c":["高处见沧溟，西风吹酒醒。","潮来一片白，山拥万重青。","草木如浮动，烟尘忽杳冥。","登临不可极，吟思满秋汀。"]},{"t":"清明日偕李钦嗣游吴公弓台至雷塘蜀井","f":"五言律诗","c":["路绝平沙过，新塘水半乾。","龙归雷雨恶，鹘没海天宽。","县帜春醅熟，行厨野祭寒。","此生无倚泊，随处得盘桓。"]},{"t":"九月八日陪危太朴偕梁九思游城南三学寺万寿寺 其一","f":"五言律诗","c":["南城多佛刹，结构自辽金。","傍舍遗民在，残碑好事寻。","雨苔尘壁暗，风叶石床深。","一饭蒲团了，萧萧钟磬音。"]},{"t":"九月八日陪危太朴偕梁九思游城南三学寺万寿寺 其二","f":"五言律诗","c":["休日得连骑，高秋天气新。","楼台惟见寺，井里半成尘。","坏庙鬼无主，荒丘狐化人。","千龄共须尽，回首一伤神。"]},{"t":"文昌楼望月时家已归浙上","f":"五言律诗","c":["今夜溪楼月，登临倍惘然。","电光何处雨，风色欲秋天。","历历灯缘岸，依依笛起船。","江湖归路渺，回首白鸥前。"]},{"t":"清明日游东山谒栖霞岭仇先生墓","f":"五言律诗","c":["前辈凋零尽，南阳有古阡。","诗应传四海，酒不到重泉。","槐国真成梦，桃源亦是仙。","松根一匊泪，惨淡堕风烟。"]},{"t":"秋日独行便上偶至清修寺","f":"五言律诗","c":["溪南野寺幽，巾舄偶相求。","古道多黄叶，残僧半白头。","远村高鸟暮，灌木乱蝉秋。","此地茅堪剪，吾将卜隐丘。"]},{"t":"四月望观帝师发思跋影堂","f":"五言律诗","c":["佛子来西竺，巍然南面尊。","法筵花散漫，香殿玉温黁。","龙象诸天下，钟螺竟日喧。","朝观立随喜，如在给孤园。"]},{"t":"九月六日宿宝集寺","f":"五言律诗","c":["来借禅房宿，悠然空客心。","残僧几人在，古殿一灯深。","檐铎能蕃语，斋居发海音。","重阳又已近，聊复此登临。"]},{"t":"次韵莫景行秋雨喜晴","f":"五言律诗","c":["苦热不可忍，汗肤鳞甲生。","雨分何处落，月在半天明。","虫语迎秋早，川光入夜清。","得凉忘坐久，河汉忽西倾。"]},{"t":"甲子元日夜大雪初三日立春始晴","f":"五言律诗","c":["几年无此雪，南国见应稀。","平地深三尺，飞花大一围。","银河乾彻底，白石烂生辉。","润色饶梅柳，新春晓已归。"]},{"t":"南园宴集雨归有作","f":"五言律诗","c":["骤落菰蒲雨，遥生菡萏风。","归云龙井黑，倒照凤山红。","帘暮舟频引，衣凉酒屡空。","歌声未可放，花底有惊鸿。"]},{"t":"辛未苦雨","f":"五言律诗","c":["禾田犹钜浸，春日复连绵。","醉使呼堂上，饥人死道边。","鹤神方下地，龙伯已行天。","真宰如容问，吾心血可笺。"]},{"t":"癸酉人日雨中","f":"五言律诗","c":["积雨将谋雪，新年未入春。","半生如过客，七日又逢人。","采胜天花小，香醪玉色醇。","多忧亦何事，适意任天真。"]},{"t":"与勃海孟芾景章守岁成居竹宅","f":"五言律诗","c":["此老无柴棘，襟期一见同。","诗如孟东野，名是米南宫。","把酒推年长，围炉到夜终。","剩吟须剩醉，相对各衰翁。"]},{"t":"庚辰元日立春","f":"五言律诗","c":["采燕方迎岁，苍龙忽建辰。","车书时有道，宇宙物皆春。","红喜灯花重，青看菜甲新。","屠苏不辞后，已是白头人。"]},{"t":"戊子正月连雪苦寒答段助教天祐吉甫二首 其一","f":"五言律诗","c":["雪寒浑未解，风力更狂吹。","强饭怜君瘦，重裘觉我衰。","酒香红面颊，灯影黑须眉。","黄鹤山中地，求田已有期。"]},{"t":"戊子正月连雪苦寒答段助教天祐吉甫二首 其二","f":"五言律诗","c":["三年冗博士，四海老诗人。","同是桑榆日，惟堪曲米春。","清羸元寿相，肮脏任长身。","微子谁知我，从来懒更真。"]},{"t":"四月十四日习仪白塔寺有旨翥升院判","f":"五言律诗","c":["乍换朝衣紫，祗怜客鬓华。","才知无补世，官喜不离家。","海燕雏方乳，戎葵蕊未花。","归来北窗卧，尘污满乌纱。"]},{"t":"七月六夜对月","f":"五言律诗","c":["星会黄姑夕，天回白帝秋。","明河初左界，大火渐西流。","晚景逢多故，寒心集百忧。","山林莽寥落，何处觅丹丘。"]},{"t":"乙未元日","f":"五言律诗","c":["稍稍钟鼓动，纷纷车马朝。","张灯照白发，把酒送寒宵。","黄石终归汉，洪厓反见尧。","刍言欣见采，拭目望新条。"]},{"t":"岁除日","f":"五言律诗","c":["七十古稀有，欣然岁更新。","换衣痴女喜，分粟故人贫。","软饱须官酿，奇温爱絮巾。","明当候云物，载笔纪王春。"]},{"t":"暴风","f":"五言律诗","c":["闭户复闭户，黄尘千丈生。","不雨草无色，冲风人倒行。","游子念乡土，腐儒忧甲兵。","狂吹不肯息，终夜为心惊。"]},{"t":"长至日","f":"五言律诗","c":["至节得休暇，闭关宜燕居。","孤怀愁易切，远信语多虚。","寿酒教儿劝，祥云听史书。","亲知半湖海，无地问何如。"]},{"t":"大风时送友南城","f":"五言律诗","c":["南国碧云暮，西风芳草多。","相思故人远，如此别情何。","清绝山僧笔，苍茫楚客歌。","凭将万里意，一问洞庭波。"]},{"t":"啸亭为盐令贾策治安题","f":"五言律诗","c":["老子掀髯处，云间孤草亭。","不妨舒逸气，直恐动精灵。","风水划秋涌，鱼龙悲夜听。","几翻流响歇，江冷越山青。"]},{"t":"寄题钦惟心山房三首 其一","f":"五言律诗","c":["普照南徐寺，苍苍祗树林。","驮经惟白马，布地尽黄金。","午梵钟声远，寒灯殿影深。","由来世界黑，谁与一明心。"]},{"t":"寄题钦惟心山房三首 其二","f":"五言律诗","c":["朱方有真子，心印悟南宗。","奏乐惟天女，听经化海龙。","香凝行道席，灯照著衣钟。","犹厌依城市，开门别种松。"]},{"t":"寄题钦惟心山房三首 其三","f":"五言律诗","c":["名山旦夕仰，方外宿心亲。","业白到初地，性空无一尘。","乞钟时出寺，坐夏不迎人。","想见惟心叟，风凉满㲲巾。"]},{"t":"辑山村先生诗卷 其一","f":"五言律诗","c":["昔在垂髫日，今吟薄暮年。","床孤郗氏选，诗得谢公传。","故国空戎马，荒山冷墓田。","祗令后死者，忍泪读遗篇。"]},{"t":"辑山村先生诗卷 其二","f":"五言律诗","c":["卷可留天地，诗尝泣鬼神。","游仙归化鹤，披发下骑麟。","素望高前辈，青衫老此身。","栖霞石表在，终古不成尘。"]},{"t":"金山桥上闻苑池荷香","f":"五言律诗","c":["立马金河上，荷香出苑池。","石桥秋雨后，瑶海夕阳时。","深树栖霞早，微波浴象迟。","烦襟一笑爽，正喜好风吹。"]},{"t":"次韵题大雷山桃源汪氏桃隐 其一","f":"五言律诗","c":["幽甚南雷路，尝闻故老传。","墟通卖鱼碶，潮入种蚶田。","棂子浑成树，桃花不计年。","山中多佛寺，灯火肃芊芊。"]},{"t":"次韵题大雷山桃源汪氏桃隐 其二","f":"五言律诗","c":["南北二十里，两山中过云。","采芝随鹿去，拾果与猿分。","酒熟青田核，羹香碧涧芹。","非君播诗句，那得世人闻。"]},{"t":"鉴堂上人招余游慧山行舟不成往因寄","f":"五言律诗","c":["竟负山游约，长怀第二泉。","毁茶休著论，载酒谩回船。","会摘春林雨，来寻午灶烟。","从师坐联句，祗恐废安禅。"]},{"t":"大风","f":"五言律诗","c":["彻昼风何急，避行陵树傍。","惊沙扑面黑，野日映人黄。","科斗旱未出，栗留寒欲藏。","穷途泪易下，不是阮生狂。"]},{"t":"七月旦立秋风雨夜寒","f":"五言律诗","c":["练裯不解暖，已索絮衾眠。","老疾日渐退，馀生天所怜。","蝎行窗纸响，蛾扑烛花偏。","喜见沽头报，江南有到船。"]},{"t":"默坐","f":"五言律诗","c":["默坐观浮世，何殊起灭云。","猿寒夜嘷母，鸦急晚追群。","应俗神嗟耗，经冬足苦皲。","俸香吾独喜，日可炷炉薰。"]},{"t":"除夕","f":"五言律诗","c":["坐玩群儿戏，閒供一笑欢。","朱丸那却鬼，白酒不禁寒。","官索题春帖，邻分馈岁槃。","归期知几日，谩检历头看。"]},{"t":"初三日夜玩月至中秋日得诗 其一","f":"五言律诗","c":["化工金铸巧，又换一钩新。","远道伤游子，深闺喜拜人。","影县秋半破，明溯日西沦。","正拟排宵看，裁诗莫厌频。"]},{"t":"初三日夜玩月至中秋日得诗 其二","f":"五言律诗","c":["新月过初弦，冰轮次第圆。","空中真见相，清极恍如仙。","旧雨苍苔地，新寒白露天。","匡床延伫久，不觉屡移前。"]},{"t":"悼太平公","f":"五言律诗","c":["晨起洒杯酒，北风吹泪痕。","岂徒歌楚些，端欲叫天阍。","碧化苌弘血，春归杜宇魂。","千秋一史笔，谁辨逐臣冤。"]},{"t":"梅隐为蕃禧观余道士作二首 其一","f":"五言律诗","c":["隐者多幽事，锄云自种梅。","几盘山径术，强半雪莓苔。","拾药泥丹灶，浮香入酒杯。","时时霞上友，清晓踏寒来。"]},{"t":"梅隐为蕃禧观余道士作二首 其二","f":"五言律诗","c":["茅屋西林下，逋仙恐是君。","支筇鹤外见，哦句竹边闻。","老树春常早，空山雪不分。","道人无梦久，何处觅梨云。"]},{"t":"寄云门僧若邪溪兼题其松风阁二首 其一","f":"五言律诗","c":["闻道邪溪叟，高年出寺迟。","眉毫长几许，布衲破多时。","挂锡鹤移树，翻经花满池。","相望一江水，岁晚赴幽期。"]},{"t":"寄云门僧若邪溪兼题其松风阁二首 其二","f":"五言律诗","c":["阁外老松子，萧萧虚籁生。","定从何处起，宁有不平鸣。","我耳固师耳，风声是树声。","他时叩禅寂，衲破睡天明。"]},{"t":"识趣斋为山阴魏仲远赋","f":"五言律诗","c":["夏盖湖滨宅，幽然水竹开。","庄前鱼市合，山下酒船来。","把钓云移树，寻诗步石苔。","相羊总成趣，直待醒心回。"]},{"t":"送泐季潭游天台并送渊侍者归天台二首 其一","f":"五言律诗","c":["来从石城寺，去访石桥僧。","锡杖空山路，禅龛独夜灯。","道知文畅得，诗识皎然能。","到日西岩下，应吟瀑布淜。"]},{"t":"送泐季潭游天台并送渊侍者归天台二首 其二","f":"五言律诗","c":["解夏回天竺，寻真问石桥。","邻房留偈遍，归路载经遥。","瀑壮秋悬雨，江明日上潮。","题诗寄相忆，何处觅山寮。"]},{"t":"送蒲空叙本中往住长芦寺","f":"五言律诗","c":["杖锡风尘际，师行戒畏途。","故人怀槜李，春水到长芦。","舍利藏金塔，袈裟系宝珠。","禅房大自在，应念室中蒲。"]},{"t":"谒仪则堂上方观听续撰释氏通鉴","f":"五言律诗","c":["平生方外朋，今识故乡僧。","史有春秋笔，谈空大小乘。","香厨朝饭面，古殿昼燃灯。","归路烟芜外，斜阳下道陵。"]},{"t":"北山以雪窗墨兰竹石求题次韵","f":"五言律诗","c":["幽兰出楚畹，美竹自湘滨。","共友三生石，俱涵太古春。","山林空见相，冰雪老通神。","长作禅房供，毋令堕世尘。"]},{"t":"清溪濯足图","f":"曲","c":["黄尘满双足，宜赋故山归。","解屦就清泚，举头看翠微。","林?下窥膝，石藓欲沾衣。","更觅渔竿伴，閒来就钓矶。"]},{"t":"观潮","f":"五言律诗","c":["海口潮初上，江流涌不行。","大风生气势，烈日夺光晶。","鹢首来何驶，䲭夷怒未平。","吴儿誇壮观，车马暮填城。"]},{"t":"送蒙古僧印空岩黄龙寺 其一","f":"五言律诗","c":["高僧明廷秀，受业自南宗。","心诀提为印，禅机捷若锋。","炉香来化鹤，瓶水豢降龙。","弟子经窗外，应占旧偃松。"]},{"t":"送蒙古僧印空岩黄龙寺 其二","f":"五言律诗","c":["古刹西江外，师居最上方。","山神出护法，天女下焚香。","久客霜髭满，归舟云树长。","秋期到天目，容我借禅床。"]},{"t":"溪居山水小景二首 其一","f":"五言律诗","c":["想像溪居好，时来放钓船。","沧洲茅屋路，春水白鸥天。","林壑无多地，烟霞自一川。","底须论咫尺，对此已茫然。"]},{"t":"溪居山水小景二首 其二","f":"五言律诗","c":["何处野人村，微茫涧谷分。","林多太古树，山有四时云。","鸟迹还成道，猿啼或作群。","秋风茅屋破，谁赋隐思君。"]},{"t":"水墨达摩像班惟志笔","f":"五言律诗","c":["佛法无多子，西山雪柱天。","应寻葱岭去，方解少林禅。","鞮屦露双脚，罽衣披半肩。","虚空本无住，须借影中传。"]},{"t":"数日北风兴怀过海诸友","f":"五言律诗","c":["数日好风色，行人应到家。","秋花香独耐，寒雁字多斜。","薄饮无长酒，轻行有小车。","吾心何尔汝，聊复度年华。"]},{"t":"啖笋","f":"五言律诗","c":["今日食指动，新苞来上林。","此儿生似玉，馈我重如金。","晚火炊鲜滑，春雷发蛰深。","山园未能往，少快老饕心。"]},{"t":"悠然阁为歙郑处士作","f":"五言律诗","c":["郑子林居好，遥希靖节贤。","看山秋色里，把酒菊花前。","人境殊多事，吾庐自一天。","能知此中意，何处不悠然。"]},{"t":"次杜德常佥院韵","f":"五言律诗","c":["鳌禁欣同直，高閒胜俗忙。","露花迎夕敛，风树借秋凉。","太史兰台笔，郎官粉署香。","时时铃索静，有喜到岩廊。"]},{"t":"闻董孟起副枢乃弟鄂霄院判凶讣哭之二首 其一","f":"五言律诗","c":["天狗忽堕地，兵生牙帐中。","宁为仗剑死，不作倒戈攻。","故国魂归黑，平原血溅红。","惊心激此变，谁为责元戎。"]},{"t":"闻董孟起副枢乃弟鄂霄院判凶讣哭之二首 其二","f":"五言律诗","c":["群盗犹铜马，将军真虎牙。","死当为厉鬼，生不负皇家。","野色含沈日，河声怒捲沙。","征东失名将，朝野共惊嗟。"]},{"t":"过黄河","f":"五言律诗","c":["食指朝来动，行庖旅次添。","淮鱼初出网，野鸭乍供盐。","新米如珠滑，香醪过蜜甜。","真成不负腹，聊尔一掀髯。"]},{"t":"陪东泉学士泛湖","f":"五言律诗","c":["山霭忽空无，春晖正满湖。","船头载家乐，花里驻行厨。","乐任喧呼动，归从酩酊扶。","使君留客意，更为倒金壶。"]},{"t":"题汪会语村隐居","f":"五言律诗","c":["闻道荆村僻，幽居趣自成。","桑中豚阱晚，芹外燕泥晴。","苔石留僧坐，山尊迟客倾。","凭轩久不到，望得白云生。"]},{"t":"题太史杨公山居图","f":"五言律诗","c":["湖上山居好，奎题压翠微。","烟霞改旧色，林壑发清晖。","松晚看书罢，荷凉坐钓归。","图中有真趣，须此挂朝衣。"]},{"t":"伍牧","f":"五言律诗","c":["苦战勤王事，精魂泣鬼雄。","坏城兵气黑，遗镞血花红。","故老谈亡国，明时录死忠。","长吟一搔首，落日鸟呼风。"]},{"t":"九日行湖上","f":"五言律诗","c":["是节最关情，随山得散行。","西风片雨过，落日半湖明。","野菊黄堪把，官醅绿可倾。","坐来无限思，散入远鸿声。"]},{"t":"莫矣","f":"五言律诗","c":["莫矣年光速，凄其世虑多。","半生县磬室，万事缺壶歌。","秃木风难响，寒云日易蹉。","向来出处意，不决欲如何。"]},{"t":"寄韩伯清","f":"五言律诗","c":["淫雨俄如此，能伤稼穑无。","积阴霾日月，愁色满江湖。","老大心空壮，艰难道愈孤。","美人秋水外，不寄锦襜褕。"]},{"t":"无题","f":"七言律诗","c":["见时略略望遥遥，有月阑干待袖招。","得巧蜘蛛丝缕细，传声鹦鹉舌关娇。","仙家弦管宁无谱，天上星河亦有桥。","云雨或时消息断，不如朝暮石城潮。"]},{"t":"闻笛","f":"七言律诗","c":["何人吹笛傍江干，木落淮南夜色寒。","三弄水边人舣棹，一声云杪客凭栏。","梅花簌簌吹应落，杨柳依依折欲残。","惆怅绿珠何处在，绮窗深锁月漫漫。"]},{"t":"台城","f":"七言律诗","c":["运尽黄旗晋祚开，天星俄复坼三台。","方惊掘地双鹅起，已见浮江五马来。","草暗离宫碑仆土，雨残战地骨生苔。","当时一掬新亭泪，犹带寒潮日暮回。"]},{"t":"冶城","f":"七言律诗","c":["此地先皇驻六龙，鼎成龙去杳无踪。","御床罗帕尘空暗，辇道朱门草已空。","题榜侍臣留帝敕，筑亭真士记天容。","自怜不及窥弓剑，愁绝寒城响暮钟。"]},{"t":"鹿苑寺","f":"七言律诗","c":["千古南朝几劫灰，萧梁寺额独崔嵬。","化蛇妒妇馀空井，刺虎将军有旧台。","江口山红寒照没，石头树白暝烟来。","满衣落叶西风急，更为凭高送一杯。"]},{"t":"瓦棺寺","f":"七言律诗","c":["脩竹长松昼寂然，梵宫高阁起中天。","虎头妙画空馀刻，鸱吻名书竟不传。","石柱至今标宿莽，瓦棺何处葬寒烟。","凭高更尽阑干曲，及取江山未暮前。"]},{"t":"石头城用萨天锡韵","f":"七言律诗","c":["逶迤石路带城遥，古寺残碑藓半凋。","一自降王归上国，空馀故老说前朝。","坏陵鬼剽传金盌，画壁仙妆剥凤翘。","更欲留连尽奇观，夕阳江上又生潮。"]},{"t":"癸亥岁八月十六夜对月","f":"七言律诗","c":["蟋蟀梧桐秋满庭，浮云散尽见疏星。","仙人修月浑无迹，使客乘槎自有灵。","一道银河通碧海，三更白露下青冥。","西风忽起吹黄鹄，梦断瑶台醉未醒。"]},{"t":"七忆 其一 忆钱塘","f":"七言律诗","c":["平湖十里碧漪风，歌舫渔舟远近同。","天竺雨馀山扑翠，海门潮上日蒸红。","伤心花月随年换，回首闾阎委地空。","白发故人零落尽，浮生怅望梦魂中。"]},{"t":"七忆 其二 忆姑苏","f":"七言律诗","c":["让王城外暮云黄，忍使行人哭战场。","台上麋游香径冷，陵头虎去剑池荒。","竹枝夜月歌仍怨，莼菜秋风兴漫长。","不是不归归未得，五湖烟水正茫茫。"]},{"t":"七忆 其三 忆会稽","f":"七言律诗","c":["千岩秋色彻层霄，忆昔来乘使者轺。","翠袖屡扶蓬阁醉，篮舆时赴宝林招。","山阴客已无春会，溪上风犹送暮樵。","此恨古今销不尽，西陵寂寞又回潮。"]},{"t":"七忆 其五 忆金陵","f":"七言律诗","c":["昔年曾上凤凰台，二水三山眼界开。","六代繁华春草歇，千年兴废暮潮哀。","灯窗禅坐时联句，山馆仙游几引杯。","最是令人愁绝处，夕阳双燕自归来。"]},{"t":"七忆 其七 忆闽中","f":"七言律诗","c":["漫漫涨海际天涯，万里曾乘使者槎。","梓泽重寻仙客洞，草堂频醉故侯家。","人多熟酒烧红叶，市有生蛮卖象牙。","安得梦中真化蝶，翩然飞上刺桐花。"]},{"t":"中秋次友生玩月韵","f":"七言律诗","c":["华月光浮玉色醪，凉飔时拂紫■袍。","河通阁道流云急，星绕天枢出地高。","按舞岂无仙跨鹤，纵吟聊放客挥毫。","扁舟近忆樟亭下，曾看鱼龙送夜涛。"]},{"t":"闰九月游钱塘南屏诸山","f":"七言律诗","c":["山僧领客兴何长，慧日峰前俯大荒。","旧俗尚传三令节，人生难遇两重阳。","丹枫换叶随秋老，黄菊留花过闰香。","更与摩崖访陈迹，西风吹冷薜萝裳。"]},{"t":"闰中秋是日白露节","f":"七言律诗","c":["河汉云消溢素光，重开樽酒据绳床。","嫦娥斟酒犹前夕，老子婆娑且醉乡。","风信两番生绿桂，年华一寸入黄杨。","怪来诗思清难忍，早雁声中露欲霜。"]},{"t":"七月望对月","f":"七言律诗","c":["新秋月色初圆夜，远客楼中独坐时。","却数只惊身老大，相看聊与影栖迟。","神仙宫阙开三岛，牛女星河淡两旗。","不是吴刚频伐树，西风应长出轮枝。"]},{"t":"中秋广陵对月","f":"七言律诗","c":["散尽浮云月在东，白蕉衫冷小庭空。","星河夜影樽罍里，城郭秋声鼓角中。","落叶有光时坠露，鸣蛩无响不含风。","此生五十三回见，只遣嫦娥笑秃翁。"]},{"t":"上元宿通州杨原诚寓宅","f":"七言律诗","c":["禁城东下一川平，杳杳烟芜淡淡晴。","风滚暗尘羊角转，水披残冻鸭头生。","离居有酒春堪醉，小市无灯月自明。","还忆故园今夕赏，玉人花底共吹笙。"]},{"t":"丁亥元日","f":"七言律诗","c":["梅花院落雨声中，窗外春寒淰淰风。","腊酒拨醅浮玉蚁，夜灯挑烬落金虫。","星环甲纪惊身老，雪解寅朝验岁丰。","还喜驿书催上路，寸心长在日华东。"]},{"t":"中秋玩月崇真万寿宫","f":"七言律诗","c":["西风吹月出云端，松柏流光绕石坛。","上国山河天广大，仙家楼观夜高寒。","似闻玉杵鸣玄兔，疑有瑶笙下翠鸾。","只把酒杯供醉赏，不知零露满金盘。"]},{"t":"四月旦日雨中送春","f":"七言律诗","c":["苦笋樱桃次第来，雨馀官树绿连街。","白缨蚯蚓歌幽草，赤帻蚍蜉穴古槐。","短发欲星愁有效，幻身如电事无涯。","人间恩怨何须论，团扇清风又入怀。"]},{"t":"述古真人寿席为赋","f":"七言律诗","c":["龙虎山中有洞天，长生见此老彭篯。","羽衣小作金门客，玉箓元书紫府仙。","药灶夜光丹似日，寿尊春色酒如泉。","未须便觅云林隐，更阅人间八百年。"]},{"t":"春日泛湖陪李旻德融席上作","f":"七言律诗","c":["春来浑不到湖边，偶逐东风上画船。","花气暖流黄鸟岸，水光晴展白鸥天。","绿尊兴极频呼酒，银管声高正辊弦。","我比放翁应更放，看花不独海棠颠。"]},{"t":"雪后苦寒","f":"七言律诗","c":["雪后北风尤苦寒，燎炉起拥懒头冠。","谩怀学士酴醾酒，仍对先生苜蓿盘。","戎马尚惊尘滚滚，客槎空望海漫漫。","向来事是今朝梦，底用悲吟且自宽。"]},{"t":"喜雨","f":"七言律诗","c":["日气如焚土气腥，黑云当午忽冥冥。","雨工分下旗千队，神姥携来酒一瓶。","牛马长河迷渚涘，龙蛇平陆起雷霆。","快看一洗飞蝗尽，犹及秋田晚稼青。"]},{"t":"清明日到陈庄","f":"七言律诗","c":["出郭东门古道斜，独骑款段稳于车。","春才三月已两月，村旧百家无十家。","山径低飞鬼蛱蝶，野塘竞噪官虾蟆。","东风不奈晚愈恶，吹散满身杨白花。"]},{"t":"东西马塍春行柬平湜伯容","f":"七言律诗","c":["清明时节每多阴，杨柳人家花满林。","侵晓乍收连日雨，赏春常负百年心。","凫翁一一蒲塘暖，雉子斑斑麦陇深。","为报能诗平处士，剩携芳酒共幽寻。"]},{"t":"暮春有感次刘监丞","f":"七言律诗","c":["二鸟宁容一处囚，能鸣何似不鸣休。","来今往古无穷事，剩水残山总是愁。","欲识碧云须丽句，拟裁白雪欠名讴。","强颜未得投簪去，一濯尘缨万古流。"]},{"t":"上京大雨骤寒饮周从道所","f":"七言律诗","c":["莫年已卜田园去，岂意犹歌行路难。","且复酒杯同旅次，不堪人事总忧端。","山林茅屋三生远，风雨毡裘六月寒。","吾友有家应此住，老夫何地挂吾冠。"]},{"t":"游凤凰山故宫至高禖台鸿雁池","f":"七言律诗","c":["衰草寒烟老木风，南朝佳气落秋空。","璧来山鬼遮秦使，盘泣仙人出汉宫。","坏埒尚传祠乙鸟，荒池曾见射飞鸿。","骚人自古多离思，长在登临感慨中。"]},{"t":"春日偕监中士友游南城","f":"七言律诗","c":["楼阁参差紫翠间，微风不动綵云閒。","柳垂禁籞丝千尺，水绕宫沟玉一环。","春树鸟鸣圆似筦，夕阳驼影兀如山。","醉鞭缓缓吟归去，灯火城东未掩关。"]},{"t":"上京秋日三首 其一","f":"七言律诗","c":["山前孤戍水边营，落日无人已断行。","瓯脱数家门早闭，轒温千帐火宵明。","白摧野草狼同色，秋入榆关雁有声。","最是不禁横笛怨，海天秋月不胜情。"]},{"t":"上京秋日三首 其二","f":"七言律诗","c":["水绕云回万里川，鸟飞不下草连天。","歌残敕勒风生帐，猎罢阏氏雪没鞯。","红颊女儿花作队，紫髯都护酒如泉。","时巡岁岁还京乐，别换新声被管弦。"]},{"t":"上京秋日三首 其三","f":"七言律诗","c":["远山平野浩茫茫，曾是当年古战场。","饮马水乾沙窟白，射雕尘起碛云黄。","中郎节在仍归汉，校尉城空罢护羌。","今日车书逢混一，不辞垂老看毡乡。"]},{"t":"三月二日赏杏花光岳堂分韵","f":"七言律诗","c":["柳色初青草渐茸，春寒犹勒杏花风。","新烟院落清明后，过雨园林罨画中。","洛社衣冠今日再，兰亭觞咏此情同。","吾年最老身仍健，更向尊前借酒红。"]},{"t":"腊日饮赵氏亭","f":"七言律诗","c":["城上高亭一再过，每看风物费吟哦。","近诗颇效寒山子，往事徒成春梦婆。","剩买十千燕市酒，閒听二八越娘歌。","梅花枉报春消息，祗遣今年别恨多。"]},{"t":"秋日偕成竹居秦景桓游蜀冈万花园","f":"七言律诗","c":["九曲池平带蜀冈，吴公台远隔雷塘。","閒寻遗迹怀千古，迥立高丘望八荒。","黄落山川秋广大，青冥风露日凄凉。","一尊不慰登临地，朔雁南云恨更长。"]},{"t":"春日游王公亮南墅","f":"七言律诗","c":["人家星散住村墟，第二港头潮水初。","蛱蝶一阑花院落，乌犍千亩雨犁锄。","养鱼已得陶朱法，种树还抄汜胜书。","兴熟不辞归路远，醉扶斜日上柴车。"]},{"t":"秋日陪吴兴诸府公宴鲁公池上","f":"七言律诗","c":["芙蓉池上会群公，满意华筵笑语中。","虹影连蜷山外雨，荷香澹荡晚来风。","歌催银甲筝逾急，凉入金樽露易空。","我亦玉堂挥翰手，题诗合在水晶宫。"]},{"t":"刊史局雨凉陪韩左丞叔亨小集","f":"七言律诗","c":["断烟疏雨散秋虹，古木高堂纳晚风。","青史文章千古上，紫微星象五云中。","前朝无似于今盛，群彦难期此会同。","凉思满帘宜解带，好怀宁放酒杯空。"]},{"t":"中秋张外史招赏月失约赋以谢之","f":"七言律诗","c":["明月中天雾气消，酒醒凉思正飘飘。","星河不动秋空阔，钟鼓无声夜寂寥。","露下远山皆落木，风来沧海欲生潮。","仙家玩事无缘到，虚负琼楼听玉箫。"]},{"t":"辛巳二月朔登悯忠阁","f":"七言律诗","c":["百级危梯溯碧空，凭阑浩浩纳长风。","金银宫阙诸天上，锦绣山川一气中。","事往前朝僧自老，魂来沧海鬼犹雄。","只怜春色城南苑，寂寞馀花落旧红。"]},{"t":"早发潞阳驿","f":"七言律诗","c":["征车如水辔如丝，望入金河欲曙时。","万里山川环拱抱，九天宫阙起参差。","风林泥泥秋多露，野淀棱棱晓有澌。","三十馀年观国愿，白头今日到京师。"]},{"t":"上京即事","f":"七言律诗","c":["滦河东出水潆洄，叠坂层冈拥复开。","金柱镇龙僧咒罢，玉舆驭象帝乘来。","中天星斗朝黄道，塞漠云山绕紫台。","欲拟两京为赋颂，白头平子愧无才。"]},{"t":"舟发浙江夜泊庙山驿","f":"七言律诗","c":["风帆东上浪冥冥，钟鼓山前近驿亭。","江海秋生河汉白，鱼龙夜没水云青。","谁从三岛求仙药，自信孤槎应客星。","好唤吴儿扣舷起，浩歌呼酒月中听。"]},{"t":"豫章山房为见心复公赋","f":"七言律诗","c":["剑江寺里古樟树，百尺如盖青童童。","山灵长此护林壑，雷电不许藏蛇龙。","扫石僮来秋叶后，谈经僧坐昼阴中。","题诗禅房更潇洒，便与王城祗树同。"]},{"t":"上清山中","f":"七言律诗","c":["烟景空明石路微，千年草木驻光辉。","山中观阙金银气，天上神仙黼黻衣。","赤石大溪鱼欲化，青云玄圃鹤长飞。","只今浩劫频来往，未信沧洲与愿违。"]},{"t":"四明寓居即事","f":"七言律诗","c":["郡城重镇浙江东，徼道荒芜雉堞空。","于越山川星纪外，故王台榭水云中。","船来蛮贾衣裳怪，潮上海鲜鳞鬣红。","不向旗亭时一醉，行人愁杀柳花风。"]},{"t":"雁自代过晋岭客中感兴","f":"七言律诗","c":["雁行初自雁门来，远度平沙阵势开。","光禄塞空霜气冽，受降城废水声哀。","乌孙公主歌难和，猿臂将军射未回。","今日客中肠易断，不须更上最高台。"]},{"t":"茌平道中","f":"七言律诗","c":["风起征尘满鬓须，频呼驿卒缓前驱。","已悲白骨多新鬼，尚说黄巾半畏途。","麦老大田鸣乳雉，草深荒径窜妖狐。","停骖思饮瓜园井，欲倩邻翁放辘轳。"]},{"t":"宴四明江中醉卧及醒舟已次车厩站","f":"七言律诗","c":["使节重来省昔年，旧游零落一凄然。","山川在眼空陈迹，歌舞催人又别筵。","风捲潮声全海起，雨分虹影半空悬。","酒醒惟有斜窗月，偏照姚江独夜船。"]},{"t":"发乐清县岑山亭","f":"七言律诗","c":["百尺新亭起碧岑，长藤古木郁萧森。","山重山掩分吴越，潮落潮生自古今。","飞鸟去边浮海色，夕阳明处散秋阴。","五云长近仙台上，时听鸾箫月下吟。"]},{"t":"石门书院瀑布","f":"七言律诗","c":["飞泉喷薄下灵湫，疑有龙居最上头。","长日风雷穿石起，半空河汉抉云流。","青牛隐去神宫在，玄鹤归来洞府幽。","弭节名山谐宿愿，筑居终羡昔贤游。"]},{"t":"西峡渡","f":"七言律诗","c":["江上日高寒雾开，渡头风顺早潮回。","中流白舫翩翩下，两岸青山滚滚来。","蛮媪浣纱衣似雪，驿夫到岸鼓如雷。","舍人起揭篷窗坐，笑割羊桃荐酒杯。"]},{"t":"湄洲屿","f":"七言律诗","c":["飞舸鲸涛渡渺冥，祠光坛上夜如星。","蛟龙笋簴县金石，云雾衣裳集殿庭。","万里使轺游冠绝，千秋海甸仰英灵。","乘槎欲借天风便，彷佛神山一发青。"]},{"t":"次福青宏路站州守林清源邀饮治所","f":"七言律诗","c":["酒家篱落隔青棕，更在轻烟细雨中。","绕郭好山横野碧，缘溪芳树立春红。","故人雪鬓年年老，太守风谣处处同。","十载相逢又相别，不堪回首海云东。"]},{"t":"浮山道中","f":"七言律诗","c":["处处人烟有酒旗，楝花开后絮飞时。","一溪春水浮黄颊，满树暄风叫画眉。","入境渐闻人语好，看山不厌马行迟。","江蓠绿遍汀洲外，拟折芳馨寄所思。"]},{"t":"北山苦雨待程继先舟行","f":"七言律诗","c":["老态已成便早睡，呼儿更与助深杯。","半窗风雨催秋到，一夜湖山入梦来。","潦水无根殊汎滥，蛩声多事为悲哀。","不知明发缘何喜，满意灯花落又开。"]},{"t":"寄龙翔欣公长老","f":"七言律诗","c":["古笪桥边夹道斜，老禅方丈梵王家。","山人宴坐时分芋，天女飞来或散花。","护法神龙蟠结构，定巢春燕避袈裟。","此生已悟空无住，欲就莎房借鹿车。"]},{"t":"登严先生两钓台","f":"七言律诗","c":["两台有径可跻攀，老树长藤荟蔚间。","渔钓自忘天子贵，风云何似客心閒。","钟催夜月来孤寺，帆挟春涛过乱山。","寂寞羊裘轩下路，几人携酒酹潺湲。"]},{"t":"滕王阁晚望","f":"七言律诗","c":["岧峣杰阁起城皋，尚想君王结构劳。","楚国山川推壮丽，唐人文赋擅风骚。","天开彭蠡连江阔，山向番禺入岭高。","万里登临一怀古，朔云秋兴正滔滔。"]},{"t":"南山莲社偕韩友直伯清昆季游龙井寺","f":"七言律诗","c":["长忆东林远法师，三生张野有前期。","经书贝叶翻重译，漏刻莲花礼六时。","长老布金多满地，高僧卓锡自成池。","不妨随喜诸天上，扶得风篁玉一枝。"]},{"t":"天竺山中访项可立不遇","f":"七言律诗","c":["葛洪川畔千年寺，路绕长松一涧分。","潭影青移行处岫，岚光白散望中云。","猿公吟树应思侣，鹿女衔花不乱群。","常羡山僧专胜概，水声林下百无闻。"]},{"t":"游万松庵","f":"七言律诗","c":["黄尘扑马出西城，忽见云林眼倍明。","竟日寂无山鸟语，满岚纯是涧松声。","石幢花雨何时洒，禅榻茶烟特地生。","客自去来钟梵外，老僧于世已忘情。"]},{"t":"扈从之上京过龙门","f":"七言律诗","c":["两崖高立色冥冥，仰视空光一罅青。","石兀马蹄危不度，水漂龙气暗闻腥。","山川壮自开天险，风雨阴疑来鬼灵。","我欲重寻旧题处，湿云寒藓满岩扃。"]},{"t":"游武康禺山留宿升元宫","f":"七言律诗","c":["白石西边山更青，杖藜尘外得经行。","鸟翻夕照落空翠，人逆松风闻涧声。","道士煮茶留夜话，田家烧草起春耕。","也知真境多佳境，拟约衡茅寄此生。"]},{"t":"四月护三丧渡江之宴坞","f":"七言律诗","c":["乱云散黑收残雨，落照浮红满大江。","烟际小星添个个，沙头宿鸟下双双。","文章烂漫工何补，胆气峥嵘老未降。","新喜仙翁与释子，买山容作读书窗。"]},{"t":"天竺北峰行香汎舟湖山堂","f":"七言律诗","c":["肩舆直过上湖西，泱漭晨光远欲迷。","风起涧松清不暑，雨乾石路净无泥。","泉分绝壑流边续，云到高峰尽处低。","投老宁能数来往，把杯洞口听猿啼。"]},{"t":"玄圃为上清道士周静脩题","f":"七言律诗","c":["路上仙岩最上溪，仙家住处有丹梯。","瑶台鹤下天风冷，灵锁花深晓日迷。","五色芝房团紫盖，千年石髓裂青泥。","羽人即此宜高隐，岂在昆崙万国西。"]},{"t":"梅雪斋为紫霄宫杨逢宾题","f":"七言律诗","c":["雪树生香满佩巾，紫霄最上集仙真。","苔荒鹤迹浑无路，花暗笙声不见人。","瑶圃月寒通白晓，丹台云暖驻长春。","莫教流水山前去，恐似桃源客问津。"]},{"t":"犀山凝翠台为上清道士刘伯达题","f":"七言律诗","c":["仙馆深居寂寞滨，千岩浓翠湿无尘。","筑台一日临风雨，驱石中宵使鬼神。","潭上昼游鱼听瑟，花间春醉鸟衔巾。","山灵不是藏真境，留待云栖学道人。"]},{"t":"爱松亭为嘉禾三塔寺宽海云赋","f":"七言律诗","c":["槜李湾头窣堵波，种来松树绕庭多。","碧粘老甲浑苔藓，黑入秋阴半薜萝。","古刹每闻龙舍宅，神僧常似鸟为窠。","无人访得韦侯笔，与作山堂障子歌。"]},{"t":"冰雪庵为衡岳北山上人赋","f":"七言律诗","c":["衡岳山中老道人，一龛一衲足容身。","禅林出定云生室，诗境行吟清入神。","瓶水不凝霞气暖，石门长埽虎蹄新。","只应煨芋烧茶外，乞火时时到寺邻。"]},{"t":"云松巢为翰林学士王公俨作","f":"七言律诗","c":["高人自昔爱云林，拟作幽居寓素心。","遁世每怀箕叟隐，题诗聊效谪仙吟。","几番白鹤迷秋梦，半树青萝补夕阴。","独坐天风洒毛发，高寒何似玉堂深。"]},{"t":"醉月堂为万声远作","f":"七言律诗","c":["月有秋期醉有乡，虚堂中夜挹流光。","九天零露溅尊俎，万里高风扶佩裳。","白凤飞回声缥渺，玉笙吹彻梦清凉。","醒来却觅神游处，狼籍中庭桂子香。"]},{"t":"不系舟渔者陈子上自号","f":"七言律诗","c":["本来无系亦无舟，随意江湖可漫游。","纵遣西风吹水外，不妨明月烂沙头。","人情平地波澜起，身世虚空日夜浮。","安得从君归把钓，只将吾道付沧洲。"]},{"t":"浮云道院","f":"七言律诗","c":["百年身世与云俱，日看纷纷变态殊。","江雨欲来龙气黑，天风忽散鹤声孤。","行藏与道同舒卷，富贵何心较有无。","此意高人还尽解，数椽营在楚山隅。"]},{"t":"石田山房为毛叔达作","f":"七言律诗","c":["荦确初开百亩荒，四明山麓有丹房。","种来玉子双双白，凿破云根寸寸方。","赤水洞天宜避世，全椒道士可休粮。","会寻瀑布声中去，一洗吾生浩劫忙。"]},{"t":"次韵刘伯贞与金山即休了长老唱和","f":"七言律诗","c":["老禅居处水云重，此地纤尘不可容。","潮色平铺无际海，日光先上最高峰。","踏花佛驭红牙象，献宝神骑白耳龙。","第一江山第一座，几时来听讲时钟。"]},{"t":"北山禅房次危太朴韵","f":"七言律诗","c":["一箪小寄青莲宇，尺土巍临白玉京。","名药晒庭分草木，好诗书壁杂真行。","劫尘息后心源净，僧腊高来颔雪生。","我住巷南师巷北，相过谈到暮钟声。"]},{"t":"游金山柬即休了公","f":"七言律诗","c":["八十了公如古佛，禅心已久会真如。","饭供南海浮来钵，经钞西天译后书。","持咒降龙秋雨歇，焚香迎客晚潮初。","此生终拟依莲社，犹苦尘缘未破除。"]},{"t":"寄越宝林别峰嘉禾水西仲铭 其一","f":"七言律诗","c":["越绝千峰有别峰，老禅宴坐梵王宫。","愿中结习三生熟，机外忘言万法空。","锡影夜飞天姥月，钟声晓度禹陵风。","孔淳自许游方者，须觅岩居竺法崇。"]},{"t":"寄越宝林别峰嘉禾水西仲铭 其二","f":"七言律诗","c":["劫灰不到爽溪亭，珍重堂头老仲铭。","朝暮钟鱼仍梵呗，虚空龙象自神灵。","幽禅定后灯悬壁，清盥閒来水在瓶。","草座麻衣亦吾事，会寻台上共翻经。"]},{"t":"寄越能仁用章俊禅师","f":"七言律诗","c":["晚节丛林道欲孤，喜公赤子服于菟。","千岩万壑平安否，淡饭长斋饱得无。","坐观山童窥止水，讲经龙女献明珠。","沃洲胜会还堪继，岂独东林有社图。"]},{"t":"寄清远渭禅师","f":"七言律诗","c":["自听龙翔寺里钟，劫馀金碧更重重。","天王按剑踏魔女，罗汉弄珠降老龙。","蒲室千镫谁继照，渭川一派自分宗。","未知今日西冈塔，留得荒寒几个松。"]},{"t":"寄四明定水见心复禅师","f":"七言律诗","c":["闻公近住慈溪寺，今是璘师第几镫。","笑我在前图作佛，只今投老欲依僧。","瓶中舍利藏来长，窗外猕猴唤得应。","会拂尘衣上方去，天香树底乞花蒸。"]},{"t":"寄平江开元寺雪窗光公","f":"七言律诗","c":["独木山寮昼不开，禅馀香印已成灰。","寺分麋鹿台前住，人向鱼凫国里来。","佛钵供多光类玉，祖衣传久色如苔。","一枝得个邛州竹，拄到云居不拟回。"]},{"t":"送西江贤古愚上人","f":"七言律诗","c":["山僧新自豫章回，千里还乘渡水杯。","问法诸天龙象绕，谈经半夜鬼神来。","西风夏解江云变，南国秋归野菊开。","欲叩心宗尘外侣，白头今日已成灰。"]},{"t":"送范准堂住天台法轮寺","f":"七言律诗","c":["白首南屏坐不回，偶提佛法住天台。","幽禅有味风生磬，瘦影无尘月满台。","罗汉山中飞锡过，鲛人海上献珠来。","不知万壑烟霞底，何处寻师拨芋煨。"]},{"t":"送道存师游方","f":"七言律诗","c":["故人去作远游僧，千里关河付脚縢。","坏衲秋缝慈母线，空山夜别祖师灯。","王城乞食应持钵，岳寺栖禅暂挂藤。","何日诸方参叩遍，一庵归老白云层。"]},{"t":"送绝宗继讲师住大雄寺","f":"七言律诗","c":["大展三衣古道场，真人高拱殿中央。","曼陀雨散天花落，薰陆烟生石乳香。","纚纚风雷飞讲舌，耽耽龙象绕禅床。","师行不废宗雷社，会觅篮舆到上方。"]},{"t":"送泐季潭还龙翔","f":"七言律诗","c":["曾将小品问支公，真是人间学道雄。","弟子不须悲灭度，禅师久已證圆通。","长怀石上三生旧，无复溪头一笑同。","想见西冈归礼塔，神光时绕夜坛红。"]},{"t":"送至上人还金陵","f":"七言律诗","c":["朱雀桥边白下门，旧游回首不堪论。","令威未返辽东鹤，圆泽难招石上魂。","金刹火馀灰已冷，锦囊诗在墨犹存。","南来邂逅逢师话，老泪临风堕酒尊。"]},{"t":"闻云海宽宝林同二师寂音悼之","f":"七言律诗","c":["久别吴宽与越同，近传归寂故禅宫。","葛川有日寻圆泽，莲社无人寄远公。","亭外松焚云海静，井间鳗化宝林空。","只留一点诗灯在，长照残山剩水中。"]},{"t":"答复见心见寄","f":"七言律诗","c":["莲花峰下天香树，吹老西风几度秋。","僧宝真同洪觉范，诗穷我亦孟参谋。","文章宇内千年事，身世江湖万里舟。","甚欲相期石桥路，更须同访羽人丘。"]},{"t":"重寄水西新公道场渭公三塔宽公 其一","f":"七言律诗","c":["我恐前生老法华，退居清淡即僧家。","禅师有道常骑虎，侍者通神自辟蛇。","已负法身来震旦，终抛尘网觅提奢。","洞庭春后多风水，准拟南归买钓车。"]},{"t":"重寄水西新公道场渭公三塔宽公 其二","f":"七言古诗","c":["道场山顶千年寺，迥出云林最上层。","师已新闻出世法，我今浑似在家僧。","书迟不到秋风雁，诗苦长县夜雨灯。","蚤晚南归有船□，□□□□□□□。"]},{"t":"筹峰真馆追松瀑黄石翁尊师","f":"七言律诗","c":["月色今宵恰满规，有山如此愧来迟。","金堂石室不到处，涧水松声无尽时。","麻姑凌寒或送酒，木客入夜同吟诗。","匡庐老仙去已远，怅望云间笙鹤期。"]},{"t":"送张惟善使还上清宫","f":"七言律诗","c":["驿骑翩翩万里归，上清山下是岩扉。","金银宫阙神仙馆，河汉文章织女机。","赤羽频县行处节，青霞自剪醮时衣。","使途邂逅还相别，回首江云朔雁飞。"]},{"t":"送道士张一无还安仁省亲","f":"七言律诗","c":["南楚东吴一草亭，道人元不叹飘零。","幻身在世真如露，客鬓经年渐欲星。","招隐山中猿鹤怨，话禅石上鬼神听。","殷勤此别须回首，不忘君家桂树青。"]},{"t":"赠别句曲外史张伯雨","f":"七言律诗","c":["玄洲别岛郁巃嵷，满谷蜷云护万松。","外史编图琼笈秘，隐居留诰玉函封。","丹池雨见龙无角，药圃春肥鹿有茸。","拟借一龛为洞吏，与君来往大茅峰。"]},{"t":"壶隐为滁州徐仁则赋","f":"七言律诗","c":["匏系深知固蒂难，餋生聊托一壶间。","仙公卖药曾藏市，逸士操瓢只在山。","千里江湖浮处远，百年日月贮来閒。","底须狡狯惊凡目，剖破轮囷别筑环。"]},{"t":"怀计筹山通真馆纯一云峰高士","f":"七言律诗","c":["彫年短发苦骎骎，只益孤怀叹惋深。","老比师丹浑忘事，死无钟子绝知音。","哀猿易下三声泪，独鹤长存万里心。","漫忆云峰凌羽士，故山无梦可相寻。"]},{"t":"送匡山王济远朱弘道南归","f":"七言律诗","c":["万峰苍翠绕舒城，中有琳宫似上清。","侠客剑寒腾虎气，仙人笙响作鸾声。","到山定及朱桃熟，归洞应多白鹿迎。","好在丹房保玄极，九还金液待君成。"]},{"t":"幻寓庵用虞芝亭学士韵","f":"七言律诗","c":["暂寄微躯在世尘，此庵名亦强为邻。","了知百岁旦暮事，岂泥三生前后因。","非假日明那有目，忽随空坏本无身。","要知枯坐环中者，别是人间不死人。"]},{"t":"送述古彭大年真人","f":"七言律诗","c":["袖有神方炼紫荷，几年璚箓著功多。","仙人海上骑黄鹤，道士山中认白骡。","枣木斗盘藏霹雳，杨枝瓶水洒天河。","只应小阅开皇劫，一剑秋空处处过。"]},{"t":"大年仙人乐天遗雷符一卷为题","f":"七言律诗","c":["一夕空飞解剑形，先生神气即风霆。","已还天阙朝群帝，别写雷符使六丁。","辽海鹤归云邈邈，葛陂龙化水冥冥。","只今有子能传业，来奉祠官篆檄灵。"]},{"t":"题闲闲吴宗师徒孙丁自南卷","f":"七言律诗","c":["羡君学道上清宫，亲得先生早发蒙。","枸杞未逢朱孺子，丹砂须问葛仙翁。","窗前点易寒研露，坛上焚香夜礼空。","化鹤归来定何事，从师千载住崆峒。"]},{"t":"送刘彦基奉宗师命访求道德经注","f":"七言律诗","c":["北风霜霰日冥冥，送子南归出广庭。","上国几年陪赐履，名山随处访藏经。","藜光照夜时燃火，龙气冲寒直射星。","却忆冲虚观前路，豫章双树更青青。"]},{"t":"壶洲为上清张道士题","f":"七言律诗","c":["锦水西头观阙青，仙家原不隔沧溟。","凤麟洲渚寒凝碧，云雾衣裳夜降灵。","金醴浸花留客醉，玉笙吹月使龙听。","看君福地容萧爽，长与曾孙宴幔亭。"]},{"t":"送上清道士李自宾归山","f":"七言律诗","c":["归去青溪点易窗，仙林如子世难双。","丹藏虎豹千山雪，剑度鱼龙万里江。","别洞苔花分石路，古坛松子落岩淙。","道人不用寻烟火，术煎经冬正满缸。"]},{"t":"送陈复斋归婺之武义清宁观","f":"七言律诗","c":["武川道馆白云间，萧散真宜羽客閒。","丹侣有情开药灶，青童应在守萝关。","冈头叱石成羊起，花下吹笙驭鹤还。","岁晚相思拟相觅，只愁落叶满空山。"]},{"t":"送胡道士还豫章舟居","f":"七言律诗","c":["道人船子是行窝，如此东湖烟水何。","宝剑携将叱雷雨，钱符埋得镇蛟鼍。","云盘仙篆朱文细，海浴神丹绛气多。","应与匡庐桂风子，山中骑虎夜相过。"]},{"t":"送薛鹤斋南归吴中","f":"七言律诗","c":["老鹤幡然忆楚皋，南来直渡浙江涛。","千年故国悲城郭，万里晴空见羽毛。","候馆夜吟飞綵翰，灵坛秋醮振琅璈。","隃麋白屋山中路，留得仙家旧种桃。"]},{"t":"云台真馆为上清周用章作","f":"七言律诗","c":["突兀中天积翠遥，层台宛似郁罗萧。","清池晓浴丹如火，白石春耕玉有苗。","此地来龙如可筑，他年归鹤底须招。","只应月夜游仙侣，时复吹笙下紫霄。"]},{"t":"送方玉壶羽士之京师","f":"七言律诗","c":["学道武夷还上清，羽人毛骨鹤同轻。","丹留别室生虹气，啸隔空山作虎声。","剑外鬼神来叱咤，画中河岳入经营。","缑山合在飞廉馆，会见祠光彻夜明。"]},{"t":"挽张伯雨宗契 其一","f":"七言律诗","c":["一夕星坛蜕羽衣，山灵何许散灵辉。","书留真诰陶弘景，名在丹台马子微。","海上青骡应远去，垆中白兔想潜飞。","风篁后夜还成韵，犹似箫声月下归。"]},{"t":"挽张伯雨宗契 其二","f":"七言律诗","c":["鹿巾曾入紫宸朝，归向名山驻绿轺。","龟脱生筒无俗累，鹤存瘦骨有仙标。","三元饥饭杯犹在，五色香烟火已消。","应复神游易仙馆，人间楚些若为招。"]},{"t":"挽张伯雨宗契 其三","f":"七言律诗","c":["童稚情亲到白纷，真香几向鹊炉焚。","丹成自浣天坛雨，剑解空埋月涧坟。","山友分将石刻帖，门人唱得锦飞群。","他时会续君前传，刊作青琼板上文。"]},{"t":"正一冲和宫杨弘道以虞学士诗求和 其一","f":"七言律诗","c":["玄都桃是旧时花，曾驻春游送客车。","翰墨尚看延阁老，松萝长护羽人家。","丹砂鍊得仙翁术，白绢封来谏议茶。","文采风流徒想见，九霄无佩乞飞霞。"]},{"t":"正一冲和宫杨弘道以虞学士诗求和 其二","f":"七言律诗","c":["往事真成过眼花，前王俱此走降车。","鹤归华表千年郭，燕入乌衣百姓家。","雨坏苑墙生野荠，云残候馆老山茶。","欲将吊古无穷意，高倚披云赋落霞。"]},{"t":"广东帅府掾林德恭饷藤簟","f":"七言律诗","c":["韬向筒中一握轻，风漪八尺胜桃笙。","文编黑白蚺皮滑，漆透丹黄虎魄明。","坞上卷将沧海色，岭南寄与故人情。","竹床楠枕山窗下，从此酣眠梦亦清。"]},{"t":"铁笛为孟天炜赋","f":"七言律诗","c":["爱此轻圆铁铸成，何须楚竹选孤生。","年多化作青蛇色，夜静吹如彩凤声。","绣出碧花凝错落，冷含金气发铿清。","最宜携向君山去，一听仙翁奏月明。"]},{"t":"给事以马乳贶就索诗","f":"七言律诗","c":["挏官载出橐驼马，分得官壶给事家。","代饮酪奴宁许敌，蒸豚人乳不成誇。","肥凝晓露䲭夷革，香带秋风苜蓿花。","长与诗翁消酒渴，肯辞为客住龙沙。"]},{"t":"仙娥玩月图为野云陈氏题","f":"七言律诗","c":["仙娥微步下高寒，独立长松月满山。","妆影透明金背镜，佩声飞动玉连环。","洗空碧海银蟾冷，舞罢瑶阶白凤閒。","不是丹青寄颜色，行云无梦到人间。"]},{"t":"陈子平寄所作琼花答谢","f":"七言律诗","c":["凤在阳冈鹤在皋，相思空遣梦劳劳。","箫吹夜月江桥酒，槎泛秋风海市涛。","故国山川吴分野，美人词赋楚离骚。","琼花新制人争写，应使扬州纸价高。"]},{"t":"周汉长公府临安故城二图 其一","f":"七言律诗","c":["主家楼观郁参差，想见当年全盛时。","宫草细侵行辇路，苑花深覆泛舟池。","瑶台仙去尘生海，甲帐神来风满旗。","好在画图留胜迹，五云长护鹤笙祠。"]},{"t":"周汉长公府临安故城二图 其二","f":"七言律诗","c":["南渡君臣建业偏，不堪乔木黯风烟。","岂知白马兴王后，又到红羊换劫年。","三辅黄图空郡国，六朝王气渺山川。","白头开府归来日，应览遗踪一怆然。"]},{"t":"海楼为宛丘秋藏用题","f":"七言律诗","c":["不著阑干百尺高，难容此客卧云涛。","深连厚地三千轴，迥压神仙十五鳌。","日影夜生浮画栋，珠光秋孕射霜袍。","醉来白眼看馀子，未许元龙气独豪。"]},{"t":"太古楼为豫章傅道士题","f":"七言律诗","c":["羽客栖玄紫极宫，楼居三景自玲珑。","游云宛在洪荒世，探道元居恍惚中。","窗白夜生南浦月，帘高时卷上江风。","如何宴坐忘机者，千劫尘缘一息空。"]},{"t":"半村为傅处士赋","f":"七言律诗","c":["半距城闉半距村，烟霞咫尺少尘喧。","小车出市仆先路，斜日下山人到门。","两岸花阴连第宅，一川草色散鸡豚。","田家数里将迎惯，时复相留醉酒樽。"]},{"t":"李克约饷腊梅并诗用韵答之","f":"七言律诗","c":["空谷佳人缟袂单，淡黄衫薄护春寒。","色欺隐者山中桂，香逼骚灵畹里兰。","鸟吐粟金妆处巧，蜂留蜜滓鍊来乾。","数枝乞与吟窗供，温水铜瓶自插看。"]},{"t":"霍丘孙游武林湖山之胜诏之","f":"七言律诗","c":["千顷平湖绕郡城，画船小桨荡春声。","红酣花港风荷密，玉照梅冈雪树明。","烟月长留歌舞地，山川不改古今情。","君行须到峰南北，为觅苍苔石上名。"]},{"t":"怀临川旧游赋以赠别戈直伯敬","f":"七言律诗","c":["拟岘台前汝水流，因君还忆旧曾游。","故人零落半为鬼，贱子蹉跎今白头。","诗思入江枫叶冷，乡心随雨雁声秋。","北斋居士知强健，为觅新篇慰别愁。"]},{"t":"暮春偶作","f":"七言律诗","c":["瞢腾睡思酒频中，潦倒吟怀语不工。","燕子人家春复夏，楝花时候雨兼风。","青林脱虱成蝴蝶，白水鸣蛙抱活东。","甚欲相从问丹诀，顶间朱橘几时红。"]},{"t":"草堂为胡晋仲题","f":"七言律诗","c":["姑孰城中林壑奇，幽人爱此结茅茨。","垂窗已著卢鸿画，绕壁惟书杜甫诗。","花气晴薰烧酒火，潮痕晚上钓鱼丝。","数椽有此真堪隐，不待山灵重勒移。"]},{"t":"赠相士陈巨山","f":"七言律诗","c":["老我宁甘彻骨贫，多君见与掇皮真。","垂厓本是无情者，若水终为勇退人。","机外骊黄难著相，眼中青白自如神。","华峰太极图犹在，何日相欈问隐沦。"]},{"t":"赠地理家何玉泉","f":"七言律诗","c":["芒屩筇枝兴渺然，知君曾得异人传。","经探玉髓青囊秘，山隐金精铁锁县。","腹有丹光飞日月，眼穷地脉入云烟。","几时把袂神州路，共看华嵩翠插天。"]},{"t":"赠易学李所翁","f":"七言律诗","c":["易学如翁近所无，蔼然声问动江湖。","蓍龟凶吉占如繇，爻象纵横画有图。","三卷秘书传句曲，百钱卜肆隐成都。","相逢欲问平生事，何惜春醪满眼沽。"]},{"t":"赠筝工任礼","f":"七言律诗","c":["牙床银甲不胜清，锦席瑶筝无限情。","第一部中当绝艺，十三弦上有新声。","齐宫蝉怨时时咽，湘浦鸿来个个惊。","宜向教坊供国乐，要须名似郭无名。"]},{"t":"玉笙为陆国瑞赋","f":"七言律诗","c":["曾听仙人白玉笙，飞琼有谱学初成。","碧桃半向露中落，采凤忽来云际鸣。","瑟响洞庭空写恨，磬浮瀛海不传声。","何如吹上扁舟去，秋满西湖月正明。"]},{"t":"长至日题","f":"七言律诗","c":["佳节萧然无过宾，馂馀觞豆自相亲。","斗垂西柄半入海，梅发南枝先得春。","平日以文为事业，老来惟酒是精神。","莫论炊熟邯郸未，巳是山翁一欠伸。"]},{"t":"元夜独坐","f":"七言律诗","c":["九衢花月万家灯，忆在钱塘与广陵。","过去豪华春似梦，老来心赏冷于冰。","苏耽仙后还为鹤，房琯生前本是僧。","唤取家人多置酒，只将寂寞付瞢腾。"]},{"t":"夜起","f":"七言律诗","c":["月落未落霜满城，鸡鸣不鸣山四更，起看北斗寒挂地，俯听长河流有声。","今夕何夕耿无寐，千古万古难为情。","欲持心事出门去，哀歌坐待东方明。"]},{"t":"秋怀","f":"七言律诗","c":["山人底事缚微官，来对阑干首蓿盘。","匣印少开经雨涩，箧衣多敝入秋寒。","劳生沙漠随征毂，入梦江湖有钓竿。","歌罢中庭待明发，起看星汉正漫漫。"]},{"t":"世事","f":"七言律诗","c":["世事纷纷在目前，故园无复可归年。","吴东城陷仍为沼，沧海尘生欲变田。","鼠穴讵容衔窭薮，豨膏聊解运方穿。","臣心有血才盈掬，拟向天公罄一笺。"]},{"t":"殿试翥与读卷官","f":"七言律诗","c":["老臣载笔侍金銮，自愧三叨读卷官。","进士擢科从古盛，大臣考策得才难。","芳年荏苒闻鶗鴂，花事从容到牡丹。","明发禁扃当彻锁，文光高动五云端。"]},{"t":"翰林三朝御容戊戌仲冬朔把香前宫","f":"七言律诗","c":["嘉禧殿前初日高，瑞光先映赭黄袍。","云间瑞露收金掌，仗外微风飏彩旄。","黄鹤仙人周子晋，碧鸡使者汉王褒。","禁园尚觉馀寒在，未放春红上小桃。"]},{"t":"甲午礼闱","f":"七言律诗","c":["白雪青天映日红，楼台高下瑞光中。","佳辰正际新春晦，薄冷犹吹向晓风。","万国衣冠朝北阙，一时文献集南宫。","吾皇方此求贤俊，载笔宁惭奉至公。"]},{"t":"九月朔迎驾大口","f":"七言律诗","c":["大驾今朝至上都，期门䍐罼已前驱。","锦衣照日环龙衮，翠盖凌云覆象瑜。","万里山河开白道，两京宫阙入黄图。","纵观父老心应喜，知有天恩免过租。"]},{"t":"庚辰十月朔奉迎明宗册宝至石佛寺明日壬辰迎至太庙清祀礼成赋以纪事","f":"七言律诗","c":["宝册香舆出法宫，非烟御路晓濛濛。","仗齐剑佩千官里，金奏箫韶九庙中。","宣室鬼神徵贾谊，太常礼乐属孙通。","下臣有幸逢熙事，散作恩波四海同。"]},{"t":"圜丘礼成改直翰林策书告庙祝版 其一","f":"七言律诗","c":["捧册先期吁太宫，圣孙翼翼孝心同。","霓旌晓绚香舆日，鹤驾晴薰仗外风。","一代皇猷昭黼黻，万年宝历卜濛鸿。","舞阶行见干戈戢，并在穹祇叶相中。"]},{"t":"圜丘礼成改直翰林策书告庙祝版 其二","f":"七言律诗","c":["黼黻青城焕景光，紫檀黄道蔼天香。","凤韶曲变初终奏，龙衮衣明上下章。","共喜圣时修旷典，更从春享议明堂。","吾皇饮福神灵毕，却进公卿万寿觞。"]},{"t":"直延春阁","f":"七言律诗","c":["蓬莱海上第三山，仙掌云间十二槃。","鸡树烟深殊窈窕，凤楼天近自高寒。","铜壶传箭声相应，紫诏封泥墨未乾。","愿祝君王千万寿，坐施雄断济艰难。"]},{"t":"送太傅丞相出师平徐方","f":"七言律诗","c":["南征诸将久无功，丞相亲劳出总戎。","虎士严兵屯玉帐，龙庭大宴赐彤弓。","万年社稷收长算，百战旌旗得胜风。","幕府如云尽才彦，荆徐指日捷书同。"]},{"t":"初度日","f":"七言律诗","c":["八十一翁乌角巾，尊前才放自由身。","病须善药休离手，衰借佳醪可餋神。","谁谓仲连为侠士，或传方朔是仙人。","行当小筑西洋墅，种杏栽桃作好春。"]},{"t":"癸酉初度真率会分韵","f":"七言律诗","c":["杏花风暖破春阴，一笑幽斋喜盍簪。","人事万端相聚少，酒杯百罚不辞深。","生辰值月方传斗，故国观星正在参。","多谢诸君为我寿，满笺佳句敌南金。"]},{"t":"乙亥初度是岁仍改至元","f":"七言律诗","c":["此生重见至元年，白发垂垂已满颠。","仕愧买臣无印绶，归思靖节有园田。","菜挑渚雪冰茸滑，柑剥吴霜玉脑圆。","终结一庵湖上去，老来閒送佛前钱。"]},{"t":"病痁 其一","f":"七言律诗","c":["肉黄皮皱发毛枯，一病支离困壮夫。","痛要小奴搥臂膝，冷寻破帽聚头颅。","邻翁教诵禳灾咒，道士来书禁疟符。","车辙马蹄劳客问，药囊糜椀乏吾须。"]},{"t":"病痁 其二","f":"七言律诗","c":["炎火寒冰忽暗投，肺肠日与药为谋。","拟寻画史图狮子，安得诗人咏髑髅。","月色自如閒度夜，虫声无赖乱吟秋。","便当一起幽忧疾，濯发西风万里流。"]},{"t":"自喻","f":"七言律诗","c":["狎鸥不下解知机，蟋蟀先鸣能表微。","人海无涯俱泛泛，佛天有相亦非非。","试论前辈今谁在，欲问何山老可归。","严濑磻溪各求志，岂关出处在渔矶。"]},{"t":"忆山中","f":"七言律诗","c":["买山晏坞近天根，遥忆春深正灌园。","一树烂红樱著子，满林鲜碧竹生孙。","少陵只拟还韦曲，安石端宜得谢墩。","归老会寻凌道士，采芝烧药了晨昏。"]},{"t":"感兴","f":"七言律诗","c":["从来豪杰愿风尘，奋臂干戈肯顾身。","司马诸王祇乱晋，祖龙二世竟亡秦。","祠旁鬼火狐鸣恶，桥下天寒鹤语神。","千古汗青留感慨，山中输与种桃人。"]},{"t":"忆广陵旧事","f":"七言律诗","c":["君王昔在镇南年，宾客风流日满筵。","上国旌旗分一半，层台歌舞宿三千。","豪华遽尽悲离黍，形胜空存惨暮烟。","多少楚魂归未得，江流无际海连天。"]},{"t":"寄宝林同别峰定水复见心","f":"七言律诗","c":["宝林老子虎耽耽，定水道人蒲作庵。","归老尚须游越绝，寻师先儗到精蓝。","越江碑在当重读，禹穴书藏会一探。","我亦三生学环者，定从佳处结禅龛。"]},{"t":"怀清源洞游","f":"七言律诗","c":["漫漫涨海际天涯，万里乘来使者槎。","紫泽重寻仙客洞，碧山常醉故侯家。","人多熟酒烧藤叶，市有生蛮卖象牙。","安得梦中时化蝶，翩翩飞向刺桐花。"]},{"t":"寄副枢董抟霄孟起","f":"七言律诗","c":["王师前后压瀛河，万里风云入荡摩。","晋帅先宜谋郤縠，赵人终欲用廉颇。","枚衔突骑宵传令，鼓发辕门晓拥戈。","共待将军白羽扇，归来幕府上功多。"]},{"t":"寄野庵察罕平章","f":"七言律诗","c":["圣主中兴大业难，元戎报国寸心丹。","军中诸将惊韩信，天下苍生望谢安。","露布北来兵气盛，楼船南渡海波寒。","拟将旧直词林笔，细传成功后世看。"]},{"t":"大军下济南","f":"七言律诗","c":["总戎十万铁鹞子，殪贼一双金仆姑。","白日照开华不注，乱云飞尽大明湖。","数年父老回生气，千里山川复旧图。","已喜武威平汴兖，可倾东海洗兵无。"]},{"t":"哀孝子夏永庆","f":"七言律诗","c":["翁已生全儿殒躯，投文我欲诘天吴。","一时肝胆宁知死，万顷波涛视若无。","骨葬夜泉鲸穴冷，魂归故国蜃云孤。","自今孝子流风在，直与扶桑水到枯。"]},{"t":"云州龙门镇韩母刘孝节卷","f":"七言律诗","c":["韩家门外立双楹，丹染旌书照路明。","此媪何如陶母传，诸郎具是董生行。","春泉跃鲤饶佳味，晓树啼乌有喜声。","孝节从来贫始见，秦台那用筑怀清。"]},{"t":"真定王节妇习氏","f":"七言律诗","c":["青春忽掩镜鸾悲，大节生全死不辞。","夫目九泉无瞑日，妾身百岁有归时。","天高地厚心如石，女嫁男婚发已丝。","东观只今多直笔，为书青简配桓嫠。"]},{"t":"上京睹陈渭叟寄友书声及鄙人赋以答之 其一","f":"七言律诗","c":["忽忆江南古庄叟，钓竿归去拂珊瑚。","药炉已熄勾庚火，书箧閒抛遁甲符。","欲与陈陶同啖鲊，祇令张翰远思鲈。","不知别后诗多少，刊到云编戊己无。"]},{"t":"上京睹陈渭叟寄友书声及鄙人赋以答之 其二","f":"七言律诗","c":["不见故人今十载，平安喜得上京书。","顾我真吟纥干雀，羡君閒钓富春鱼。","山房夜雨青灯外，紫塞秋风白雁初。","终儗携琴隐湖曲，一官垂老欲何如。"]},{"t":"授钺","f":"七言律诗","c":["天子临轩授钺频，东南何处不红巾。","铁衣远道三军老，白骨中原万鬼新。","烈士精灵虹贯日，仙家谈笑海扬尘。","只将满眼凄凉泪，哭尽平生几故人。"]},{"t":"左丞傅梦臣归老汾曲赋以寿之","f":"七言律诗","c":["六朝名德仰巍巍，未许家园久息机。","霖雨帝方思汝作，衮衣人更望公归。","南山一柱标中土，左辖三星拱太微。","欲向宾筵颂眉寿，寸心遥与白云飞。"]},{"t":"王继学廉使迁南台侍史诗以贺之","f":"七言律诗","c":["天上归来锦作袍，几陪春色醉仙桃。","银河有路惟通鹊，碧海无山不戴鳌。","卿月又临仙掌动，客星偏傍钓台高。","广陵此去金陵近，拟拂尘埃望节旄。"]},{"t":"送西江胡允中之桃温万户府学正","f":"七言律诗","c":["辽水穷边牟盖东，镇人今始识儒宫。","诗书直化三韩远，文轨须令万国同。","隼度塞云秋有雪，鳌翻海浪昼多风。","知君回首神州路，一发青山落照中。"]},{"t":"余伯畴归浙东简郡守王居敬","f":"七言律诗","c":["四明游客住京都，旅舍青灯照影孤。","家信十年黄耳犬，乡心一夜白头乌。","却携长铗辞金水，直挂轻帆到鉴湖。","为问蠡吾王太守，别来安稳有书无。"]},{"t":"寄达兼善经历柯敬仲博士","f":"七言律诗","c":["心怜旅寓各西东，长忆樽前笑语同。","故国鱼龙沧海上，仙家鸡犬白云中。","百年人物无多见，一代文章有至公。","等是不禁惆怅事，鬓丝黄叶共秋风。"]},{"t":"宗人鸣善将还武昌诗以叙别","f":"七言律诗","c":["武昌城中官柳阴，广陵行客动归心。","衣冠南渡悲豪杰，江汉东流变古今。","多病马卿游已倦，能诗杜老律尤深。","洞庭明月如相忆，为写清愁入楚吟。"]},{"t":"次倪元镇张伯雨锡山倡和之什","f":"七言律诗","c":["鹤在青林凤在阿，骚人行处有吟窝。","西风落木秋来早，南国浮云入暮多。","欲赋朱华临邺水，可堪白芷怨湘波。","期君不负湖山约，来听吴侬欸乃歌。"]},{"t":"答谢看云宗师寿帙绮段之赠","f":"七言律诗","c":["自信平生有道缘，频烦白鹤寄瑶笺。","锦分帝子机中织，诗入真人诰内编。","弱水蓬莱三万里，庆云阊阖九重天。","拟抽玉刺从飙御，一到环枢问列仙。"]},{"t":"送涂茂才北游","f":"七言律诗","c":["黄河十月已流冰，暂解行装驻广陵。","逆旅壮怀销北斗，故山归梦入孤灯。","千金燕市方求马，万里天池欲徙鹏。","曾是公卿有知己，孝廉船上觅张凭。"]},{"t":"答韩伯清练溪见寄","f":"七言律诗","c":["久惭簪绂趋文馆，拟问田园归武林。","慷慨谩论当世事，衰迟空负壮年心。","忘机白鸟何妨狎，投老青山不厌深。","闻道练溪春酒熟，期君苕上共登临。"]},{"t":"醉乡","f":"七言律诗","c":["半属华胥半酒泉，封君惟有曲生权。","觥筹席上无多地，风月壶中别有天。","千日梦醒如隔世，四时春尽不知年。","从来此处藏身好，容我神游太古前。"]},{"t":"送曹鉴克明自浙省员外迁湖广","f":"七言律诗","c":["上流形势控荆扬，挝鼓飞帆过武昌。","幕府一时登杰俊，朝廷今日际明良。","南楼词翰题鹦鹉，北斗旌旗下凤凰。","好折楚芳遥寄与，美人秋水远相望。"]},{"t":"越僧无涯号栖云乞赋","f":"七言律诗","c":["上方何处但闻钟，深护林扉翠几重。","卧冷衲衣侵片石，行随锡杖度千峰。","松晴每下安巢鹤，潭暮时留听法龙。","更欲移禅沃洲去，微茫岩洞不曾封。"]},{"t":"怀上饶祝蕃远时为建康学正","f":"七言律诗","c":["圣王端拱致时平，妙选群才属汗青。","一代弥文县日月，万方同轨走雷霆。","敢希太史抽金匮，更待中郎写石经。","出处与君俱有道，不烦猿鹤谢山灵。"]},{"t":"送欧阳逊老从谦之湖阃照磨","f":"七言律诗","c":["白云亲舍在湘东，怀牒归来昼锦同。","宾幕尽趋元帅府，朝班旧引大明宫。","剑横岩客南楼日，瑟罢湘灵北渚风。","何处登临最相忆，江蓠秋碧畹兰红。"]},{"t":"送王季培还扬州兼述所怀","f":"七言律诗","c":["远忆淮南后土祠，君归今已发琼枝。","好寻月下吹箫处，犹及花前把酒时。","锦瑟金钱馀旧伴，乌丝红袖有新诗。","故人相见如相问，老尽当年杜牧之。"]},{"t":"江兖州叔志去思碑","f":"七言律诗","c":["使君有道是民师，惠政长留去后思。","秀麦不专称汉史，甘棠直欲继周诗。","驯桑有雉童俱化，攫肉无乌吏绝欺。","东鲁自今应纸贵，一时争打兖州碑。"]},{"t":"临川留别宜黄乐杞楚材","f":"七言律诗","c":["当年携酒杏花春，同是江西榜上人。","岁晚异乡为客久，夜来归梦到家频。","雁声孤馆迢迢雨，马影斜阳漠漠尘。","怅望与君江海别，几时高谊复相亲。"]},{"t":"寄归学士彦温","f":"七言律诗","c":["老笔文章史汉间，喜闻华发映朱颜。","司空旧隐王官谷，开府今称庾子山。","一色黄茅丹灶火，十年清梦紫宸班。","与君岁晚须相见，久办归思疏乞还。"]},{"t":"寄韩文玙与玉","f":"七言律诗","c":["自惊六十八年身，老病蹉跎又见春。","京国岁寒稀雨雪，江淮兵久尚风尘。","乡书屡绝亲知远，官俸常空仆马贫。","只忆练溪韩与玉，封书寄与重伤神。"]},{"t":"春闱和周伯温韵呈同院","f":"七言律诗","c":["鼓角声中漏未终，衣寒官烛屡销红。","百年海岳回元气，一代文章有古风。","仙掌露漙金沆瀣，觚棱雪散玉玲珑。","祗惭白首河汾客，得与群贤此会同。"]},{"t":"正月九日夜雪甚寒","f":"七言律诗","c":["雪后西山照眼青，早寒微霰又飘零。","昨非未必今皆是，众醉何由我独醒。","学篆每朝临《碧落》，存神长夜养《黄庭》。","若为唤得瀛台侣，相与吹箫上杳冥。"]},{"t":"长至后一日小集张氏小轩留题","f":"七言律诗","c":["金殿当头是广寒，阑干高倚五云端。","山衔落照虹光阔，海蹙长冰玉气乾。","仙客上升惟控鲤，月娥来舞每乘鸾。","更须载酒春晴日，万里风烟快一看。"]},{"t":"十月望夜食既","f":"七言律诗","c":["翳翳冰轮渐欲无，满城钟鼓竞喧呼。","明销鱼脑浑应减，食尽蟆肠正可刳。","后羿药灵知不死，臣仝心切望全苏。","夜阑失喜清光满，一片霜风冻玉壶。"]},{"t":"阙题","f":"七言律诗","c":["席上屠苏岁岁同，只怜最后饮衰翁。","半生客路江湖里，十月春愁雨雪中。","黄道云消晴见斗，青阳气转晓占风。","欲题采帖无佳句，思绕蓬莱最上宫。"]},{"t":"寄郯九成即事自述","f":"七言律诗","c":["竖儒无术善飞钤，镜里形容亦自嫌。","忧世不堪才力弱，告归方畏简书严。","风沙惨淡寒吹帽，星斗光芒夜近帘。","此际思君倍愁绝，何山容得老夫潜。"]},{"t":"寄成居竹","f":"七言律诗","c":["战骨填沟尘满城，尚书归说使人惊。","方期渤海民沾化，岂意平凉贼畔盟。","何日皇天知悔祸，中原故老望休兵。","伤心扬子洲边月，忍听江流是哭声。"]},{"t":"高沙失守哭知府李齐公平","f":"七言律诗","c":["高邮自昔号铜城，一旦东平委贼兵。","杀气仓皇迷野色，怨魂呜咽泣江声。","广陵琼树春仍在，甓社珠光夜不明。","白首故人悲赵李，临风唯有泪纵横。"]},{"t":"潼关失守哭参政舒噜杰存道","f":"七言律诗","c":["十月三日天地昏，将军扼贼死辕门。","火飞华岳三关破，血浸秦川万马奔。","望越伍胥方抉目，战箕先轸不归元。","北风吹尽英雄泪，倚剑悲歌一怆魂。"]},{"t":"寄答翟彬文中时避慈溪 其一","f":"七言律诗","c":["往年使过慈湖上，风景依稀可画传。","红叶树藏秋水寺，白头僧渡夕阳船。","竹林雨过山多笋，渔浦潮来海有鲜。","藉是县公能爱客，不妨酬倡酒樽前。"]},{"t":"寄答翟彬文中时避慈溪 其二","f":"七言律诗","c":["静对孤灯思往事，偶闻疏雨落寒窗。","愁边白发三千丈，梦里青山十四双。","蜀魄有声疑诉国，楚招无些忆沈江。","只因诗思缘君苦，吟断遥钟已晓撞。"]},{"t":"食粥","f":"七言律诗","c":["病齿入冬便食粥，瓦瓶煮豆给晨庖。","邻人新酒赊来醉，道士奇方借得抄。","雁喜随阳还北乡，鹊知避岁已南巢。","故园我亦无归计，且作斋居盖白茅。"]},{"t":"题冯士启士可藏书堂","f":"七言律诗","c":["不惜黄金为买书，要令弦诵被乡闾。","圣贤事业千年上，经史文章万卷馀。","借送讵论鸱有酒，收藏长爱蠹无鱼。","他时许下成精舍，岳麓匡山恐未如。"]},{"t":"分韵瓜步送司执中之江西宪府照磨","f":"七言律诗","c":["山前古驿草萧萧，候吏沙头候画桡。","采石晚风人渡急，历城烟树鸟飞遥。","时平烽火沈江戍，市早鱼盐散浦桥。","目送征帆慢相忆，祇将离恨寄回潮。"]},{"t":"分题投书浦送沙彦文架阁之江西","f":"七言律诗","c":["高人岂作置书邮，尽弃函封向石头。","故迹不随烟草没，遗风长与大江流。","悲台鹰下川云暮，别国龙回岳雨秋。","君过渚傍须舣棹，题诗相寄莫沈浮。"]},{"t":"分题若邪溪送别胡一中允文录事之绍兴","f":"七言律诗","c":["五云溪水碧萦湾，纯浸蓬莱郡里山。","金跃冶垆龙已化，箭空仙的鹤长閒。","棹歌洲渚芙蓉外，人在楼台罨画间。","吟赏总输贤录事，樵风日暮送舟还。"]},{"t":"寄题睢阳张文照存斋","f":"七言律诗","c":["之子山房结数楹，静无尘累已撄宁。","此心炯炯同千载，吾道煌煌有六经。","雨后仪型山更好，窗前意思草长青。","工夫要在存存熟，便是斋居座右铭。"]},{"t":"题四皓商山图","f":"七言律诗","c":["兵尘澒洞绕函关，不到商于六里间。","赤帜频传秦楚蹶，白云自与绮园閒。","龙蛇陆起知何在，鸿鹄冥飞竟不还。","千载高风无复见，空馀芝草满空山。"]},{"t":"玉山墨工魏元德名一时赠之以诗","f":"七言律诗","c":["魏郎应得庭圭法，未数松泉与雪堂。","万杵熟胶香入剂，一螺点漆黑生光。","抡材合致图书府，留价争倾翰墨埸。","我有诗囊须剩袭，草玄归去老山房。"]},{"t":"山友为金阁山田道士作","f":"七言律诗","c":["山人爱与山为友，住得山前地几双。","为纳白云长扫室，欲延青嶂别开窗。","岚中筇迹粘苔磴，风外琴声泻石缸。","应是烟霞数仙侣，月明时复下旌幢。"]},{"t":"望江","f":"七言律诗","c":["寒潮已退大江空，不见来鸥与去鸿。","半岭綵霞缠落日，一川红树照西风。","鲁连蹈海英灵远，王粲登楼感慨同。","径欲投竿会稽石，得鱼为饱浙河东。"]},{"t":"岁晏奇寒","f":"曲","c":["痴坐?毹类冻蝇，霜风吹折布衣棱。","炉翻宿火随灰陷，杯覆燖汤到地凝。","虎豹冻埋山尽雪，鱼龙寒宿水连冰。","浊醪最解强人意，吟短西窗一寸灯。"]},{"t":"寄答莫维贤景行","f":"七言律诗","c":["故人音问久相疏，忽寄新诗良起予。","半卷长笺欹枕读，尽拈佳句绕窗书。","此生馆阁嗟留滞，何日兵戈见扫除。","归觅南屏山下隐，酒杯茶灶共閒居。"]},{"t":"答马易之编修病中作","f":"七言律诗","c":["喜君近疾已平安，楮帐绵衾且避寒。","饭颗任嘲诗骨瘦，糟丘能遣客怀宽。","天街钟动朝初罢，海国书回岁又残。","忽讶衰翁不相问，北风吹雪正漫漫。"]},{"t":"寄成居竹黄舜臣 其一","f":"七言律诗","c":["岁月峥嵘春又来，归心遥在故园梅。","十年厌见风尘恶，万事徒增耳目哀。","大漠平铺沙雪去，远山直枕海云开。","近怀欲报成夫子，强起题诗对酒杯。"]},{"t":"寄成居竹黄舜臣 其二","f":"七言律诗","c":["一见君诗倍黯然，蓟南湖北各风烟。","故人渐似星将晓，尘世真成海变田。","桂在谩吟招隐曲，鹤归还记去家年。","虎丘山水知无恙，有待先期置酒泉。"]},{"t":"至日微雪家人尽上冢独步小酌","f":"七言律诗","c":["忽忽又逢长至日，此心寒似琯中灰。","寻思一日老一日，得饮数杯还数杯。","鹊知太岁改巢去，雨被北风吹雪来。","醢兔羞鴽良不恶，馂馀聊遣冻颜开。"]},{"t":"送布延彦仁都事还蜀兼东时文可郎中","f":"七言律诗","c":["送君一骑发长安，王事方殷肯避难。","使者好寻巴道路，诗人多勒蜀岩峦。","江来灌口声初放，云接峨嵋翠不乾。","为报郎中勉勋业，远音时遣破幽端。"]},{"t":"题栝士朱矩方画五松","f":"七言律诗","c":["隐君业在栝溪东，种就长松倚翠空。","一夕蛟龙起春雨，满山鳞甲动天风。","也知造物生来异，未许烟霞画得同。","想见青田旧巢鹤，时时来唳白云中。"]},{"t":"吾庐","f":"七言律诗","c":["吾庐幽似野人家，时倚南轩玩物华。","亦有君臣槐腹蚁，也能鼓吹沼中蛙。","邻翁来送新篘酒，堂吏求抄旧草麻。","早晚乞骸寻旧隐，不妨高卧傲烟霞。"]},{"t":"歙汪希仲罕代自雄新二州还都话其风土为赋","f":"七言律诗","c":["越鸟巢南涨海东，地兼夷夏气惟雄。","洞深屋垒层厓上，泷险船行乱石中。","春树湿云生桂蠹，瘴茅经雨落沙虫。","宦游最数蛮荒恶，羡子归来面更红。"]},{"t":"病起偶题","f":"七言律诗","c":["阅世悠悠八十馀，此身天地一蘧庐。","季鹰只爱生前酒，司马空留后世书。","野散未归鸣泽雁，水烦徒噞在渊鱼。","可堪濩落风尘里，两鬓霜毛顿觉疏。"]},{"t":"饮故相国宅","f":"七言律诗","c":["相君池馆旧撝诃，今日还容野老过。","裂地商于真已矣，积金郿坞竟如何。","胡僧漫演寅朝偈，女鬼空悲子夜歌。","起向春风酹杯酒，青芜满地雨红多。"]},{"t":"监中暮归","f":"七言律诗","c":["扶桑铜柱若为标，南望兵氛久未销。","秋水涨河初放鳄，晚烟笼树尽鸣枭。","枕戈未睹栖于越，舞羽曾闻格有苗。","河北诸侯总戎翰，好宣忠力佐皇朝。"]},{"t":"次韵闽僧秀嵓寄竹溪僧 其一","f":"七言律诗","c":["峰北峰南法界中，杖藜来往夕阳钟。","时过花洞逢游鹿，夜咒珠台放钓龙。","七字诗才清似水，三生骨相古于松。","羡师方外全无事，只个蒲团又过冬。"]},{"t":"次韵闽僧秀嵓寄竹溪僧 其二","f":"七言律诗","c":["望入南云无去鸿，凭谁持饷一瓶空。","诗来万里燕台下，寺在三山冶县东。","戏瓦空中惟见水，挂幡窗外自摇风。","我今也拟辞簪绂，去作岩居三老翁。"]},{"t":"送监生聂让省兄山后","f":"七言律诗","c":["书剑翩翩送子归，原头相见脊令飞。","北风关路雪云暗，落日客亭烟火微。","血立忠臣头上发，线留慈母手中衣。","老夫唯有销兵望，早遣平安到虎闱。"]},{"t":"东坡淮口墨迹卷后有黄策诗","f":"七言律诗","c":["潮落潮生沙岸头，布帆来往几经秋。","山川如故人何在，天地无情水自流。","败垒荒墟非昔画，野烟寒照总新愁。","只应千古清淮月，曾照东坡此唤舟。"]},{"t":"寿许集贤可用 其一","f":"七言律诗","c":["圭塘谕德真寿星，斑衣戏舞满中庭。","同年笑我雌为甲，上寿看君老复丁。","壶有仙公新授药，厨留长史旧传经。","他时若许相依住，愿割西山一半青。"]},{"t":"寿许集贤可用 其二","f":"七言律诗","c":["看君才气夐无双，往往宾贤镇海邦。","未报美人青玉案，且乘壮士碧油幢。","唤船椰叶迷蛮驿，对酒椒花映客窗。","别后平安须越便，雁飞不过岭头泷。"]},{"t":"送贵溪彭伯时教授之高州蒙古学","f":"七言律诗","c":["都门柳色绿纷纷，惆怅南园此送君。","䫈海驿程须给传，国朝字学要同文。","鼓来野庙迷蛮鬼，火燎山田落瘴云。","藉有槟榔与藤酒，冷官聊复送朝曛。"]},{"t":"乐平刘复初隐居四咏 其一 耕田","f":"七言律诗","c":["东皋南亩雨新晴，杏花欲开菖叶生。","田妇蒸藜来午饷，邻翁荷锸趁春耕。","乌犍引犊村村出，布谷催人处处鸣。","归与儿孙共閒夜，一窗灯火读书声。"]},{"t":"乐平刘复初隐居四咏 其二 听泉","f":"七言律诗","c":["泱泱寒流底处寻，但传幽响出空林。","石根云窦元多罅，松籁风簧共一音。","醉梦䀨醒春枕熟，诗怀清彻夜窗深。","中郎别有清溪曲，更写潺湲入素琴。"]},{"t":"乐平刘复初隐居四咏 其三 饮酒","f":"七言律诗","c":["酿法传将道士家，春醪一味采松花。","常时野坐开新瓮，几度山行载后车。","忤客有谁焚醉日，学仙何处饮流霞。","明朝又觅南邻伴，还汲清泉洗石洼。"]},{"t":"乐平刘复初隐居四咏 其四 观鱼","f":"七言律诗","c":["漾漾清波浮紫鳞，一筇閒倚树边身。","我疑濠上漆园老，谁识江头渔丈人。","细草留连还可藉，野鸥来往自相亲。","此中正得悠然乐，何用扁舟把钓纶。"]},{"t":"成居竹有诗见寄因郯九成行用韵答之","f":"七言律诗","c":["归隐山林叹未能，强支世故力难胜。","少狂欲作追风骠，老退还如被冻蝇。","客赋有愁逾万斛，兵厨无酒可三升。","与君为结东家社，珍重衰年护寝兴。"]},{"t":"送燕山杨文周之汾州教授","f":"七言律诗","c":["关河迢递入汾阳，暑雨初收陌树苍。","名士多为文学掾，此州今有状元坊。","雁来霜塞秋声急，鸟去烟台野色荒。","试问西河读书处，因君石室重辉光。"]},{"t":"送草窗讲师周善京还九江太平宫","f":"七言律诗","c":["万叠匡庐紫翠开，太平宫馆即琼台。","九天使者云间下，五柳先生社里来。","杏树春阴浑满院，桂花凉露不盈杯。","遥应鹤侣相望久，吹取楼头铁笛回。"]},{"t":"许编修克敬归平水奉寄王秘监先辈","f":"七言律诗","c":["忆昔先生致政时，至今留在十图诗。","古来贤达知几早，此日山林问舍迟。","故国衣冠多草莽，中原郡县半旌旗。","白云汾水秋风外，目送归鸿有所思。"]},{"t":"九日燕允孚森玉轩醉中感怀","f":"七言律诗","c":["不见江南信使来，菊花应傍战场开。","风尘渺渺家难问，节物匆匆老转催。","把酒多无今日醉，登高只益寸心哀。","白头一觉湖山梦，谁料繁华有劫灰。"]},{"t":"会试院泰甫兵部既答和拙作且示以佳章仆以汨于校文遂稽貂续仍韵见趣所考既就格辄缀四首录奉一笑 其一","f":"七言律诗","c":["堆床朱卷考初分，卫士传呼夜锁门。","覂驾已多东野马，抟扶应有北溟鲲。","熟衣乍换寒犹薄，倦枕才凭睡易昏。","愿向斯文求俊乂，大廷行对帝王尊。"]},{"t":"会试院泰甫兵部既答和拙作且示以佳章仆以汨于校文遂稽貂续仍韵见趣所考既就格辄缀四首录奉一笑 其二","f":"七言律诗","c":["楼头叠鼓已三严，起听秋声满四檐。","山叶落频风绕树，露蛩吟苦月当帘。","烟寒铜兽催香换，漏促金壶报箭添。","笑我原无食肉相，只思莼鲙荐吴盐。"]},{"t":"会试院泰甫兵部既答和拙作且示以佳章仆以汨于校文遂稽貂续仍韵见趣所考既就格辄缀四首录奉一笑 其三","f":"七言律诗","c":["勌眼空花漫不分，偶随群彦集金门。","扁舟只拟追张翰，一壑还期置谢鲲。","枫叶旧诗多冷落，梅花归梦几黄昏。","与君此去如休暇，莫厌相过共酒樽。"]},{"t":"会试院泰甫兵部既答和拙作且示以佳章仆以汨于校文遂稽貂续仍韵见趣所考既就格辄缀四首录奉一笑 其四","f":"七言律诗","c":["诗律输君敢斗严，强摩老眼傍风檐。","鹄袍夜散遥持烛，席舍朝开尽撤帘。","久悟物机忘出入，时存神火验抽添。","明当唤取弹筝手，与唱新声阿鹊盐。"]},{"t":"故御史王楚鳌元戴为临川王伯达三画求题 其一","f":"七言律诗","c":["双凤山人茅作屋，五云阁吏绣为衣。","写将潇洒沧洲趣，留待风流二老归。","岁月无情遗墨在，江湖多事宿心违。","寒藤古木江西道，惟有当年白雁飞。"]},{"t":"故御史王楚鳌元戴为临川王伯达三画求题 其二","f":"七言律诗","c":["罨画溪头春水波，美人兰棹远来过。","杯如贺老稽山酒，曲有吴儿小海歌。","楼馆云晴空翠湿，汀洲花暗夕阳多。","只今粉墨馀高致，愁绝樵风冷薜萝。"]},{"t":"故御史王楚鳌元戴为临川王伯达三画求题 其三","f":"七言律诗","c":["小吏堞前烟水空，淮山无数直丛丛。","使君援笔写秋色，舟子唱桡乘晚风。","几处渔家依落木，半汀残照下飞鸿。","白云望断仙游远，应在蓬莱碧海中。"]},{"t":"雪中梁师孟叔原饷浑酒小饮閒窗偶成一章","f":"七言律诗","c":["岁事萧条雪拥门，家人随分具盘飧。","灶头饼软团团白，缸面醅新盎盎浑。","万窍风声皆地籁，一窝春意自天根。","老夫只待干戈息，归问西湖水竹村。"]},{"t":"送契元鲁降香南岳南海","f":"七言律诗","c":["天开朱岳奠炎方，地入南溟接大荒。","使者肃修时典礼，神明宜护国封疆。","仙台云散峰峦碧，瘴岭春回草木香。","珍重词臣致诚祷，愿消昏疠降休祥。"]},{"t":"送景初漕史还平江各赋一诗寄吴下诸友 其一","f":"七言律诗","c":["怒浪蹙天摧漕舟，疾风吹雨黑中流。","海神跃马火明灭，龙伯钓鳌山荡浮。","安得灵槎通汉使，断无奇药采瀛洲。","丈夫政事经艰险，不负平生亦壮游。"]},{"t":"送景初漕史还平江各赋一诗寄吴下诸友 其二","f":"七言律诗","c":["我忆栝山老徵士，卷雾飞谈那可当。","高致何如漆园吏，幽居真是郑公乡。","未能即去楚氛恶，每一相思云树长。","欲觅双鱼问消息，越来溪远水茫茫。"]},{"t":"送景初漕史还平江各赋一诗寄吴下诸友 其三","f":"七言律诗","c":["匡山道士躯干小，豪气直压香炉峰。","池边咒剑出金虎，峡顶放船飞白龙。","老我每推诗俊逸，何时相见话从容。","散仙万一烟尘外，为报巢云若个松。"]},{"t":"送景初漕史还平江各赋一诗寄吴下诸友 其四","f":"七言律诗","c":["近报昆冈亦被兵，知君抚剑气峥嵘。","夫差强弩风生海，姑蔑战旗云绕城。","天诏屡传宽宥下，王师行见扫除平。","草堂无恙玉山好，我欲南辕寻旧盟。"]},{"t":"汶上早行图上清张道士写","f":"七言律诗","c":["绛节前驱海日生，川回已见汶阳城。","数峰晓翠和烟湿，千树春红照地明。","原隰使华来焕烂，河山风物入经营。","凭君更写千岩月，与听鸾笙夜夜声。"]},{"t":"白鹰","f":"七言律诗","c":["爱此精神顾盼雄，扶舆遥隔海涛东。","俊含金气翎如雪，直上秋云骨有风。","绦镞五方禽献后，锦貂千骑猎围中。","平原侧目多狐兔，安得真拳一击空。"]},{"t":"九月二日揭晓仆以朔旦始得閒复成二诗录奉泰甫侍郎思齐御史本中都事道明敏文伯崇有志诸寮友 其一","f":"七言律诗","c":["解送诸君藻鉴分，棘围明发喜开门。","荆人自许山多玉，庄叟虚谈海有鲲。","过雁风高秋索索，护霜云薄晓昏昏。","乡来曾预春闱考，犹记君王赐上尊。"]},{"t":"九月二日揭晓仆以朔旦始得閒复成二诗录奉泰甫侍郎思齐御史本中都事道明敏文伯崇有志诸寮友 其二","f":"七言律诗","c":["西风渐急早寒严，晓露俄晞日在檐。","满鼎松声烹活火，半钩花影捲疏帘。","菊黄又报秋期近，发白空惊老态添。","未得山中觅茅屋，去修丹灶养红盐。"]},{"t":"庚子元日早朝大明殿小饮自述","f":"七言律诗","c":["玉殿齐班对正衙，退朝冠盖满京华。","青天彻晓无云气，黄道回春转日车。","閒染彩毫题帖子，喜将绿酒泛椒花。","老身只待承平了，携取来书问故家。"]},{"t":"仙兴","f":"七言律诗","c":["鶱林树树玉成围，皓鹤彩鸾中自飞。","玄石山人千日酒，上清仙子六铢衣。","道心不动方归朴，物化无方总入机。","自炷芜香明月夜，露坛东向礼灵威。"]},{"t":"自悼 其一","f":"七言律诗","c":["十二楼空月自明，一圆一缺总关情。","每从画里瞻琼在，复向诗中记受生。","魂不归来悲楚些，梦还惊觉厌秋声。","遥知别鹤离鸾思，只在芙蓉海上城。"]},{"t":"自悼 其二","f":"七言律诗","c":["梦中常苦不分明，天上人间各有情。","桃叶竹枝无限意，灵芝瑞草可怜生。","若兰谩织回文字，鹦鹉犹传响板声。","欲得近音何处问，风烟遮断武林城。"]},{"t":"病中","f":"七言律诗","c":["小儿舞袖学斋郎，大女笑看傍鼓簧。","狂客有时来猎酒，老夫无事坐焚香。","前家后家杂歌哭，南斗北斗相低昂。","病卧经旬不出户，墙角青青春荠长。"]},{"t":"遣兴","f":"七言律诗","c":["七十蜕翁衰病馀，一室俨若维摩居。","孔方无神可使鬼，毛颖已秃不中书。","江湖天远道涂断，鼓柝冲寒风雪初。","糠籺明年恐未饱，欲求何地托吾庐。"]},{"t":"至后暴日","f":"七言律诗","c":["火煖毡床拥病翁，遣怀篇翰底求工。","悲歌学士徒能壮，学坐禅僧要自空。","鹖旦犹鸣天有雪，爰居已去海无风。","只留一段思乡意，不见诗中见梦中。"]},{"t":"悼亡日","f":"七言律诗","c":["剪水裁云聚作花，直教颜色冠芳华。","一双仙子玉条脱，三尺天家香辟邪。","南国好音将过雁，西窗残梦已啼鸦。","年年此日伤春思，忍把归心赋落霞。"]},{"t":"九日书似北山上人","f":"七言律诗","c":["老年尤惜过芳时，篱下黄花值闰迟。","夜雨有愁如湿絮，秋风无发可吹丝。","劳魂数数还乡梦，往事茫茫感兴诗。","满腹精神浑减尽，一杯谁与共襟期。"]},{"t":"中秋望亭驿对月代祀北还","f":"七言律诗","c":["月色沧波共渺茫，驿亭杂坐看湖光。","仙家刻玉青蟾兔，帝子吹笙白凤凰。","芦叶好风生晚思，桂花清露湿空凉。","回槎使者秋怀阔，倒泻银河入酒觞。"]},{"t":"春日小轩独坐","f":"七言律诗","c":["江南棕笋正时新，滋味还思养病身。","暮雨过云初有电，老莺啼树已无春。","虚名晚合徒多累，同辈生存仅数人。","净扫虚轩炷香坐，只将篇什拟心神。"]},{"t":"清明日杏园独坐","f":"七言律诗","c":["底事东风大放颠，为花浑废夜深眠。","赏心不有闰三月，老眼应虚春一年。","歌舞尽传天上曲，笑谈同是酒中仙。","归时更爱东城道，月在秋千影外圆。"]},{"t":"长至日偕诸友游故宫","f":"七言律诗","c":["皇天有数混南邦，组练长驱万里江。","内井龙沈军檄在，西郊鬼泣帝车降。","河开故道穿宫籞，殿锁秋尘暗佛幢。","欲问兴亡遗老尽，晚风铃语自摐摐。"]},{"t":"中秋雨明日晴明玩月有作","f":"七言律诗","c":["今夕清光不负公，更无云气碍虚空。","晴迟一日秋才望，看到三更月正中。","蟾兔影寒天下露，鱼龙魄动海生风。","故人别有蕉杯约，未放扁舟一鹤东。"]},{"t":"雪中早朝","f":"七言律诗","c":["北风吹雪浩漫漫，晓出津桥立马看。","春入上林花树早，水连平地海波乾。","金城万雉微茫湿，月阙双龙赑屃寒。","今日天颜知有喜，紫宸朝下散千官。"]},{"t":"过李陵台","f":"七言律诗","c":["路出桓州山缦回，仆夫指是李陵台。","树遮望眼仍相吊，云结乡愁尚未开。","海上羝羊秋牧罢，陵头石马夜嘶哀。","英雄不死非无意，空遣归魂故国来。"]},{"t":"喜雪简社友","f":"七言律诗","c":["今朝腊日初飞雪，一白先期报岁丰。","坐见洪荒还太古，信知造化自虚空。","诗情画意天机外，和气欢声帝力中。","便欲访君僧舍去，冻泥晴滴阻西东。"]},{"t":"清明日大风雨","f":"七言律诗","c":["阴霾连日恶风生，老去愁多骨亦惊。","天色昏昏转黄浊，春光冉冉又清明。","邻家醁酒初开瓮，游女香车不出城。","须为杏花赊一醉，谁家园里有莺声。"]},{"t":"西兴渡","f":"七言律诗","c":["携家迢递过西陵，江雾微消海日升。","帆影昼惊沙上雁，船声斗落岸头冰。","果园霜后初分橘，渔浦潮平各下罾。","岁晚不思行路倦，剡中佳兴正堪乘。"]},{"t":"送春答何高士","f":"七言律诗","c":["湖山不见暮云浑，杨柳风寒早闭门。","情在旧游花历历，酒淹残睡雨昏昏。","种桃道士今何处，采芍骚人不返魂。","欲识伤春无限意，杜鹃枝上有啼痕。"]},{"t":"夕次杨村","f":"七言律诗","c":["烟中帆影落舸峨，系缆沙边已夜过。","风骤数声来海树，月移半晕入天河。","得归始觉形神王，望远空留感慨多。","坐听舟人语明发，芦花秋水正增波。"]},{"t":"清明雨晴游包山龙华寺过慈云岭","f":"七言律诗","c":["当年玉辇此经行，古寺犹题扈从名。","龙凤谶空山气歇，马羊劫换海波平。","野桃著雨春红落，岭路埋云湿翠生。","日暮人归烟树黑，饥鼯啼雨上宫城。"]},{"t":"雷火焚故宫白塔","f":"七言律诗","c":["声声起蛰乍闻雷，骤落千山白雨来。","恐有怪龙遭电取，未应佛塔被魔灾。","人传妖鸟生讹火，谁觅胡僧话劫灰。","岂复神灵有遗恨，冷烟残烬满荒台。"]},{"t":"中秋乐陵驿玩月","f":"七言律诗","c":["西风吹尽马蹄尘，凉夜中庭暂解巾。","华月团团生兔腹，黑云片片散鱼鳞。","鬓毛老去如黄叶，诗思秋来满白蘋。","乐饮与君须达曙，举杯相属恰三人。"]},{"t":"家居九日","f":"七言律诗","c":["病馀瘦骨不胜秋，早起惊寒已索裘。","安得酒酬佳节醉，从教花为老人羞。","螟蛉有子宁嫌祝，蛱蝶无知底用愁。","却笑江湖旧诗客，凄凉犹忆少年游。"]},{"t":"喜雪答鹤斋薛逸人","f":"七言律诗","c":["晓雪初飞应岁华，因风吹起整还斜。","石田不种皆成玉，瑶界非时自雨花。","道士拥炉衣类鹤，麻姑送酒髻如鸦。","悬知此际神游处，只在蓬莱海上家。"]},{"t":"七月二十七日书所见","f":"七言律诗","c":["杏花树底血犹红，一宿星痕雨洗空。","凤阙追班听帝诏，羽林坐甲卫皇宫。","天官占候徵玄象，国士精诚贯白虹。","引领云间望笙鹤，朝来佳气已葱葱。"]},{"t":"辱井栏","f":"七言律诗","c":["好事能收断石存，摩挲堪忆古云根。","楼空野燹钟何在，宫没寒芜井已眢。","古篆半留栏上字，妖姬犹有墓中魂。","试扪凹处殷红湿，不是胭脂是血痕。"]},{"t":"十一月六日大明殿贺清祀礼成","f":"七言律诗","c":["大明宫殿彩云间，花底微风响佩环。","陛戟九重周虎士，御筵咫尺望龙颜。","犬牙磐石诸侯国，豹尾钩陈百辟班。","漏下五门朝退晚，日边佳气满西山。"]},{"t":"存道元帅师宗感时及陡溯山俟刀寨入贡次韵二诗送归关戍 其一","f":"七言律诗","c":["徼外频传羽檄飞，将军三起著戎衣。","空山狐兔无藏窟，平陆龙蛇有杀机。","已见赵佗知汉德，更令孟获识天威。","此行整顿蛮荒了，箐雨泸烟好赋归。"]},{"t":"存道元帅师宗感时及陡溯山俟刀寨入贡次韵二诗送归关戍 其二","f":"七言律诗","c":["群蛮连岁閧滇中，陡溯山前喜挂弓。","万里筹边频却虏，半生忧国早成翁。","塞垣烽火方无警，幕府文书已上功。","奏赋归来五云阁，汉庭不独数严终。"]},{"t":"送谟侍者还江阴","f":"七言律诗","c":["禅裓无尘锡杖青，一龛天竺更南屏。","杨枝遍洒瓶中水，贝叶时翻笈内经。","旧业池菱秋漠漠，归舟江树晓冥冥。","今朝又作芜城别，何处钟声入夜听。"]},{"t":"寄陈敬初郯九成","f":"七言律诗","c":["忆昨阊门绾柳条，远烦相送过枫桥。","夕阳陌上东西路，春水江头早晚潮。","老境此心惟白社，英年何处不青霄。","诗林别后应俱进，时遣邮筒慰寂寥。"]},{"t":"寄俊上人","f":"七言律诗","c":["不见俊公今十年，武林留偈竟茫然。","苕溪寺已空尘劫，蒲室灯还有别传。","晒衲石根随夕照，题诗竹里湿秋烟。","何时近一牛鸣地，老去山中伴夜禅。"]},{"t":"寄智及上人","f":"七言律诗","c":["故人远在越江南，何日相寻过海帆。","少借禅房一十笏，全翻经藏五千函。","寒炉拨火宜煨芋，夜月裁诗定倚杉。","儗结愿香归未得，碧莲花老补陀岩。"]},{"t":"寄见心上人次韵 其一","f":"七言律诗","c":["自入赤墀青琐间，旧游禅侣亦阑珊。","青山只忆招提境，白首初辞供奉班。","马为空群犹蹻蹻，鸟能求友自关关。","终期一舸相寻去，知在姚溪第几湾。"]},{"t":"寄见心上人次韵 其二","f":"七言律诗","c":["见说钱塘别筑城，凄凉风景若为情。","湖堤柳尽曾游路，石壁苔荒旧刻名。","老我无能如烛武，何人可饮胜公荣。","沃洲胜会还容续，即拟山中隐计成。"]},{"t":"怀翟文中","f":"七言律诗","c":["君留越甸长怀我，我在京华几梦君。","佳句每从愁里得，远书忽向病中闻。","船来海口人争岸，兵满淮南火照云。","今日临风倍凄断，白头清泪共纷纷。"]},{"t":"江山览胜楼","f":"七言律诗","c":["白云东南相荡浮，中有隐者之飞楼。","千峰影落华盖晚，一水寒通彭蠡秋。","鲛人机杼或闻响，山鬼窟宅疑藏幽。","为问仙家借黄鹄，我欲题诗来上头。"]},{"t":"寄别陈渭叟","f":"七言律诗","c":["空山花发春事幽，道人结屋居上头。","胡麻随水有时得，杏子成林谁敢偷。","金银气杂丹光现，涧壑响带松声流。","寄语黄鹤一相别，独立苍茫歌远游。"]},{"t":"游天竺寺 其一","f":"七言律诗","c":["石梁溅水湿苍苔，阴洞傍穿涧底回。","殿阁金银从地涌，山林图画自天开。","龙随僧到分云住，猿任人呼下树来。","游兴未阑斜日尽，马头呼酒尚徘徊。"]},{"t":"游天竺寺 其二","f":"七言律诗","c":["西湖之西天竺深，天香满风多桂林。","老猿引子下高树，流水与云来远岑。","上方已变劫灰黑，古涧长带秋岚阴。","清辉娱人且归去，后夜明月来重寻。"]},{"t":"通玄观","f":"七言律诗","c":["羽盖翩翩下九重，江乡秋晚滞仙踪。","信传真府凭青鸟，剑舞瑶台走碧龙。","顷刻风云兴五岳，须臾雨泽慰三农。","殷勤欲问参同契，双舄遄飞未易从。"]},{"t":"题张外史马塍新居","f":"七言律诗","c":["窈窕丹房古涧阿，长松脩竹绕层坡。","桃园隐者时相遇，茅洞仙人夜或过。","沆瀣杯寒供晓食，青冥笙响答空歌。","白云浮出池痕满，知是龙泓宿雨多。"]},{"t":"登六和塔","f":"七言律诗","c":["江上浮屠快一登，望中烟岸是西兴。","日生沧海横流外，人立青冥最上层。","潮落远沙群下雁，树欹高壁独巢鹰。","百年等事豪华尽，怕听兴亡懒问僧。"]},{"t":"上清薛茂弘虞内翰以鹤斋号之为赋","f":"七言律诗","c":["羽人新得虞翁号，归筑衡茅并翠微。","丹室有风鸣夜帐，斗坛多露湿秋衣。","画中昨者薛少保，华表当年丁令威。","直拟身形鍊相似，玉笙吹上白云飞。"]},{"t":"登金山吞海亭了公请赋","f":"七言律诗","c":["危亭突兀戴鳌头，俯视沧溟一勺浮。","龙伯衣冠藏下府，梵王台殿起中流。","扶桑夜色三山日，滟滪江声万里秋。","老我惜无吞海句，但磨崖石记曾游。"]},{"t":"寄成居竹隐居","f":"七言律诗","c":["青袍朝士困京华，此老萧閒竹满家。","山压穷愁诗强项，海枯渴肺酒槎牙。","商岩未采芝如草，彭泽将归菊有花。","孤负江头理渔事，短篷春雨梦沤沙。"]},{"t":"题唐子华画王师鲁尚书石田山房","f":"七言律诗","c":["秋水桥边红叶林，数家茅屋傍青岑。","冈头种玉朝烟煖，陇上锄云宿雨深。","摩诘辋川宜入画，少陵韦曲自成吟。","束薪岁晚来同煮，应许山中道士寻。"]},{"t":"赋中书左曹小瀛洲","f":"七言律诗","c":["东曹地迥集名郎，宛是仙家紫翠房。","阊阖上通天咫尺，蓬莱移出海中央。","金波日暖浮鳷鹊，玉树春浓下凤凰。","几度梦回清夜直，此身如在五云乡。"]},{"t":"三月望日游虎丘寺题小吴轩","f":"七言律诗","c":["海涌峰前云树盘，佛宫飞阁出巑岏。","虎来古冢金精白，龙卧秋池剑影寒。","禅老说空留坏石，鬼仙题雨下虚坛。","凭高不尽登临兴，更借西山晚翠看。"]},{"t":"题舒噜存道元帅平师宗三州卷后","f":"七言律诗","c":["不用牙璋远出师，将军凭轼下边陲。","僰酋争歃金盘血，汉使高悬玉帐旗。","司马文章传太史，武侯威略震南夷。","只今父老兰沧上，拟刻宁蛮第一碑。"]},{"t":"送李孟端奉祀天妃祠北归","f":"七言律诗","c":["万里函香出汉廷，楚江南下越山青。","祠光夜现天妃火，骑气秋瞻使者星。","三岛凤麟环碧海，九关虎豹隔青冥。","君才宜掌丝纶美，为述文章袭六经。"]},{"t":"虚斋赠四明王道士","f":"七言律诗","c":["高斋闻在荔枝林，曲几方床宴坐深。","大道无形元寓器，至人于物不容心。","三山云气通寥泬，一室天光入照临。","我欲壶中收药去，石田瑶草共相寻。"]},{"t":"吴江","f":"七言律诗","c":["坐倚风樯看太湖，波涛澒洞半三吴。","寒通上界咸池气，黑入中流水伯都。","云暗蛟龙应起立，雪深鸿雁自惊呼。","望亭有酒宵堪醉，买得渔家一尺鲈。"]},{"t":"寄题杜原父怀友轩","f":"七言律诗","c":["尺五城南近世纷，移家来并武夷君。","他年功业谁青史，此日山林自白云。","石气晓侵书幌湿，溪声时杂棹歌闻。","故人已有同栖约，杖策行穿虎豹群。"]},{"t":"题黄州管氏怀坡堂","f":"七言律诗","c":["玉局仙人云锦裳，骑龙一夕下黄冈。","峨峨冠盖生陈迹，落落江山有耿光。","谪宦六年名益重，怀贤千古意何长。","君侯此举诚佳事，未数儋州载酒堂。"]},{"t":"瓜州与成居竹王克纯登江风山月亭","f":"七言律诗","c":["风起西津断客艘，熊家亭上得凭高。","云移鸟影沈江树，雨带龙腥出海涛。","开辟自天留壮观，登临如我老英豪。","放舟拟就金山宿，一夜清寒袭锦袍。"]},{"t":"奉答新仲铭禅师","f":"七言律诗","c":["吴枫初冷雁连天，梦在江南野水边。","词客欲归嗟老大，美人不嫁惜婵娟。","豺狼正尔当官道，龙象于今护法筵。","我识新公老禅衲，一灯蒲室是真传。"]},{"t":"赠马易之","f":"七言律诗","c":["万里征帆渡越江，兹游奇观世无双。","海中蓬岛金银阙，天上玉堂云雾窗。","吾道政须求柱石，诗坛从此避旌幢。","青林白谷归休地，怀抱因君得暂降。"]},{"t":"冰蟾为金齐贤赋","f":"七言律诗","c":["老蟾素魄禀金精，千岁玻瓈幻结成。","明水夜零阴隧冻，丹书秋满肉芝生。","腹凝寒露藏虚白，影入银河浴太清。","拟问姮娥乞灵药，与君骑向广寒行。"]},{"t":"吴江王氏水云深处","f":"七言律诗","c":["潮平天阔开诗境，宜著幽亭俯碧浔。","閒许钓徒分半席，静饶沙鸟占全林。","青连河汉秋无极，黑入菰蒲晚易阴。","更好扁舟明月夜，醉携长笛写龙吟。"]},{"t":"送式无外归高丽","f":"七言律诗","c":["三韩山水有灵晖，秀出斯人了佛机。","岳寺禅馀留偈别，王城斋罢戴经归。","瓶收沧海降龙入，锡度秋空近鹤飞。","只恐故林云卧后，一镫秋老木棉衣。"]},{"t":"散木轩为陈则虚高士赋","f":"七言律诗","c":["散木轩中一散仙，形虽如槁气苍然。","路松正自为明误，社栎还因不用全。","梁栋无心聊阅世，山林有地可长年。","碧窗日静忘机事，悟得南华第四篇。"]},{"t":"送宋本礼部状元调选还京","f":"七言律诗","c":["圣主求贤礼数崇，策名高步冠南宫。","乘槎析木天津上，奏赋甘泉卤簿中。","染翰墨凝仙掌露，护衣香散御炉风。","只今帝业熙千载，正待儒臣黼黻功。"]},{"t":"春日怀柯敬仲博士","f":"七言律诗","c":["建章莺啭曙光初，上直门开漏点疏。","花拥西清森仗卫，星临东壁焕图书。","汉庭长者多推毂，楚国骚人久卜居。","为问五云仙阁吏，綵毫春咏近何如。"]},{"t":"题张性之提举静学斋","f":"七言律诗","c":["隐者城南水竹居，萧然一室白生虚。","传声吴会名家后，探道农黄邃古初。","日影上帘晴晒药，露凉侵户夜翻书。","元知静里工夫大，欲乞灵方一起予。"]},{"t":"送刘侯赴大理","f":"七言律诗","c":["万里南云入马蹄，蛮酋迎拜过阿黎。","将军拔剑歌玄武，使者乘轺祀碧鸡。","六诏星文开井络，两关鸟道插天梯。","圣朝谋帅先诗礼，努力筹边息鼓鼙。"]},{"t":"送柯敬仲之京","f":"七言律诗","c":["给事先皇禁邸中，归来空抱小臣弓。","鱼龙夜落黄河水，鸿雁秋征白霫风。","郢国善歌推宋玉，汉庭能赋待扬雄。","如君必用才优俊，重见金闺尺籍通。"]},{"t":"题远碧楼","f":"七言律诗","c":["江上楼居景自清，阑干朝暮傍阴晴。","数峰残雨云间湿，一水斜阳岛外明。","树隔钓歌分浦出，风移帆影近窗行。","綵衣白发宜春酒，更喜田园乐事成。"]},{"t":"二月望日湖上值风","f":"七言律诗","c":["疾风吹浪满重湖，云掩西山一半无。","黄帽牵船依岸过，苍头按鹘绕林呼。","莺花世界如春梦，烟雨楼台似画图。","童稚兹游今白发，断桥斜日重踟蹰。"]},{"t":"寄观志能照磨","f":"七言律诗","c":["鳌背三山最上峰，美人手把玉芙蓉。","仗围泰畤传宵燎，漏下层城踏晓钟。","锦瑟无尘飞刻雁，金壶有墨洒雕龙。","老怀已托王郎道，早晚归营北涧松。"]},{"t":"十二月二十七日雪寒奉旨赐宴史局","f":"七言律诗","c":["圣主恩荣六赐筵，玉音躬听相臣宣。","史裁东观何殊汉，人在瀛洲总是仙。","御酒如春浮浩荡，宫花与雪斗婵娟。","微生此日沾休泽，祇望丹宸祝万年。"]},{"t":"初度日病起不能饮诸友载酒集书楼偶赋见意","f":"七言律诗","c":["细雨东风泛晓烟，草痕青过竹篱边。","春当揆度灵均日，老及知非伯玉年。","病眼纷纭花似雾，吟怀跌宕酒如泉。","诸君有意留迂叟，拟买雷塘百亩田。"]},{"t":"题辜德中瑞竹亭","f":"五言古诗","c":["江馆当西澨，山堂向北隅。","旧樊聊补坏，新竹复嘘枯。","嘉此神明劳，森然雨露濡。","贤才世闽海，之子冠洪都。","生意原无息，休徵固有符。","浑涵由地脉，腾达即天衢。","故业诗书远，能官俊造须。","材称人似玉，宾待凤将雏。","照映丘园重，流传赋咏俱。","拟同嘉树传，来作瑞筠图。"]},{"t":"送成礼部谊叔察访守令河南山东","f":"五言古诗","c":["历数开千载，明良会一时。","朝廷严守令，宵旰为黔黎。","南服方多故，东州复阻饥。","郎官膺简拔，使者出询咨。","此命于今重，如君众论推。","直承廉察往，肯作畏难辞。","灵雨随华毂，流风度綵旗。","草兼骢一色，柳与辔同丝。","梁宋分淮甸，青齐并海涯。","政苛嗟虎猛，民散念鸿离。","罢软宁胜任，奸贪只自私。","中牟因雉见，单父得鱼知。","或有隳其职，谁能慎所司。","张弦从急缓，朗鉴各妍媸。","治道诚先务，皇心实在兹。","俱为良吏选，足慰远人思。","空阔青云步，孤高玉树姿。","暂倾冠盖饯，行赴简书期。","事业悬钟鼎，光华映羽仪。","归来前席问，请入史臣词。"]},{"t":"送彭大年真人祀东海东岳东镇","f":"五言古诗","c":["国典崇常祀，名山仰岱宗。","圣王钦所遣，使者肃惟恭。","礼自唐虞秩，神知造化钟。","天门开巀嵲，日观上巃嵷。","零雨行清道，浮云起荡胸。","宿斋分鹤帐，朝飨发鲸钟。","吹溢安歌进，灵来卫仗从。","御香分晻霭，佩玉响瑽瑢。","美荐怀椒糈，精诚奠璧琮。","东流瞻巨海，列镇到诸峰。","瀛岛遥相望，仙人或此逢。","岳祇调虎豹，水怪帖鱼龙。","星坠祠光白，烟涵瑞气浓。","振衣临浚壑，飞盖拂长松。","庶物消馀沴，洪河复故踪。","年祥报齐鲁，地宝出雷澭。","嘉泽群方洽，明时百职供。","回车宜访问，弭节可从容。","世祚祈千亿，元功赞九重。","禁庭归福处，有待颂东封。"]},{"t":"元日灵台官以初四日己酉时享遂以岁除日受誓于中书乃免朝贺纪诗八韵","f":"五言古诗","c":["清庙当春享，彤庭放早朝。","扈鸣更历正，龙集转寅杓。","瑞日开黄道，卿云映绛霄。","八方周象译，九奏舜箫韶。","炉暖香生术，杯红酒泛椒。","新符郁垒换，候琯女夷调。","有待宽书下，行看战甲销。","衰年今可隐，归老故山樵。"]},{"t":"分题送京兆赵耕师尹之临安路帅府照磨得通海湖","f":"五言古诗","c":["万顷平湖碧，浮光映泬㵳。","秀山纯漫影，沧海暗通潮。","瘴黑云相荡，春澄雪未销。","润沾蒙部阔，川合洱河遥。","粳稻收田利，蒲鱼入市饶。","雨归龙气湿，晴浴鹤媒骄。","夹树迷深箐，流花落野椒。","毡来蛮妇漂，船放僰僮桡。","帅阃开荒甸，英才屈下僚。","此心同逝水，日夜向东朝。"]},{"t":"送刘贞庭总管之嘉禾","f":"五言古诗","c":["牧守膺民寄，循良不数公。","使君新建隼，御史近乘骢。","内府声华著，专城控制雄。","老成归物望，清切简宸衷。","紫绶盘铜虎，朱幡拥画熊。","焚香迎父老，骑竹走儿童。","槜李名藩古，勾吴地利通。","粤从师次后，俱在震邻中。","水暗台隍月，云寒鼓角风。","蛮氛犹涨黑，战血未消红。","圣主方图治，台司亦即戎。","频烦纶綍下，次第甲兵空。","公等宜宣力，王臣固匪躬。","关防先武备，国计务农功。","黄霸徵当最，阳城考欲同。","苍旻飘劲气，白日照精忠。","万象天枢北，三山海市东。","旱龙俄作雨，阳凤已鸣桐。","善政风须变，虚襟理自融。","平生经世志，要似节轩翁。"]},{"t":"福唐张氏永思堂","f":"五言古诗","c":["自昔闽多士，吾宗世有人。","共闻两孝子，永慕百年亲。","僾若音容在，巍然栋宇新。","秋筵仍几杖，温鼎自淳珍。","草娱称觞地，花迎戏綵辰。","流芳变春雨，精思动秋旻。","风教关民俗，文章藉史臣。","声诗播休美，正为盛时陈。"]},{"t":"成居竹有书报甥傅君亮至扬州言其家与外表舅吴仲益及妇家二叔学生韩与玉全家无恙喜甚有怀","f":"五言古诗","c":["始得平安信，浑纾怅望心。","争看尺素字，绝胜万黄金。","危甚初秋警，几于平陆沈。","蜂屯昱岭上，豨突浙江浔。","纵尔驱锋镝，宁逃磔斧砧。","官军俄克复，乱首即成擒。","城市半焦土，亲朋多好音。","已知生有路，暂免泪沾襟。","老子欢殊剧，家人酒快斟。","狂歌敲手板，醉倒脱头簪。","黎庶思苏息，皇天愿照临。","国威虽震叠，兵气尚萧森。","自顾形骸累，仍嗟岁月侵。","怀归畏吏议，承乏念官箴。","虎豹关非远，龙蛇水更深。","岂无黄石略，虚遣白头吟。","落日耿残雪，浮云生夕阴。","枯萁闻龁马，疏树见栖禽。","松竹荒须理，茅茨破可寻。","前身本道士，不是恋山林。"]},{"t":"送林崇高还武夷山 其一","f":"七言绝句","c":["云岩岩下聘君家，长记宵谈到曙霞。","今日陇头谁洒饭，鹧鸪啼老白桐花。"]},{"t":"送林崇高还武夷山 其二","f":"七言绝句","c":["武夷山中毛竹多，神君一去奈山何。","松风犹带琅璈响，散入遗音作棹歌。"]},{"t":"七月望日徐勉自武林来得两讣音 其一","f":"七言绝句","c":["海舟隔岁望回音，及得回音恨更深。","从此远书无用寄，九原芜没转伤心。"]},{"t":"七月望日徐勉自武林来得两讣音 其二","f":"七言绝句","c":["外来丧逝讣音来，女嫁桐陵亦告哀。","老眼今朝方是哭，百年心事总成灰。"]},{"t":"予京居廿稔始置屋灵椿坊衰老畏寒始制青鼠袍且久乏马始作一车出入皆赋诗自志 其一","f":"七言绝句","c":["五槐浓绿荫门前，东宇西房数十椽。","不是衰翁买屋住，归时留作雇船钱。"]},{"t":"予京居廿稔始置屋灵椿坊衰老畏寒始制青鼠袍且久乏马始作一车出入皆赋诗自志 其二","f":"七言绝句","c":["青鼠毛衣可禦寒，秃襟空袖放身宽。","遮头更著狐皮帽，好个侬家老契丹。"]},{"t":"予京居廿稔始置屋灵椿坊衰老畏寒始制青鼠袍且久乏马始作一车出入皆赋诗自志 其三","f":"七言绝句","c":["浅浅轻车稳便休，何须高盖与华辀。","短辕不作王丞相，下泽聊为马少游。"]},{"t":"读瀛海喜其绝句清远因口号数诗示九成皆寔意也 其一","f":"七言绝句","c":["一日粮船到直沽，吴罂越布满街衢。","新诗将作如千首，为问郯郎有买无。"]},{"t":"读瀛海喜其绝句清远因口号数诗示九成皆寔意也 其二","f":"七言绝句","c":["接粮御史性情真，断事官来苦怒嗔。","索酒索钱横生事，遭风遭浪肯知人。"]},{"t":"读瀛海喜其绝句清远因口号数诗示九成皆寔意也 其三","f":"七言绝句","c":["客窗昨夜北风高，犹似乘船海上涛。","明发先宜觅貂鼠，唤人来作禦寒袍。"]},{"t":"读瀛海喜其绝句清远因口号数诗示九成皆寔意也 其四","f":"七言绝句","c":["虎贲坐甲夜传更，千步廊街鼓柝声。","未许离人眠得熟，马蹄车铎又天明。"]},{"t":"读瀛海喜其绝句清远因口号数诗示九成皆寔意也 其五","f":"七言绝句","c":["拂郎之马走千里，独立长嘶凡马空。","昔在江南看图画，今来天厩识真龙。"]},{"t":"读瀛海喜其绝句清远因口号数诗示九成皆寔意也 其六","f":"七言绝句","c":["赛娘十五解新声，杨柳腰肢怯啭莺。","好写潘郎胡十八，教伊传唱满京城。"]},{"t":"读瀛海喜其绝句清远因口号数诗示九成皆寔意也 其七","f":"七言绝句","c":["长川妓子早晨来，戴笠骑驴帕拥腮。","总在狭斜坊里住，教坊日日听差回。"]},{"t":"读瀛海喜其绝句清远因口号数诗示九成皆寔意也 其八","f":"七言绝句","c":["杖履寻花虎丘寺，壶觞按曲馆娃宫。","阿成杀受吴中乐，请入风沙海浪中。"]},{"t":"读瀛海喜其绝句清远因口号数诗示九成皆寔意也 其九","f":"七言绝句","c":["结束黄骝粉画鞯，更投西市买长鞭。","知侬已有南归日，户部来催助燕钱。"]},{"t":"读瀛海喜其绝句清远因口号数诗示九成皆寔意也 其十","f":"七言绝句","c":["大风尘土涨天飞，遮眼乌纱拍马归。","还是洞庭湖水好，待郎来浣旧征衣。"]},{"t":"大年小景 其一","f":"七言绝句","c":["一川风柳绿傞傞，古木茅茨近涧阿。","汉上无人船不渡，水禽飞处夕阳多。"]},{"t":"大年小景 其二","f":"七言绝句","c":["春澹空山不自聊，幽花老画国香销。","只今愁绝沅湘路，谁与侯芭赋楚招。"]},{"t":"大年小景 其三","f":"七言绝句","c":["采采幽芳不盈把，好收风露入铜瓶。","虎丘老衲今何在，思见兰芽石上青。"]},{"t":"幼闇宗师以诗招赏海棠文申有诗见约次韵 其一","f":"七言绝句","c":["自是仙家春日迟，紫绵无数袅柔丝。","凭君多置看花酒，肺渴如今似漏卮。"]},{"t":"幼闇宗师以诗招赏海棠文申有诗见约次韵 其二","f":"七言绝句","c":["环枢堂上迟明来，要向花前不放杯。","只恐狂风无顾藉，尽将春色委苍苔。"]},{"t":"幼闇宗师以诗招赏海棠文申有诗见约次韵 其三","f":"七言绝句","c":["好怀日近少曾开，心忆湖山曾屡回。","不是故人多雅致，谁能相约看花来。"]},{"t":"廉子祐归省金陵且就秋试作三绝句赠别 其一","f":"七言绝句","c":["故园归思浩无涯，更听啼鹃恼客怀。","后夜月明应有梦，先随潮水过秦淮。"]},{"t":"廉子祐归省金陵且就秋试作三绝句赠别 其二","f":"七言绝句","c":["陌上吹衣柳絮风，凭君莫放酒杯空。","归舟总是伤情处，一路残山剩水中。"]},{"t":"廉子祐归省金陵且就秋试作三绝句赠别 其三","f":"七言绝句","c":["自昔高科取俊英，布衣徒步到公卿。","庙堂今日求材切，正待诸君策治平。"]},{"t":"王杲东白墨兰樵题诗用韵其左并寓所怀","f":"七言绝句","c":["光风叶叶露香新，欲采幽芳惜暮春。","几度玉笙吹夜月，潇湘云断不逢人。"]},{"t":"早出北城迎社稷香舆","f":"七言绝句","c":["我如老马怯征鞍，推起东窗欲起难。","昨日风雷驱雹过，满衣明月五更寒。"]},{"t":"偶成二绝句简鲁威学士 其一","f":"七言绝句","c":["云物凄凉小雪初，半庭残菊蝶来疏。","连朝笔砚多忙事，借得东泉学士书。"]},{"t":"偶成二绝句简鲁威学士 其二","f":"七言绝句","c":["病起头颅不可风，南窗晴日正融融。","天怜老境无差使，乞与诗篇酒盏中。"]},{"t":"小游仙词 其一","f":"七言绝句","c":["清华公子并骑龙，直过蓬莱第一峰。","亲见海中城阙好，半栽玉树半芙蓉。"]},{"t":"小游仙词 其二","f":"七言绝句","c":["五色烟中玉女窗，凤歌鸾舞一双双。","除是飞琼方教得，紫箫吹彻不成腔。"]},{"t":"小游仙词 其三","f":"七言绝句","c":["来不分明去不言，红椒花露湿妆痕。","巫娥已逐梦魂断，十二碧峰愁暮猿。"]},{"t":"小游仙词 其四","f":"七言绝句","c":["月圃群芬次第开，步前红露下瑶阶。","摴蒱偶共真妃博，赌得双头白燕钗。"]},{"t":"小游仙词 其五","f":"七言绝句","c":["道人寄我紫逻山，时复卖药来人间。","石潭薄晚有龙斗，满谷湿云无路还。"]},{"t":"小游仙词 其六","f":"七言绝句","c":["五岳真官立帐前，露芜香霭落琼筵。","夜深醮罢各归去，一一马声嘶上天。"]},{"t":"小游仙词 其七","f":"七言绝句","c":["美人临水笑相邀，自解罗巾掷作桥。","同觅云间仙伴侣，杏花坛上听吹箫。"]},{"t":"小游仙词 其八","f":"七言绝句","c":["月帐新开蕊辇过，桂花凉露洒天河。","双星一夜叙离别，狼藉碧莲秋露多。"]},{"t":"招韩伯清泛湖 其一","f":"七言绝句","c":["南园携手赏芳红，唤取能歌盛小丛。","传与春风留杏萼，明朝开向曲声中。"]},{"t":"招韩伯清泛湖 其二","f":"七言绝句","c":["段桥春水绿初柔，便有群凫来上游。","好借鸱夷盛酒去，玉箫吹上画船头。"]},{"t":"人雁吟（悯饥也）二章 其二","f":"曲","c":["雁啄啄，飞搏搏。","江边虞人缚矰?，人饥处处规尔肉。","岂知雁饥肉更薄，城中卖雁不直钱，市头籴米斗五千。","妻儿煮糜不敢饱，朝朝射雁出江边。","不闻关中易子食，空里无人骨生棘。","县官赈济文字来，汝尚可生当自力。"]},{"t":"周昉按乐图","f":"曲","c":["美人按乐春昼长，绿鬟翠袖双鸣珰。","玉箫高吹银管笛，二十三弦啼凤凰。","后来知是调筝手，窈窕傍听曾误否？","《梁州》遍彻《六么》翻，此曲惟应天上有。","行云不动暮雨生，流莺瞥目飞鸿惊。","宫驰羽疾争新声，花月六宫无限情。","君不见《后庭》《玉树》梨园谱，日日君王醉歌舞。","一朝鼙鼓动地来，禄儿危似韩擒虎。","丹青纵复王何益。","由来嗜音必亡国。","田家机杼人不知，好写《豳风》劝蚕织。"]},{"t":"杏叶黄","f":"曲","c":["杏叶黄，杏叶黄。","胡蝶双飞来，飞来东家墙。","东家女儿绣衣裳，可怜胡蝶惜流芳，妆鬓无心苏合香。","起弹床上筝，自歌杏叶黄。","杏叶青时君去乡，坐见黄落思断肠，安得致之在我傍。","君不来，天繁霜。"]},{"t":"寒漏明次韵王子常","f":"曲","c":["寒漏明，时一聆。","夜长不能寐，月色明阶庭。","西风落叶争秋声，鸡啼未啼霜满城。","城中有思妇，正促征衣成。","东家西家砧杵急，使我起坐时时惊。","归心如废弓，屡折不可檠。","寒漏明，时一聆。"]},{"t":"游石头城清凉寺用天锡题壁诗韵","f":"五言律诗","c":["扪萝上绝顶，岚气湿缤纷。","日色不到地，树阴浑似云。","僧归过岭见，樵唱逆风闻。","更待诗人醉，狂书白练裙。"]},{"t":"禖台","f":"五言律诗","c":["嫔御亲弓韣，祠禖有古台。","瑶池今寂寞，玄鸟自归来。","鼎再移支子，星俄坼上台。","兴亡关历数，祇遣后人哀。"]},{"t":"皇舅墓","f":"七言古诗","c":["青州刺史河上坟，坟不可识碑仍存。","维舟上读半磨灭，使君乃缘戚里恩。","当时赐葬宜过厚，冢阙树立须雄尊。","岂知陵谷有迁变，石马尽没龟趺蹲。","驿夫指我元傍岸，县官恐坠移高原。","岸滨往往多古冢，零落空馀秋草根。","至今父老传谶记，野人之语那足论。","我疑其藏必深锢，或谓已被湍流吞。","安得壮士塞河水，万古莫令开墓门。"]},{"t":"辱井石阑","f":"七言律诗","c":["好事能收断石存，摩挲堪惜古云根。","楼空野寺钟何在，宫浸寒芜井已眢。","古篆半馀阑上字，妖姬犹有梦中魂。","试扪洼处红犹湿，不是胭脂是血痕。"]},{"t":"上元夜雨","f":"七言律诗","c":["门外东风惊落尘，夜寒街鼓断无人。","江山长抱千年恨，雨雪虚销一月春。","红蜡光深行酒罢，玉龙声急落梅频。","邻翁闻说儿时事，何异繁华梦里身。"]},{"t":"壬申元日大雪二日立春晴景豁然春宴有作","f":"七言律诗","c":["白雪青天映日红，楼台高下玉山中。","盘蔬晓送冰丝脆，钗杏春生蜡带融。","北斗龙杓回后夜，东皇鸾辂驾灵风。","何如得接云霄上，一看烟花绕禁宫。"]},{"t":"露坐","f":"七言绝句","c":["官街人静鼓鼕鼕，独坐中庭满扇风。","堕地一丝和露湿，青虫悬在月明中。"]},{"t":"宋徽宗画栀禽","f":"七言绝句","c":["龙沙魂断梦华空，遗墨凄凉扇面中。","三十六宫恩怨尽，更无花鸟诉秋风。"]},{"t":"马上望江南诸峰","f":"七言绝句","c":["浮云散尽暮天空，遥见江南数十峰。","安得夸娥两神力，为分苍翠过淮东。"]},{"t":"朱翁子负薪卷","f":"七言绝句","c":["富贵危机解杀身，是非千古付樵人。","当时长史魂应悔，不向山中只负薪。"]},{"t":"题兰","f":"七言绝句","c":["鶗鴂声中花片飞，楚兰遗思独依依。","春风先自悲芳草，惆怅王孙又不归。"]},{"t":"题王蕺隐画山水","f":"七言绝句","c":["额黄销尽玉婵娟，翠袖凝愁倚暮烟。","旧日汉宫三十六，更无秋露泣铜仙。"]},{"t":"题赵仲穆江圃归帆图","f":"七言绝句","c":["西施浦头鸿雁声，苧萝山下于菟行。","前村路暗愁未到，回首海天秋月生。"]},{"t":"今我不乐三章章五句 其一","f":"七言古诗","c":["今我不乐思故山，虎豹盘踞愁难攀。","岂无壮士藏□间，谁能西乡发一矢，畏途如此何由还。"]},{"t":"今我不乐三章章五句 其二","f":"楚辞体","c":["鸱鸮夜鸣兮天似漆，烟际争头小星出。","破窗无灯望白日，东方未明起揽衣，风雨何来忽萧瑟。"]},{"t":"今我不乐三章章五句 其三","f":"七言古诗","c":["月白西南星宿稀，巷无行人蝙蝠飞。","步檐萧萧露沾衣，目断天涯遍芳草，王孙不归春自归。"]},{"t":"紫檀筚篥曲赠善吹者任子中","f":"曲","c":["君不见龟兹乐工能新声，截竹插芸吹月明。","黄沙碛里橐驼断，花门山上浮云生。","夜深促节转悲壮，只愁崩倒赤连城。","石崖划裂水泉涌，海鹘怒戛风力竦。","贾胡惊起怨思长，都护罢饮精魂动。","传之中国久更新，任郎妙解尤绝伦。","镂檀作管如紫玉，连蝉锦囊金作束。","等閒未肯出向人，为我酒边吹一曲。","落花撩乱游丝起，流莺无言蛱蝶死。","当头独发调最高，响来直在青云里。","顿令阳春变秋色，佶栗吴霜飞绕指。","教坊弦索惨不骄，歌舞堂中静如水。","古谁得名今莫比，讵数阳陶与关李。","南音北谱此正繁，含嚼纷纭徒聒耳。","我心感慨未易降，已觉满坐寒摐摐。","安得酒船百斛乘月去，数声吹黑鱼龙江。"]},{"t":"六月廿六日泛湖遇雨","f":"七言律诗","c":["忽雷矆䁡奔雨急，山灵昼藏水仙泣。","螮蝀下饮湖水立，恍惚疑有蛟龙入。","疾风吹裂南天青，芙蓉放香薰水腥。","吴歌楚舞方烂熳，更尽花间双玉瓶。"]},{"t":"蟠松引","f":"曲","c":["何年风雨拔老湫，乾卧千岁长黄虬。","垂胡磥碨髯怒磔，雷火不敢烧其瘤。","卒然一见势欲攫，况可手扪双角鯄。","悬知根受元气大，跁跒力争崖石碍。","樛枝互错横铁□，弓纽□张攲羽盖。","低无玄鹤寄巢居，幽有苍夔出光怪。","故人语似灵岩山，卧云之树同屈蟠。","身横百围容客踞，声入半空生昼寒。","毕宏韦偃世无有，画史掉首应嗟难。","彼当为甲此为乙，造化偏钟两奇崛。","爱之欲□重摩挲，图赞还须怪魁笔。","君不见龙门寺千丈。","齐耸巃嵷荫白日。"]},{"t":"题林若拙画孤山图","f":"七言古诗","c":["孤山处士孤吟处，水影月香馀妙句。","鹤声叫绝陵谷秋，修竹祠空几愁暮。","白云生根著湖水，力尽西风飞不去。","何人鞭石下崔嵬，中流截断鱼龙路。","丹青楼观花如雾，葵麦无情仅前度。","何似槎牙半死枝，百年犹是咸平树。","荒烟坏柳断桥冰，宿葑田深散鸥鹭。","画船歌舞不须臾，落落诗名自如故。","野人亦有沧洲趣，安得数椽相近住。","长待天寒欲雪时，杖藜来访梅边墓。"]},{"t":"题吴性存所藏赵仲穆竹枝双蝶图与玉山同赋","f":"七言绝句","c":["满丛鲜碧露团香，院落春红过野芳。","蛱蝶一生花里活，飞来还恋竹风凉。"]},{"t":"西湖冰合","f":"七言律诗","c":["西湖雪厚冰彻底，行人径度如长川。","风吹盐池结阴卤，日射玉田生暖烟。","鱼龙穴里寒更缩，鸥鹭沙头饥可怜。","安得长冰通沧海，我欲三岛求神仙。"]},{"t":"水晶笔架","f":"七言律诗","c":["三峰近列砚池头，光照文房烂不收。","冰壑夜寒龙独卧，雪山春煖兔群游。","彩毫倚阁功应就，银管依栖价未酬。","别有珊瑚新琢样，策勋毕竟是谁优。"]}]};